package com.osrscn;

/** Where AI fallback translations come from. */
public enum AiBackend
{
	/** Local Ollama server ({@code /api/chat}). Free, private, needs a GPU. */
	OLLAMA("本地 Ollama"),
	/** OpenAI-compatible online API ({@code /chat/completions}, Bearer key). DeepSeek/OpenAI/... */
	OPENAI("在线 API");

	private final String label;

	AiBackend(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.osrscn;

/**
 * Preset OpenAI-compatible API providers. Picking one auto-fills the API address; it stays
 * editable. {@link #CUSTOM} leaves it alone.
 */
public enum AiProvider
{
	DEEPSEEK("DeepSeek", "https://api.deepseek.com"),
	SILICONFLOW("硅基流动", "https://api.siliconflow.cn/v1"),
	OPENAI("OpenAI", "https://api.openai.com/v1"),
	CUSTOM("自定义", "");

	private final String label;
	private final String url;

	AiProvider(String label, String url)
	{
		this.label = label;
		this.url = url;
	}

	public String getUrl()
	{
		return url;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.osrscn;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(OsrscnConfig.GROUP)
public interface OsrscnConfig extends Config
{
	String GROUP = "osrscn";

	@ConfigSection(name = "联系作者 / 反馈", description = "加 QQ 群或填写问卷，反馈问题与建议", position = 0)
	String feedback = "feedback";

	@ConfigSection(name = "通用", description = "", position = 1)
	String general = "general";

	@ConfigSection(name = "翻译", description = "", position = 2)
	String translate = "translate";

	@ConfigSection(name = "外观", description = "", position = 3)
	String display = "display";

	@ConfigSection(
			name = "AI 翻译",
			description = "开启后，本地查表缺失的游戏英文文本会发送到你设置的翻译服务器（本地 Ollama 或在线 API）翻译。玩家名永不发送。默认用本地 Ollama。",
			position = 4)
	String ai = "ai";

	@ConfigSection(name = "调试", description = "", position = 6, closedByDefault = true)
	String debug = "debug";

	// ===== 联系作者 / 反馈 =====

	@ConfigItem(
			keyName = "qqGroup",
			name = "QQ 群",
			description = "汉化交流 / 问题反馈 QQ 群号。反馈问卷：https://docs.qq.com/form/page/DWW5BcmpRZmRORFho（侧边栏顶部有一键打开按钮）",
			section = feedback,
			position = 0
	)
	default String qqGroup()
	{
		return OsrscnPlugin.QQ_GROUP;
	}

	@ConfigItem(
			keyName = "loginNotice",
			name = "登录提示",
			description = "每次登录时，在聊天框显示一行插件版本和发布渠道。"
					+ "本插件永久免费，只在 RuneLite 插件库发布，这一行是为了让你认出别处收费转卖的假冒版本。不想看可以关掉。",
			section = feedback,
			position = 3
	)
	default boolean loginNotice()
	{
		return true;
	}

	@ConfigItem(
			keyName = "collectMissing",
			name = "帮忙补全汉化",
			description = "想为汉化出份力就开它。游戏里查不到的文本会存到本地缺词文件"
					+ "（不含聊天，插件不会自动上传），攒一阵点侧边栏「缺词」按钮即可一键提交。",
			section = feedback,
			position = 1
	)
	default boolean collectMissing()
	{
		return false;
	}

	@ConfigItem(
			keyName = "uploadMissing",
			name = "自动上传缺词",
			description = "定期把收集到的缺词自动发送给汉化组，免去手动提交。只发送游戏英文原文"
					+ "和匿名安装 ID（不含聊天、不含账号信息）。开启时会弹窗确认，随时可关。",
			section = feedback,
			position = 2
	)
	default boolean uploadMissing()
	{
		return false;
	}

	// ===== 通用 =====

	@ConfigItem(
			keyName = "toggleHotkey",
			name = "中英切换",
			description = "在中文和英文之间切换",
			section = general,
			position = 0
	)
	default Keybind toggleHotkey()
	{
		return new Keybind(KeyEvent.VK_T, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
			keyName = "clearCacheHotkey",
			name = "清翻译缓存",
			description = "清掉 AI 翻译缓存，重新翻译",
			section = general,
			position = 1
	)
	default Keybind clearCacheHotkey()
	{
		return new Keybind(KeyEvent.VK_C, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK);
	}

	@ConfigItem(
			keyName = "dataBaseUrl",
			name = "翻译数据地址",
			description = "翻译表的下载地址。默认从公开数据仓库下载；国内可改成镜像地址。留空则只用本地缓存。",
			section = general,
			position = 2
	)
	default String dataBaseUrl()
	{
		return "https://raw.githubusercontent.com/Aoldbald/OSRS_CN_Data_Runelite/main/public/zh/";
	}

	// ===== 翻译 =====

	@ConfigItem(
			keyName = "translateMenus",
			name = "菜单",
			description = "翻译右键菜单和左上角悬停的动作文字",
			section = translate,
			position = 0
	)
	default boolean translateMenus()
	{
		return true;
	}

	@ConfigItem(
			keyName = "translateSearchResults",
			name = "搜索结果物品名",
			description = "大交易所和银行搜索时，把候选物品名显示成中文。"
					+ "只打一两个字母时候选很多，一屏几十个名字要现画，配置较低的机器会掉帧，卡就关掉。"
					+ "关掉只影响候选列表，搜索框的提示文字照常是中文。",
			section = translate,
			position = 1
	)
	default boolean translateSearchResults()
	{
		return true;
	}

	@ConfigItem(
			keyName = "translateGameMessages",
			name = "游戏消息",
			description = "翻译聊天框里的游戏消息（物品/NPC 查看、升级、系统提示等）。不影响玩家发言。",
			section = translate,
			position = 2
	)
	default boolean translateGameMessages()
	{
		return true;
	}

	@ConfigItem(
			keyName = "playerChatMode",
			name = "公屏玩家发言",
			description = "其他玩家公共聊天的处理方式（含管理员和自动喊话）。玩家名字任何情况都不翻译。"
					+ "「不翻译」按原频道颜色显示英文；「翻译」直接把英文行替换成中文；"
					+ "「翻译并另起一行」保留英文行，下面另插一条中文翻译（如 OSRS_CN: 玩家名: 你好）。"
					+ "玩家黑话翻译质量不稳，且会占用 AI 翻译队列。",
			section = translate,
			position = 3
	)
	default PlayerChatMode playerChatMode()
	{
		return PlayerChatMode.OFF;
	}

	@ConfigItem(
			keyName = "groupChatMode",
			name = "额外频道玩家发言",
			description = "独立设置 Friends Chat、Clan、Guest、GIM 的玩家发言；不受「公屏玩家发言」影响。"
					+ "默认不翻译；可直接翻译或保留英文另起一行。缺少译文时需开启「启用 AI 翻译」。"
					+ "正文发送至所选 AI 后端：本机 Ollama 在本机处理，在线 API 或远程地址会发送至远端。"
					+ "玩家名保持原样，不发送给 AI。切换后仅翻译新来信。",
			section = translate,
			position = 4
	)
	default PlayerChatMode groupChatMode()
	{
		return PlayerChatMode.OFF;
	}

	// ===== 外观 =====

	@ConfigItem(
			keyName = "mainFontSize",
			name = "对话字号",
			description = "对话文字的中文字号。只影响对话；界面、菜单、悬停提示用固定字号以避免重叠超框。",
			section = display,
			position = 0
	)
	@Range(min = 8, max = 22)
	@Units("pt")
	default int mainFontSize()
	{
		return 14;
	}

	@ConfigItem(
			keyName = "fontPath",
			name = "自定义字体",
			description = "中文字图用的字体文件路径（.ttf/.otf）。留空则用插件内置开源字体（思源黑体 Source Han Sans）。改后即时生效。",
			section = display,
			position = 1
	)
	default String fontPath()
	{
		return "";
	}

	// ===== AI 翻译 =====

	@ConfigItem(
			keyName = "useLocalAi",
			name = "启用 AI 翻译",
			description = "查表没有时，用 AI 翻译缺失文本（后端见下方「AI 后端」）。"
					+ "开启后会把缺失的游戏英文文本发送到你配置的翻译服务器。",
			section = ai,
			position = 0
	)
	default boolean useLocalAi()
	{
		return false;
	}

	@ConfigItem(
			keyName = "aiBackend",
			name = "AI 后端",
			description = "AI 翻译用哪个后端。「本地 Ollama」免费私密但要 GPU；"
					+ "「在线 API」用 DeepSeek/OpenAI 等云端服务，按量付费，会把游戏文本发到该服务商。",
			section = ai,
			position = 1
	)
	default AiBackend aiBackend()
	{
		return AiBackend.OLLAMA;
	}

	@ConfigItem(
			keyName = "aiFillInterface",
			name = "界面缺词 AI 翻译",
			description = "界面里查表没有的文字也用 AI 翻译（含新版技能指南正文的缺句）",
			section = ai,
			position = 2
	)
	default boolean aiFillInterface()
	{
		return true;
	}

	@ConfigItem(
			keyName = "reconstructJournals",
			name = "成就/任务日志整句翻译",
			description = "把成就日志/任务日志里被折行拆碎的任务拼回整句再翻译，并保留完成/要求的颜色区分。"
					+ "需配合「界面缺词 AI 翻译」效果最好；不满意可关闭。",
			section = ai,
			position = 3
	)
	default boolean reconstructJournals()
	{
		return true;
	}

	@ConfigItem(
			keyName = "skillGuideOverlay",
			name = "新版技能指南翻译",
			description = "翻译新版技能指南（OSRS 设置 Enable new-style skill guide interface 的界面）：正文整段重排为中文，"
					+ "图标、链接、维基横幅保持可用。游戏更新若导致排版异常，可临时关闭恢复英文。",
			section = ai,
			position = 4
	)
	default boolean skillGuideOverlay()
	{
		return true;
	}

	@ConfigItem(
			keyName = "aiConcurrency",
			name = "翻译并发数",
			description = "同时进行的 AI 翻译请求数。越大填充越快，但更吃 GPU、可能掉帧（Ollama 需开并行）",
			section = ai,
			position = 5
	)
	@Range(min = 1, max = 6)
	default int aiConcurrency()
	{
		return 1;
	}

	@ConfigItem(
			keyName = "aiPaceMs",
			name = "翻译间隔(ms)",
			description = "每次 AI 翻译之间的最小间隔。越小填充越快、越吃 GPU；越大越省 FPS",
			section = ai,
			position = 6
	)
	@Range(min = 0, max = 1000)
	@Units("ms")
	default int aiPaceMs()
	{
		return 120;
	}

	@ConfigItem(
			keyName = "ollamaUrl",
			name = "Ollama 地址",
			description = "本地 Ollama 服务地址（后端选「本地 Ollama」时使用）",
			section = ai,
			position = 7
	)
	default String ollamaUrl()
	{
		return "http://localhost:11434";
	}

	@ConfigItem(
			keyName = "ollamaModel",
			name = "Ollama 模型",
			description = "用于翻译的模型名（后端选「本地 Ollama」时使用）",
			section = ai,
			position = 8
	)
	default String ollamaModel()
	{
		return "qwen2.5";
	}

	@ConfigItem(
			keyName = "aiProvider",
			name = "API 服务商",
			description = "后端选「在线 API」时使用。选一个常用服务商会自动填好下面的「API 地址」"
					+ "（之后仍可手改）。选「自定义」则自己填地址。",
			section = ai,
			position = 9
	)
	default AiProvider aiProvider()
	{
		return AiProvider.DEEPSEEK;
	}

	@ConfigItem(
			keyName = "apiUrl",
			name = "API 地址",
			description = "OpenAI 兼容接口的基础地址，如 https://api.deepseek.com。"
					+ "插件会自动补 /chat/completions。一般选好「API 服务商」即可自动填。",
			section = ai,
			position = 10
	)
	default String apiUrl()
	{
		return "https://api.deepseek.com";
	}

	@ConfigItem(
			keyName = "apiKey",
			name = "API 密钥",
			description = "服务商给的 API Key（后端选「在线 API」时使用）。保存在本地 RuneLite 配置里，不要分享给别人。",
			section = ai,
			position = 11,
			secret = true
	)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(
			keyName = "apiModel",
			name = "API 模型",
			description = "模型名（后端选「在线 API」时使用），如 deepseek-chat、gpt-4o-mini、Qwen/Qwen2.5-7B-Instruct 等。",
			section = ai,
			position = 12
	)
	default String apiModel()
	{
		return "deepseek-chat";
	}

	@ConfigItem(
			keyName = "testConnection",
			name = "测试连接（点一下）",
			description = "勾一下立即测试当前「AI 后端」是否连通（在线 API 还会验密钥），不消耗 token。"
					+ "勾后会自动弹回，结果用弹窗提示。",
			section = ai,
			position = 13
	)
	default boolean testConnection()
	{
		return false;
	}

	// ===== 调试 =====

	@ConfigItem(
			keyName = "debugMonitor",
			name = "AI 翻译状态",
			description = "侧边栏多出一个「调试」tab，显示 AI 翻译进度（已缓存/翻译中/最近翻译），"
					+ "同时往日志写走查耗时和聊天框控件明细。排查问题时才需要开。",
			section = debug,
			position = 0
	)
	default boolean debugMonitor()
	{
		return false;
	}


}

package com.osrscn;

import com.google.inject.Provides;
import com.osrscn.glyph.GlyphService;
import com.osrscn.hooks.ChatHandler;
import com.osrscn.hooks.DialogueHandler;
import com.osrscn.hooks.InterfaceTranslator;
import com.osrscn.hooks.MenuTranslator;
import com.osrscn.hooks.OverheadHandler;
import com.osrscn.translate.AiTranslator;
import com.osrscn.translate.MissingCollector;
import com.osrscn.translate.MissingUploader;
import com.osrscn.translate.TranslationStore;
import com.osrscn.translate.Translator;
import com.osrscn.ui.HoverTooltipOverlay;
import com.osrscn.ui.LoginBanner;
import com.osrscn.ui.ToggleOverlay;
import com.osrscn.ui.OsrscnPanel;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.externalplugins.PluginHubManifest;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@Slf4j
@PluginDescriptor(
		name = "OSRSCN",
		description = "Lightweight Simplified Chinese translation for OSRS (lookup + local AI translation for missing text)."
)
public class OsrscnPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private KeyManager keyManager;
	@Inject
	private OsrscnConfig config;
	@Inject
	private ConfigManager configManager;
	@Inject
	private ToggleService toggle;
	@Inject
	private TranslationStore store;
	@Inject
	private Translator translator;
	@Inject
	private AiTranslator aiTranslator;
	@Inject
	private MissingCollector missingCollector;
	@Inject
	private MissingUploader missingUploader;
	@Inject
	private DialogueHandler dialogueHandler;
	@Inject
	private MenuTranslator menuTranslator;
	@Inject
	private InterfaceTranslator interfaceTranslator;
	@Inject
	private OverheadHandler overheadHandler;
	@Inject
	private ChatHandler chatHandler;
	@Inject
	private GlyphService glyph;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private HoverTooltipOverlay hoverTooltipOverlay;
	@Inject
	private ToggleOverlay toggleOverlay;
	@Inject
	private LoginBanner loginBanner;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private OsrscnPanel panel;

	// Glyph pre-warm pace: characters registered per client tick. Small enough that the one-off warm
	// (~thousands of chars) stays well under a frame; the lazy path still covers anything not yet warmed.
	private static final int PREWARM_CODEPOINTS_PER_TICK = 8;

	/** Official QQ group. Shown in the side panel and in the login notice. */
	public static final String QQ_GROUP = "978108806";

	// Origin notice printed once per login, so a repackaged/resold copy is easy to spot. Orange is one of
	// the pre-warmed glyph colours, so it needs no extra sprite uploads.
	// The chatbox draws on parchment by default and on the game world when transparency is on, so one
	// colour cannot read on both: pale orange vanishes against parchment, dark red vanishes against the
	// world. Pick per mode, like the client does for its own messages.
	private static final int NOTICE_RGB_OPAQUE = 0x8f1010;
	private static final int NOTICE_RGB_TRANSPARENT = 0xff981f;
	private static final long NOTICE_TIMEOUT_MS = 15_000;

	private boolean announced;
	// volatile: armed from startUp / cleared from shutDown (plugin thread), drained on the client thread
	private volatile boolean noticeDone;  // this login already had its notice handled
	private volatile long noticeDeadline; // >0 while the notice is queued, waiting for its glyphs to upload
	private NavigationButton navButton;
	private final HotkeyListener toggleHotkey = new HotkeyListener(() -> config.toggleHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(() ->
			{
				boolean zh = toggle.toggle();
				if (zh)
				{
					// switching back to Chinese: re-translate chat history; dialogue/interface
					// re-translate themselves on the next tick scan.
					chatHandler.goChinese();
				}
				else
				{
					// switching to English: actively put the original text back so it's instant
					dialogueHandler.restore();
					interfaceTranslator.restore();
					overheadHandler.clear();
					chatHandler.goEnglish();
				}
				toggleOverlay.flash(zh ? "中文" : "English");
			});
		}
	};

	private final HotkeyListener clearCacheHotkey = new HotkeyListener(() -> config.clearCacheHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			translator.clearAiCache();
			toggleOverlay.flash("已清缓存");
		}
	};

	@Provides
	OsrscnConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OsrscnConfig.class);
	}

	private static boolean uiFontPatched = false;
	private static javax.swing.Timer uiFontTimer;

	private static boolean hasCjk(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (s.charAt(i) >= 0x3400 && s.charAt(i) <= 0x9FFF)
			{
				return true;
			}
		}
		return false;
	}

	// Force a CJK-capable font onto any label/button/text component that shows CJK text in a font
	// that can't render it (e.g. RuneLite's @ConfigSection titles are set explicitly to the
	// Latin-only RuneScape font). Latin-only and already-OK components are left untouched.
	private static void fixCjkFonts(java.awt.Component c)
	{
		String text = null;
		if (c instanceof javax.swing.JLabel)
		{
			text = ((javax.swing.JLabel) c).getText();
		}
		else if (c instanceof javax.swing.AbstractButton)
		{
			text = ((javax.swing.AbstractButton) c).getText();
		}
		else if (c instanceof javax.swing.text.JTextComponent)
		{
			text = ((javax.swing.text.JTextComponent) c).getText();
		}
		java.awt.Font f = c.getFont();
		if (text != null && f != null && hasCjk(text) && f.canDisplayUpTo(text) != -1)
		{
			c.setFont(new java.awt.Font(java.awt.Font.SANS_SERIF, f.getStyle(), f.getSize()));
		}
		if (c instanceof java.awt.Container)
		{
			for (java.awt.Component child : ((java.awt.Container) c).getComponents())
			{
				fixCjkFonts(child);
			}
		}
	}

	// macOS' default Swing UI font has no CJK glyphs and no fallback, so RuneLite renders our
	// Chinese config text as tofu boxes. On macOS only: retarget the default UI fonts to logical
	// "SansSerif" (which has a CJK fallback on macOS) for the bulk of the panel, then keep sweeping
	// open windows for any component still showing CJK in a non-CJK font (RuneLite sets some fonts
	// explicitly, e.g. the orange @ConfigSection titles). No-op on Windows/Linux.
	private static void ensureCjkUiFontOnMac()
	{
		if (uiFontPatched
				|| !System.getProperty("os.name", "").toLowerCase(java.util.Locale.ROOT).contains("mac"))
		{
			return;
		}
		uiFontPatched = true;
		javax.swing.SwingUtilities.invokeLater(() ->
		{
			javax.swing.UIDefaults defaults = javax.swing.UIManager.getLookAndFeelDefaults();
			for (Object key : defaults.keySet().toArray())
			{
				if (defaults.get(key) instanceof java.awt.Font)
				{
					java.awt.Font f = (java.awt.Font) defaults.get(key);
					javax.swing.UIManager.put(key,
							new javax.swing.plaf.FontUIResource(java.awt.Font.SANS_SERIF, f.getStyle(), f.getSize()));
				}
			}
			// config panels are built lazily and set some fonts explicitly, so sweep periodically
			uiFontTimer = new javax.swing.Timer(500, e ->
			{
				for (java.awt.Window w : java.awt.Window.getWindows())
				{
					fixCjkFonts(w);
				}
			});
			uiFontTimer.start();
			for (java.awt.Window w : java.awt.Window.getWindows())
			{
				javax.swing.SwingUtilities.updateComponentTreeUI(w);
			}
		});
	}

	// Queued on the EDT after any pending patch runnable, so it also catches a timer created just
	// before shutdown. Resets the guard so a re-enable can re-patch.
	private static void stopMacUiFontSweep()
	{
		javax.swing.SwingUtilities.invokeLater(() ->
		{
			if (uiFontTimer != null)
			{
				uiFontTimer.stop();
				uiFontTimer = null;
			}
			uiFontPatched = false;
		});
	}

	@Override
	protected void startUp()
	{
		ensureCjkUiFontOnMac();
		store.setBaseUrl(config.dataBaseUrl());
		store.loadAsync();
		aiTranslator.preloadAsync();
		glyph.reloadFont();
		keyManager.registerKeyListener(toggleHotkey);
		keyManager.registerKeyListener(clearCacheHotkey);
		overlayManager.add(hoverTooltipOverlay);
		overlayManager.add(toggleOverlay);
		loginBanner.apply();
		addPanel();
		// say so whenever collected words actually leave the machine: silence looks broken, and the
		// person the data belongs to should be able to see it happen
		missingUploader.setUploadListener(rows -> chat("已上传 " + rows + " 条缺词，谢谢"));
		missingUploader.start();
		// enabled mid-session: no LOGGED_IN event is coming, so arm the notice here instead
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			armLoginNotice();
		}
		log.info("OSRSCN started");
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(toggleHotkey);
		keyManager.unregisterKeyListener(clearCacheHotkey);
		overlayManager.remove(hoverTooltipOverlay);
		overlayManager.remove(toggleOverlay);
		loginBanner.remove();
		if (navButton != null)
		{
			panel.stop();
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		// Put the original English back and drop per-session state, so nothing stays translated
		// while the plugin is off and a re-enable starts clean.
		clientThread.invoke(() ->
		{
			dialogueHandler.restore();
			interfaceTranslator.restore();
			overheadHandler.clear();
			chatHandler.goEnglish();
			dialogueHandler.reset();
			interfaceTranslator.reset();
			chatHandler.clear();
		});
		missingUploader.stop();
		missingCollector.stop();
		stopMacUiFontSweep();
		announced = false;
		noticeDone = false;
		noticeDeadline = 0;
		log.info("OSRSCN stopped");
	}

	@Subscribe
	public void onClientTick(ClientTick t)
	{
		if (!announced && store.isLoaded())
		{
			announced = true;
			chat("就绪 " + store.size() + " 条");
			// Pre-warm every translated character's glyph so its first appearance never flashes English
			// while the sprite uploads (the dominant remaining flash cause). Drained a few per tick below.
			glyph.beginPrewarm(store.chineseCodepoints());
		}
		if (glyph.prewarmPending())
		{
			glyph.prewarmStep(PREWARM_CODEPOINTS_PER_TICK);
		}
		if (noticeDeadline > 0)
		{
			tryLoginNotice();
		}
		if (toggle.isChineseEnabled())
		{
			dialogueHandler.translateDialogues();
			overheadHandler.tick();
			chatHandler.tick();
			// Scan every client tick so newly opened interfaces spend less time flashing English.
			// If this ever costs too much, switch to dirty/adaptive scanning here.
			interfaceTranslator.translateOpen();
		}
	}

	@Subscribe
	public void onGameTick(net.runelite.api.events.GameTick t)
	{
		// Slow lane for big miss-heavy lists (world switcher): translated once per game tick instead of
		// the 50x/s client-tick scan, whose repeated lookup misses over hundreds of rows tanked FPS.
		if (toggle.isChineseEnabled())
		{
			interfaceTranslator.translateSlowGroups();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
				chatHandler.clear();
				// only a real logout re-arms the notice: a world hop or a region load goes back to
				// LOGGED_IN without passing through here, so neither re-prints it.
				noticeDone = false;
				noticeDeadline = 0;
				break;
			case LOGGED_IN:
				armLoginNotice();
				break;
			default:
				break;
		}
	}

	/**
	 * Queue the once-per-login origin notice. In English mode nothing is printed and nothing is queued:
	 * the toggle means "keep Chinese out of the game UI", and the same text stays in the side panel.
	 */
	private void armLoginNotice()
	{
		if (noticeDone)
		{
			return;
		}
		noticeDone = true;
		if (config.loginNotice() && toggle.isChineseEnabled())
		{
			noticeDeadline = System.currentTimeMillis() + NOTICE_TIMEOUT_MS;
		}
	}

	/**
	 * Print the notice once its glyphs are uploaded. Glyph sprites go up a cycle after registration, so
	 * right after login toImgTags returns null for a character that is not ready; retry on the next tick
	 * like the chat/interface handlers do, and give up at the deadline so it can never retry forever.
	 */
	private void tryLoginNotice()
	{
		int rgb = client.getVarbitValue(net.runelite.api.gameval.VarbitID.CHATBOX_TRANSPARENCY) != 0
				? NOTICE_RGB_TRANSPARENT
				: NOTICE_RGB_OPAQUE;
		String zh = "<col=" + String.format("%06x", rgb) + ">" + versionLabel()
				+ " 永久免费，只在 RuneLite 插件库发布</col>";
		String msg = glyph.toImgTags(zh, rgb);
		if (msg != null)
		{
			client.addChatMessage(ChatMessageType.CONSOLE, "", "OSRSCN: " + msg, null);
			noticeDeadline = 0;
		}
		else if (System.currentTimeMillis() > noticeDeadline)
		{
			noticeDeadline = 0;
		}
	}

	/**
	 * Version of the running build, read from the Plugin Hub manifest so it always matches the installed
	 * release with no constant to bump. Null when loaded from source (dev client), which has no hub
	 * manifest, or on clients that predate the API.
	 */
	public static String version()
	{
		try
		{
			PluginHubManifest.DisplayData data = ExternalPluginManager.getDisplayData(OsrscnPlugin.class);
			if (data != null && data.getVersion() != null && !data.getVersion().isEmpty())
			{
				return data.getVersion();
			}
		}
		catch (Throwable ignored)
		{
			// no manifest available
		}
		return null;
	}

	/** Short version label for user-facing text. */
	public static String versionLabel()
	{
		String v = version();
		return v == null ? "开发版" : v;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Translate the moment an interface is built - before its first frame is drawn - so it does not
		// flash English for a tick until the per-tick scan catches it. The onClientTick scan stays as the
		// backstop for interfaces whose text is populated later by client scripts. The scan self-scopes
		// and skips already-translated widgets, so the extra calls on open are cheap.
		if (toggle.isChineseEnabled())
		{
			interfaceTranslator.translateOpen();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (ChatHandler.isChatBuildScript(event.getScriptId()))
		{
			chatHandler.beginChatBuild();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (ChatHandler.isChatBuildScript(event.getScriptId()))
		{
			chatHandler.finishChatBuild();
		}
		// Some panels write their English text from a client script when opened / switched to / updated.
		// Translate the affected surface the instant that script finishes (before the frame draws) so it
		// does not flash English until the next per-tick scan. Which scripts map to which surface/targets
		// lives in SurfaceRegistry; this is just the dispatch. One-shot per fire, so hover hit-test cells
		// are untouched (a per-frame redraw of the account summary previously broke its mouseover).
		// NOTE: combat achievements (CaTasks) is intentionally not handled here - it resists draw-time
		// widget rewrites, so it is handled via overlay rendering instead.
		if (!toggle.isChineseEnabled())
		{
			return;
		}
		interfaceTranslator.translateForScript(event.getScriptId());
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if ("chatMessageBuilding".equals(event.getEventName()))
		{
			chatHandler.captureChatLine(client.getIntStack(), client.getIntStackSize());
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		// spell tooltip and other per-frame-rewritten widgets must be re-translated after their
		// client scripts run each frame, or our text is overwritten before it is drawn.
		if (toggle.isChineseEnabled())
		{
			interfaceTranslator.translateRedraw();
			chatHandler.refreshNativeColors();
			// Menu hover is drawn per frame by the client; match that cadence while still retrying
			// not-yet-uploaded glyphs without reopening the menu.
			if (config.translateMenus())
			{
				menuTranslator.retranslateOpenMenu();
			}
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (toggle.isChineseEnabled() && config.translateMenus())
		{
			menuTranslator.handleMenuOpened(event);
		}
	}

	// run before other plugins so they see the original English option/target (e.g. the core Examine
	// plugin needs "Examine" to show vendor/GE prices). The game executes by opcode, so this is invisible.
	@Subscribe(priority = 1)
	public void onMenuOptionClicked(net.runelite.api.events.MenuOptionClicked event)
	{
		if (toggle.isChineseEnabled() && config.translateMenus())
		{
			menuTranslator.restoreForClick(event.getMenuEntry());
		}
	}

	@Subscribe
	public void onChatMessage(net.runelite.api.events.ChatMessage event)
	{
		// Always forward: in English mode the handler only tracks game messages, so a later
		// switch to Chinese can translate lines that arrived while the toggle was off.
		chatHandler.handle(event);
	}

	@Subscribe
	public void onOverheadTextChanged(net.runelite.api.events.OverheadTextChanged event)
	{
		if (toggle.isChineseEnabled())
		{
			overheadHandler.handle(event);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!OsrscnConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		String key = event.getKey();
		if ("aiBackend".equals(key) || "ollamaModel".equals(key) || "apiModel".equals(key)
				|| "ollamaUrl".equals(key) || "apiUrl".equals(key) || "apiKey".equals(key))
		{
			// Synchronous invalidation retains rapid model round trips before the next lookup.
			aiTranslator.configurationChanged();
		}
		if ("playerChatMode".equals(key) || "groupChatMode".equals(key))
		{
			// ConfigChanged is synchronous on its caller's thread. Record every transition now,
			// including reset (null newValue), so OFF -> ON cannot outrun client-thread cleanup.
			chatHandler.playerChatModeChanged(key);
			clientThread.invoke(chatHandler::discardRevokedPlayerMessages);
			return;
		}
		if (key != null && key.startsWith("panel"))
		{
			return; // panel UI state (collapse / show-English): not a translation setting
		}
		panel.onConfigChanged(); // show/hide the debug section
		// Picking an API provider preset auto-fills the API address (still user-editable afterwards).
		if ("aiProvider".equals(key) && config.aiProvider() != AiProvider.CUSTOM)
		{
			configManager.setConfiguration(OsrscnConfig.GROUP, "apiUrl", config.aiProvider().getUrl());
		}
		// "测试连接" is a checkbox acting as a button: tick -> reset to off, run the no-token test, pop the result.
		if ("testConnection".equals(key) && config.testConnection())
		{
			configManager.setConfiguration(OsrscnConfig.GROUP, "testConnection", false);
			aiTranslator.testConnection((ok, msg) -> javax.swing.SwingUtilities.invokeLater(() ->
					javax.swing.JOptionPane.showMessageDialog(null, msg, "OSRSCN AI 连接测试",
							ok ? javax.swing.JOptionPane.INFORMATION_MESSAGE : javax.swing.JOptionPane.WARNING_MESSAGE)));
		}
		// Explicit consent gate for the voluntary missing-word upload: turning the toggle on pops a
		// dialog spelling out what is sent; declining flips it straight back off. Accepting also turns
		// on the collector (uploading without collecting would silently do nothing).
		if ("uploadMissing".equals(key) && config.uploadMissing())
		{
			javax.swing.SwingUtilities.invokeLater(() ->
			{
				int choice = javax.swing.JOptionPane.showConfirmDialog(null,
						"开启后，插件会定期把缺词文件里的内容自动发送给汉化组，\n"
								+ "用于补全翻译。发送的只有：游戏英文原文 + 匿名安装 ID。\n"
								+ "不含聊天记录、不含账号信息。随时可以关闭此开关。\n\n"
								+ "确定开启吗？（会同时开启「帮忙补全汉化」收集开关）",
						"自动上传缺词", javax.swing.JOptionPane.OK_CANCEL_OPTION);
				if (choice == javax.swing.JOptionPane.OK_OPTION)
				{
					configManager.setConfiguration(OsrscnConfig.GROUP, "collectMissing", true);
				}
				else
				{
					configManager.setConfiguration(OsrscnConfig.GROUP, "uploadMissing", false);
				}
			});
		}
		// Only re-render when a setting that changes glyph output changed. Other settings
		// (AI params, toggles, data URL) take effect on the next translation without dropping
		// the whole glyph cache and re-walking every interface.
		if ("fontPath".equals(key) || "mainFontSize".equals(key))
		{
			glyph.reloadFont();
			// reset() now reverts 860 widgets, so it must run on the client thread (this event fires on the EDT)
			clientThread.invoke(() ->
			{
				dialogueHandler.reset();
				interfaceTranslator.reset();
			});
			// reloadFont cleared the glyph cache: re-warm so the new font/size doesn't flash on first use.
			if (store.isLoaded())
			{
				glyph.beginPrewarm(store.chineseCodepoints());
			}
		}
		// Turning the new-style skill guide translation off must actively hand the page back to the client,
		// or the last laid-out Chinese stays frozen on screen with no pass left to clean it up.
		if ("skillGuideOverlay".equals(key) && !config.skillGuideOverlay())
		{
			clientThread.invoke(interfaceTranslator::revertSkillGuide);
		}
	}

	/** Side panel is always available; the debug section inside it is gated on the config flag. */
	private void addPanel()
	{
		navButton = NavigationButton.builder()
				.tooltip("OSRS 汉化")
				.icon(navIcon())
				.priority(7)
				.panel(panel)
				.build();
		clientToolbar.addNavigation(navButton);
		panel.start();
	}

	private BufferedImage navIcon()
	{
		BufferedImage img = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		java.awt.Graphics2D g = img.createGraphics();
		g.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
				java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(java.awt.Color.WHITE);
		g.setFont(new java.awt.Font(java.awt.Font.SANS_SERIF, java.awt.Font.BOLD, 20));
		java.awt.FontMetrics fm = g.getFontMetrics();
		String s = "中";
		g.drawString(s, (24 - fm.stringWidth(s)) / 2, (24 - fm.getHeight()) / 2 + fm.getAscent());
		g.dispose();
		return img;
	}

	private void chat(String zh)
	{
		// glyphs register a cycle late, so toImgTags is null on first use; retry until ready
		clientThread.invokeLater(() ->
		{
			String msg = glyph.toImgTags(zh, 0xffff00);
			if (msg == null)
			{
				return false; // not ready yet, retry next cycle
			}
			// CONSOLE (not GAMEMESSAGE): a local notice that other plugins' chat parsers ignore, so our
			// "ready" line can't trip e.g. the Loot Tracker trying to parse it as a drop message.
			client.addChatMessage(ChatMessageType.CONSOLE, "", "OSRSCN: " + msg, null);
			return true;
		});
	}
}

package com.osrscn;

/** How other players' supported chat channels are handled. Player names are never translated. */
public enum PlayerChatMode
{
	/** Leave player chat in English using that channel's native colour. */
	OFF("不翻译"),
	/** Translate the message in place (the English line becomes Chinese). */
	INLINE("翻译"),
	/** Keep the English line and add a separate Chinese line below it (e.g. "OSRS_CN: Name: 你好"). */
	INSERT("翻译并另起一行");

	private final String label;

	PlayerChatMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

