package com.osrscn.glyph;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.osrscn.OsrscnConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.game.ChatIconManager;

/**
 * Renders Simplified Chinese characters to inline chat-icon images so they can be drawn on the
 * native OSRS UI via {@code <img=N>} tags. Glyphs are generated on demand from a bundled OFL CJK font
 * (no pre-rendered atlas) and cached per (size, colour, codepoint).
 *
 * <p>Three sizes are used: {@link #dialogueSize()} (user-configurable) for dialogue, a fixed
 * {@link #uiSize()} for interface/menus/chat, and a smaller fixed {@link #smallSize()} for hover
 * tooltips and cramped info boxes. Glyphs keep the font's top leading (no top crop) so they sit on
 * the native text baseline rather than floating up.
 *
 * <p>{@link ChatIconManager#registerChatIcon} uploads the sprite on the next client cycle, so the
 * icon's {@code <img>} index is not valid the instant we register. We therefore cache the
 * registration id (stable) and resolve the index fresh on each use; {@link #toImgTags} returns
 * {@code null} while any glyph in the string is still pending, so the caller retries next tick.
 *
 * <p>Use on the client thread.
 */
@Slf4j
@Singleton
public class GlyphService
{
	private static final String CROP_REF = "国中永鬱"; // dense glyphs that span the full ink box
	// CJK closing punctuation that must not start a wrapped line (kinsoku): keep it with the
	// preceding glyph so a line never begins with a stray comma/period/percent/bracket.
	private static final String NO_LEADING = "、。，．；：！？）｝】》」』〉〕…—·％”’";
	private static final int FAILED = -2; // font cannot render this codepoint (permanent)

	// Emergency fallback only: the real default is the bundled OFL font (see BUNDLED_FONT). These
	// families are used solely when no custom path, external drop-in, or bundled font is present. Non-free
	// system fonts (Microsoft YaHei = Founder, ...) are deliberately excluded so we never rasterise them.
	private static final String[] FONT_CANDIDATES = {
			"Source Han Sans SC", "思源黑体", "Noto Sans CJK SC", "Noto Sans SC", "PingFang SC", "Heiti SC"
	};

	// The default glyph font: Source Han Sans SC (SIL Open Font License) bundled in the JAR, so Chinese
	// renders for every user out of the box (including those without a system CJK font). See OFL-1.1.txt.
	private static final String BUNDLED_FONT = "/com/osrscn/SourceHanSansSC-Regular.otf";

	// Optional external drop-in: an .otf/.ttf placed here overrides the bundled font without touching config.
	private static final File FONT_DIR = new File(RuneLite.RUNELITE_DIR, "osrscn/font");

	@Inject
	private ChatIconManager chatIconManager;
	@Inject
	private OsrscnConfig config;

	// Only dialogue follows the user's size setting; all other surfaces use fixed conservative sizes so
	// dense UI never overflows or mixes visibly different sizes (skill/prayer/HP vs the rest).
	private static final int UI_SIZE = 11;    // interface / menus / chat / overhead bubbles
	private static final int SMALL_SIZE = 11; // hover tooltips and cramped info boxes

	// Coverage threshold for flattening an antialiased glyph to a 1-bit mask (see render()).
	// macOS' Java2D antialiases even when the AA hint is OFF, leaving no fully-opaque pixels
	// for RuneLite's IndexedSprite to keep, so small glyphs would render blank. 0x60 keeps
	// thin CJK strokes legible at the tiny in-game sizes.
	private static final int GLYPH_ALPHA_THRESHOLD = 0x60;

	/** Point size for NPC/player dialogue text (the only user-configurable size). */
	public int dialogueSize()
	{
		return clamp(config.mainFontSize());
	}

	/** Fixed point size for interface, menus, chat and overhead bubbles. */
	public int uiSize()
	{
		return UI_SIZE;
	}

	/** Fixed point size for hover tooltips and cramped info boxes (skill/prayer/magic/emote, HP bar). */
	public int smallSize()
	{
		return SMALL_SIZE;
	}

	private static int clamp(int size)
	{
		return Math.max(8, Math.min(28, size));
	}

	/**
	 * The resolved glyph font at {@code size}, or null if none is available. For the rare surface that
	 * draws Chinese with Java2D instead of {@code <img>} tags (the login banner), so it uses the same
	 * font as the in-game glyphs. Call after {@link #reloadFont}.
	 */
	public Font font(int size)
	{
		return fontFor(size);
	}

	// Colours pre-warmed for every translated character so its first appearance never flashes English
	// while the sprite uploads: white (menu/UI), OSRS blue (public chat), yellow (overhead/highlight),
	// near-black (game messages / dialogue / default widget text), and the skill-guide prose orange
	// (whose first-use upload used to hold every freshly opened guide page in English for ~0.5s).
	// Rare widget colours stay lazy.
	private static final int[] PREWARM_COLORS = {0xFFFFFF, 0x0000FF, 0xFFFF00, 0x000000, 0xFF981F};

	private final Map<Long, Integer> regId = new HashMap<>(); // (size,colour,codepoint) -> registration id / FAILED
	private int[] prewarmCps;   // codepoints still to warm (null when idle/done)
	private int[] prewarmSizes; // distinct sizes to warm each codepoint at
	private int prewarmIdx;     // next codepoint index to process
	private final Map<Integer, Font> fonts = new HashMap<>();
	private final Map<Integer, Integer> glyphW = new HashMap<>();
	private final Map<Integer, Integer> glyphH = new HashMap<>(); // cropped ink height per size
	private final Map<Integer, Integer> cropTop = new HashMap<>(); // first ink row to crop from, per size
	private String fontName;
	private boolean fontResolved;
	private Font customBase;      // loaded from config.fontPath(), or null to use the system font

	/** Rendered pixel width of a full-width CJK glyph, for wrap calculations. */
	public int glyphWidth()
	{
		return glyphWidth(uiSize());
	}

	public int glyphWidth(int size)
	{
		Integer cached = glyphW.get(size);
		if (cached != null)
		{
			return cached;
		}
		Font f = fontFor(size);
		int w = (f == null) ? size : Math.max(1, metrics(f).stringWidth("中"));
		glyphW.put(size, w);
		return w;
	}

	/**
	 * How many full-width glyphs of {@code size} fit in {@code widthPx} pixels. Used to insert
	 * {@code <br>} breaks, since a char-image string has no spaces for the client to wrap on. Returns
	 * 0 when nothing fits (callers treat 0 as "no wrap").
	 */
	public int wrapChars(int widthPx, int size)
	{
		int gw = glyphWidth(size);
		return widthPx >= gw ? widthPx / gw : 0;
	}

	/**
	 * Rendered pixel height of a glyph image. Native widget line height is sized for the small bitmap
	 * font, so multi-line char-image text overflows unless the caller raises the line height to this.
	 */
	public int glyphHeight()
	{
		return glyphHeight(uiSize());
	}

	public int glyphHeight(int size)
	{
		Integer cached = glyphH.get(size);
		if (cached != null)
		{
			return cached;
		}
		computeCrop(size);
		return glyphH.get(size);
	}

	/**
	 * Find the shared vertical crop window for a size from dense reference glyphs: the first and last
	 * rows that actually contain ink. OSRS draws inline {@code <img>} aligned to the text baseline, so
	 * cropping away the font's empty top leading and below-baseline descent keeps glyphs from floating
	 * up with a gap underneath, and saves vertical space.
	 */
	private void computeCrop(int size)
	{
		Font f = fontFor(size);
		if (f == null)
		{
			cropTop.put(size, 0);
			glyphH.put(size, size);
			return;
		}
		FontMetrics fm = metrics(f);
		int ascent = fm.getAscent();
		int full = Math.max(1, ascent + fm.getDescent());
		int w = Math.max(1, fm.stringWidth(CROP_REF));

		BufferedImage img = new BufferedImage(w, full, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g.setFont(f);
		g.setColor(Color.WHITE);
		g.drawString(CROP_REF, 0, ascent);
		g.dispose();

		int top = -1;
		int bot = -1;
		for (int y = 0; y < full; y++)
		{
			for (int x = 0; x < w; x++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0)
				{
					if (top < 0)
					{
						top = y;
					}
					bot = y;
					break;
				}
			}
		}
		if (top < 0)
		{
			top = 0;
			bot = full - 1;
		}
		cropTop.put(size, top);
		glyphH.put(size, bot - top + 1);
	}

	/**
	 * Convert a translated string to a renderable one: CJK characters become {@code <img=N>} tags
	 * coloured with {@code colorRgb}; tags, ASCII and whitespace pass through unchanged.
	 *
	 * @return the rendered string, or {@code null} if some glyph is not uploaded yet (retry later)
	 */
	public String toImgTags(String text, int colorRgb)
	{
		return toImgTags(text, colorRgb, 0, uiSize());
	}

	public String toImgTags(String text, int colorRgb, int maxChars)
	{
		return toImgTags(text, colorRgb, maxChars, uiSize());
	}

	/**
	 * @param maxChars insert a {@code <br>} after this many visual characters so long lines wrap
	 *                 inside their widget (a glyph string has no spaces for the client to break on);
	 *                 0 disables wrapping.
	 * @param size     point size to render at ({@link #dialogueSize()}, {@link #uiSize()} or {@link #smallSize()})
	 */
	public String toImgTags(String text, int colorRgb, int maxChars, int size)
	{
		if (text == null || text.isEmpty())
		{
			return text;
		}
		text = normalizeSeparators(text);
		StringBuilder out = new StringBuilder(text.length() * 6);
		int i = 0;
		int len = text.length();
		int lineChars = 0;
		boolean ready = true;
		boolean pendingBreak = false; // wrap limit reached; emit the <br> at the next safe boundary
		int currentColor = colorRgb; // inline <col=..> tags recolour following glyphs; </col> resets
		while (i < len)
		{
			char c = text.charAt(i);
			// a pending wrap break is only safe before a CJK glyph or whitespace, never inside an ASCII
			// run (so "15%" never splits into "1"/"5%") nor before closing punctuation (kinsoku, so a
			// line never starts with a stray "、"); defer past tags too
			if (pendingBreak && c != '<' && (text.codePointAt(i) >= 0x2E80 || Character.isWhitespace(c))
					&& NO_LEADING.indexOf(c) < 0)
			{
				out.append("<br>");
				lineChars = 0;
				pendingBreak = false;
			}
			if (c == '<')
			{
				int end = text.indexOf('>', i);
				if (end != -1)
				{
					out.append(text, i, end + 1);
					if (text.startsWith("<br>", i))
					{
						lineChars = 0;
						pendingBreak = false;
					}
					else if (text.regionMatches(true, i, "<col=", 0, 5))
					{
						currentColor = parseColTag(text, i, end, colorRgb);
					}
					else if (text.regionMatches(true, i, "</col>", 0, 6))
					{
						currentColor = colorRgb;
					}
					i = end + 1;
					continue;
				}
			}
			int cp = text.codePointAt(i);
			int cc = Character.charCount(cp);
			if (cp < 0x2E80) // ascii + latin-ish: keep native
			{
				out.append(text, i, i + cc);
				lineChars++;
				i += cc;
			}
			else
			{
				int id = glyphRegId(cp, currentColor & 0xFFFFFF, size);
				if (id == FAILED)
				{
					out.append(text, i, i + cc); // font can't render: leave literal
					lineChars++;
				}
				else
				{
					int idx = chatIconManager.chatIconIndex(id);
					if (idx >= 0)
					{
						out.append("<img=").append(idx).append('>');
						lineChars++;
					}
					else
					{
						ready = false; // sprite not uploaded yet
					}
				}
				i += cc;
			}
			if (maxChars > 0 && lineChars >= maxChars && i < len)
			{
				pendingBreak = true; // break at the next safe boundary, not mid-token
			}
		}
		return ready ? out.toString() : null;
	}

	/**
	 * Wrap tag-free text into lines by pixel budget: the first line gets {@code firstPx}, later lines
	 * {@code restPx}. A CJK glyph counts {@link #glyphWidth(int)} px, anything else (ASCII, digit,
	 * space) half that. Unbreakable tokens - a maximal non-CJK run ("15%", "1,000,000") or a CJK char
	 * with its trailing {@link #NO_LEADING} punctuation - are measured up front and moved whole to the
	 * next line when they don't fit, so a line never overflows its budget and never starts with closing
	 * punctuation. A token wider than a whole line is placed alone (overshoot accepted, no split).
	 */
	public java.util.List<String> wrapPlain(String plain, int firstPx, int restPx, int size)
	{
		java.util.List<String> lines = new java.util.ArrayList<>();
		if (plain == null || plain.isEmpty())
		{
			return lines;
		}
		plain = normalizeSeparators(plain);
		int gw = glyphWidth(size);
		int half = (gw + 1) / 2;
		int budget = Math.max(firstPx, gw);
		int restBudget = Math.max(restPx, gw);
		StringBuilder line = new StringBuilder();
		int lineW = 0;
		int i = 0;
		int len = plain.length();
		while (i < len)
		{
			// form the next unbreakable token and measure it
			int start = i;
			int tokenW = 0;
			int cp = plain.codePointAt(i);
			if (cp < 0x2E80)
			{
				if (Character.isWhitespace(plain.charAt(i)))
				{
					i++;
					tokenW = half; // a single space: breakable, dropped at a line start
				}
				else
				{
					while (i < len && plain.codePointAt(i) < 0x2E80 && !Character.isWhitespace(plain.charAt(i)))
					{
						tokenW += half;
						i += Character.charCount(plain.codePointAt(i));
					}
				}
			}
			else
			{
				tokenW = gw;
				i += Character.charCount(cp);
			}
			// attach trailing no-leading punctuation so a line never starts with it
			while (i < len && NO_LEADING.indexOf(plain.charAt(i)) >= 0)
			{
				tokenW += plain.codePointAt(i) < 0x2E80 ? half : gw;
				i++;
			}
			String token = plain.substring(start, i);
			if (lineW > 0 && lineW + tokenW > budget)
			{
				lines.add(line.toString());
				line.setLength(0);
				lineW = 0;
				budget = restBudget;
				if (token.trim().isEmpty())
				{
					continue; // drop the whitespace the line broke on
				}
			}
			line.append(token);
			lineW += tokenW;
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	/**
	 * Queue a glyph pre-warm: register (and so start the upload of) every {@code codepoints} character at the
	 * {@link #PREWARM_COLORS} and the sizes actually in use, drained a few per tick by {@link #prewarmStep}.
	 * Registration is the latency-bearing step; doing it ahead of need means the sprite is already uploaded by
	 * the time a surface first draws the character, so it never flashes English. Re-queue after {@link
	 * #reloadFont} (which clears the cache). Call on the client thread.
	 */
	public void beginPrewarm(java.util.Collection<Integer> codepoints)
	{
		if (codepoints == null || codepoints.isEmpty())
		{
			prewarmCps = null;
			return;
		}
		int[] cps = new int[codepoints.size()];
		int k = 0;
		for (int cp : codepoints)
		{
			cps[k++] = cp;
		}
		// distinct sizes only (uiSize and smallSize are usually equal; dialogue follows the config)
		java.util.TreeSet<Integer> sizes = new java.util.TreeSet<>();
		sizes.add(uiSize());
		sizes.add(smallSize());
		sizes.add(dialogueSize());
		int[] sz = new int[sizes.size()];
		int j = 0;
		for (int s : sizes)
		{
			sz[j++] = s;
		}
		prewarmCps = cps;
		prewarmSizes = sz;
		prewarmIdx = 0;
	}

	/** True while a pre-warm queue still has characters to register. */
	public boolean prewarmPending()
	{
		return prewarmCps != null;
	}

	/**
	 * Register up to {@code codepointBudget} more pre-warm characters (all colours/sizes each). Keep the
	 * budget small so the per-tick rasterise cost stays well under a frame. Call from a per-tick hook until
	 * {@link #prewarmPending} is false. Call on the client thread.
	 */
	public void prewarmStep(int codepointBudget)
	{
		if (prewarmCps == null)
		{
			return;
		}
		int end = Math.min(prewarmIdx + codepointBudget, prewarmCps.length);
		for (; prewarmIdx < end; prewarmIdx++)
		{
			int cp = prewarmCps[prewarmIdx];
			for (int size : prewarmSizes)
			{
				for (int color : PREWARM_COLORS)
				{
					glyphRegId(cp, color, size);
				}
			}
		}
		if (prewarmIdx >= prewarmCps.length)
		{
			prewarmCps = null; // drained
		}
	}

	private int glyphRegId(int codepoint, int colorRgb, int size)
	{
		long key = ((long) size << 45) | ((long) colorRgb << 21) | codepoint;
		Integer cached = regId.get(key);
		if (cached != null)
		{
			return cached;
		}
		int id = FAILED;
		try
		{
			BufferedImage img = render(codepoint, colorRgb, size);
			if (img != null)
			{
				id = chatIconManager.registerChatIcon(img);
			}
		}
		catch (Exception e)
		{
			log.warn("glyph render failed for U+{}", Integer.toHexString(codepoint), e);
		}
		regId.put(key, id);
		return id;
	}

	/** Colour-independent 1-bit pixel mask of a rasterized glyph, cached per (size, codepoint). */
	private static final class Mask
	{
		static final Mask EMPTY = new Mask(0, 0, new long[0]);
		final int w;
		final int h;
		final long[] bits; // row-major solid-pixel bitset

		Mask(int w, int h, long[] bits)
		{
			this.w = w;
			this.h = h;
			this.bits = bits;
		}

		boolean solid(int x, int y)
		{
			int i = y * w + x;
			return (bits[i >> 6] & (1L << (i & 63))) != 0;
		}
	}

	private final Map<Long, Mask> masks = new HashMap<>(); // (size,codepoint) -> mask

	private BufferedImage render(int codepoint, int colorRgb, int size)
	{
		Mask m = maskFor(codepoint, size);
		if (m == null)
		{
			return null;
		}
		// pure black collides with the IndexedSprite transparent slot (index 0) and renders blank;
		// nudge it to near-black, which is visually identical.
		int solid = 0xFF000000 | ((colorRgb == 0 ? 0x010101 : colorRgb) & 0xFFFFFF);
		BufferedImage img = new BufferedImage(m.w, m.h, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < m.h; y++)
		{
			for (int x = 0; x < m.w; x++)
			{
				if (m.solid(x, y))
				{
					img.setRGB(x, y, solid);
				}
			}
		}
		return img;
	}

	/** Rasterize a glyph once per (size, codepoint); per-colour sprites just repaint the mask. */
	private Mask maskFor(int codepoint, int size)
	{
		long key = ((long) size << 21) | codepoint;
		Mask cached = masks.get(key);
		if (cached != null)
		{
			return cached == Mask.EMPTY ? null : cached;
		}
		Font f = fontFor(size);
		if (f == null || !f.canDisplay(codepoint))
		{
			masks.put(key, Mask.EMPTY);
			return null;
		}
		String s = new String(Character.toChars(codepoint));

		FontMetrics fm = metrics(f);
		int w = Math.max(1, fm.stringWidth(s));
		int ascent = fm.getAscent();
		int full = Math.max(1, ascent + fm.getDescent());

		BufferedImage img = new BufferedImage(w, full, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		// IndexedSprite conversion keeps only fully-opaque pixels. Render aliased (AA off) so
		// Windows/Linux produce crisp fully-opaque glyphs; macOS ignores this hint and antialiases
		// anyway, so coverage is flattened to the 1-bit mask below (which is also what we cache).
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g.setFont(f);
		g.setColor(Color.WHITE);
		g.drawString(s, 0, ascent);
		g.dispose();

		// crop to the shared ink window so glyphs sit tight on the baseline (no top/bottom gap)
		glyphHeight(size); // ensure crop window computed
		int top = Math.min(cropTop.get(size), full - 1);
		int ch = Math.min(glyphH.get(size), full - top);

		long[] bits = new long[(w * ch + 63) >> 6];
		for (int y = 0; y < ch; y++)
		{
			for (int x = 0; x < w; x++)
			{
				int a = (img.getRGB(x, top + y) >>> 24) & 0xFF;
				if (a >= GLYPH_ALPHA_THRESHOLD)
				{
					int i = y * w + x;
					bits[i >> 6] |= 1L << (i & 63);
				}
			}
		}
		Mask m = new Mask(w, ch, bits);
		masks.put(key, m);
		return m;
	}

	/**
	 * Reload the glyph font from {@code config.fontPath()} (a bundled/system-independent .ttf/.otf) and
	 * drop every cached glyph so the new font takes effect immediately. Call at start-up and whenever
	 * the font (or size) setting changes. A blank/invalid path falls back to the system CJK font.
	 */
	public void reloadFont()
	{
		String path = config.fontPath() == null ? "" : config.fontPath().trim();
		// clear caches so glyphs re-render with the new font / size
		fonts.clear();
		regId.clear();
		masks.clear();
		glyphW.clear();
		glyphH.clear();
		cropTop.clear();
		prewarmCps = null; // drop any in-flight pre-warm; the caller re-queues after reloadFont
		customBase = null;
		fontName = null;
		fontResolved = false;
		// Priority: user-configured path > external drop-in (FONT_DIR) > bundled OFL font (JAR) > system CJK.
		File file = !path.isEmpty() ? new File(path) : externalDropInFont();
		if (file != null)
		{
			try
			{
				// TRUETYPE_FONT loads both .ttf and OpenType .otf (CFF included)
				customBase = Font.createFont(Font.TRUETYPE_FONT, file);
				if (!customBase.canDisplay('中'))
				{
					log.warn("OSRSCN: font '{}' can't display CJK, using bundled font", file);
					customBase = null;
				}
				else
				{
					log.info("OSRSCN glyph font: {} ({})", customBase.getFontName(), file);
				}
			}
			catch (Exception e)
			{
				log.warn("OSRSCN: failed to load font '{}', using bundled font", file, e);
				customBase = null;
			}
		}
		// Default: the OFL font bundled in the JAR, so Chinese renders even without any system CJK font.
		if (customBase == null)
		{
			try (InputStream in = GlyphService.class.getResourceAsStream(BUNDLED_FONT))
			{
				if (in != null)
				{
					customBase = Font.createFont(Font.TRUETYPE_FONT, in);
					if (!customBase.canDisplay('中'))
					{
						customBase = null;
					}
					else
					{
						log.info("OSRSCN glyph font: bundled {}", customBase.getFontName());
					}
				}
			}
			catch (Exception e)
			{
				log.warn("OSRSCN: failed to load bundled font, using system font", e);
				customBase = null;
			}
		}
	}

	/**
	 * Optional external drop-in font in {@code ~/.runelite/osrscn/font/}: lets a user swap the glyph font
	 * without setting a config path. Overrides the bundled font. Returns the first {@code .otf}/{@code .ttf}
	 * found, or null (the common case), in which case the bundled JAR font is used.
	 */
	private static File externalDropInFont()
	{
		File[] files = FONT_DIR.listFiles((dir, name) ->
		{
			String n = name.toLowerCase(java.util.Locale.ROOT);
			return n.endsWith(".otf") || n.endsWith(".ttf");
		});
		if (files == null || files.length == 0)
		{
			return null;
		}
		java.util.Arrays.sort(files);
		return files[0];
	}

	private Font fontFor(int size)
	{
		Font cached = fonts.get(size);
		if (cached != null)
		{
			return cached;
		}
		Font f;
		if (customBase != null)
		{
			f = customBase.deriveFont((float) size);
		}
		else
		{
			resolveFontName();
			if (fontName == null)
			{
				return null;
			}
			f = new Font(fontName, Font.PLAIN, size);
		}
		fonts.put(size, f);
		return f;
	}

	private void resolveFontName()
	{
		if (fontResolved)
		{
			return;
		}
		fontResolved = true;
		for (String name : FONT_CANDIDATES)
		{
			Font candidate = new Font(name, Font.PLAIN, 12); // probe size; family is what matters here
			if (candidate.getFamily().equalsIgnoreCase(name) && candidate.canDisplay('中'))
			{
				fontName = name;
				log.info("OSRSCN glyph font: {}", name);
				return;
			}
		}
		Font fallback = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
		if (fallback.canDisplay('中'))
		{
			fontName = Font.SANS_SERIF;
			log.info("OSRSCN glyph font: logical SansSerif");
		}
		else
		{
			log.error("OSRSCN: no CJK-capable font found");
		}
	}

	/** Parse the RGB of a {@code <col=RRGGBB>} tag occupying {@code text[start..end]}, or {@code fallback}. */
	private static int parseColTag(String text, int start, int end, int fallback)
	{
		int eq = text.indexOf('=', start);
		if (eq < 0 || eq >= end)
		{
			return fallback;
		}
		int n = 0;
		StringBuilder hex = new StringBuilder(6);
		for (int i = eq + 1; i < end && n < 6; i++)
		{
			char c = text.charAt(i);
			boolean isHex = (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
			if (!isHex)
			{
				break;
			}
			hex.append(c);
			n++;
		}
		if (n == 0)
		{
			return fallback;
		}
		try
		{
			return Integer.parseInt(hex.toString(), 16);
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}

	/**
	 * The OSRS bitmap font can't draw the interpunct used in foreign names (shows as '?'), nor most
	 * other non-ASCII punctuation below the CJK range - ellipsis, em-dash, curly quotes pass through
	 * as garbage glyphs (chars &lt; 0x2E80 are kept native, see the render loop). Full-width Latin
	 * letters and digits have the opposite problem: they enter the glyph path and render with CJK
	 * spacing. Fold only those three compatibility ranges and the known separators to ASCII; leave
	 * full-width punctuation and all other compatibility characters untouched.
	 */
	static String normalizeSeparators(String s)
	{
		boolean dirty = false;
		boolean fullWidthAlphanumeric = false;
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			if ((c >= '０' && c <= '９') || (c >= 'Ａ' && c <= 'Ｚ') || (c >= 'ａ' && c <= 'ｚ'))
			{
				dirty = true;
				fullWidthAlphanumeric = true;
			}
			if (c >= 0x80 && c < 0x2E80)
			{
				dirty = true;
			}
		}
		if (!dirty)
		{
			return s;
		}
		if (fullWidthAlphanumeric)
		{
			StringBuilder folded = new StringBuilder(s.length());
			for (int i = 0; i < s.length(); i++)
			{
				char c = s.charAt(i);
				if ((c >= '０' && c <= '９') || (c >= 'Ａ' && c <= 'Ｚ') || (c >= 'ａ' && c <= 'ｚ'))
				{
					c -= 0xFEE0;
				}
				folded.append(c);
			}
			s = folded.toString();
		}
		return s.replace('·', '.').replace('・', '.').replace('‧', '.').replace('•', '.')
				.replace("…", "...")
				.replace('—', '-').replace('–', '-')
				.replace('“', '"').replace('”', '"')
				.replace('‘', '\'').replace('’', '\'')
				.replace('\u00A0', ' ');
	}

	private static FontMetrics metrics(Font f)
	{
		BufferedImage probe = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = probe.createGraphics();
		g.setFont(f);
		FontMetrics fm = g.getFontMetrics();
		g.dispose();
		return fm;
	}
}

package com.osrscn.hooks;

import com.osrscn.OsrscnConfig;
import com.osrscn.AiBackend;
import com.osrscn.glyph.GlyphService;
import com.osrscn.text.Tags;
import com.osrscn.translate.Translator;
import com.osrscn.translate.AiTranslator;
import com.osrscn.translate.AiTranslator.RequestPermit;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import com.osrscn.PlayerChatMode;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.Point;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Owns the scrolling chat box, which the interface walk deliberately skips (chat is message-node
 * driven, not widget driven).
 *
 * <ul>
 *   <li><b>Player chat</b> (public / friends chat / clan / guest clan / GIM): names are never translated.
 *       {@link PlayerChatMode#OFF} keeps English in the native channel colour;
 *       {@link PlayerChatMode#INLINE} translates the content in place;
 *       {@link PlayerChatMode#INSERT} leaves the English line and adds a separate Chinese line below
 *       it (e.g. {@code "OSRS_CN: Name: 你好"}).</li>
 *   <li><b>Game messages</b> (level-up / quest / system / examine description): translated to
 *       char-images, number-templated, with AI fallback.</li>
 *   <li>Everything else (private chat and channel system notices): left as the game drew it.</li>
 * </ul>
 *
 * <p>Applying a translation writes both {@link MessageNode#setValue} and, when present,
 * {@link MessageNode#setRuneLiteFormatMessage} - the latter is what the client renders for
 * plugin-formatted lines (e.g. the Examine plugin's vendor/GE price, set <i>after</i> our handler
 * runs). Such nodes stay in {@link #pending} and are re-asserted each tick. Translated nodes are
 * remembered so the language toggle can put the chat back to English ({@link #goEnglish()}) and back
 * to Chinese ({@link #goChinese()}).
 */
@Singleton
public class ChatHandler
{
	// Untagged messages are coloured by the engine per message type; baked glyphs must match.
	private static final int PUBLIC_OPAQUE_RGB = 0x0000ff;
	private static final int PUBLIC_TRANSPARENT_RGB = 0x9090ff;
	private static final int AUTOCHAT_OPAQUE_RGB = 0x2020ef;
	private static final int AUTOCHAT_TRANSPARENT_RGB = 0x4040ff;
	private static final int FRIENDSCHAT_OPAQUE_RGB = 0x7f0000;
	private static final int FRIENDSCHAT_TRANSPARENT_RGB = 0xef5050;
	private static final int CLANCHAT_RGB = 0x7f0000;
	private static final int GUESTCLAN_OPAQUE_RGB = 0x007a00;
	private static final int GUESTCLAN_TRANSPARENT_RGB = 0x00d300;
	private static final int GIMCHAT_RGB = 0x7f0000;
	private static final int DIDYOUKNOW_OPAQUE_RGB = 0x006600;
	private static final int DIDYOUKNOW_TRANSPARENT_RGB = 0xffff00;
	private static final int GAME_OPAQUE_RGB = 0x000000;
	private static final int GAME_TRANSPARENT_RGB = 0xffffff;
	private static final int CHAT_WIDTH_PX = 480; // approx chat line width, for wrapping
	private static final int TIMESTAMP_PAD_PX = 60;
	private static final long PENDING_TIMEOUT_MS = 15_000;
	private static final int PENDING_MAX = 96;
	private static final int TRACKED_MAX = 200;
	// RuneLite's BUILD_CHATBOX (216) is only a wrapper. Chat transmit and chatbox init invoke the
	// callback-owning rebuild proc directly, so lifecycle capture must follow the actual proc (84).
	private static final int CHATBOX_REBUILD_PROC = 84;

	@Inject
	private Client client;
	@Inject
	private Translator translator;
	@Inject
	private GlyphService glyph;
	@Inject
	private OsrscnConfig config;
	@Inject
	private com.osrscn.ToggleService toggle;

	private LongSupplier clock = System::currentTimeMillis;
	private long writeEpoch;
	private volatile RequestPermit publicRequests = newPlayerPermit(false);
	private volatile RequestPermit groupRequests = newPlayerPermit(true);
	private RequestPermit cleanedPublicRequests;
	private RequestPermit cleanedGroupRequests;
	private PlayerChatMode cleanedPublicMode;
	private PlayerChatMode cleanedGroupMode;

	private RequestPermit newPlayerPermit(boolean group)
	{
		return new RequestPermit(() -> toggle.isChineseEnabled()
				&& (group ? config.groupChatMode() : config.playerChatMode()) != PlayerChatMode.OFF);
	}

	/** Revoke both scopes for callers invalidating all player deliveries. */
	public synchronized void playerChatModeChanged()
	{
		publicRequests.revoke();
		groupRequests.revoke();
		publicRequests = newPlayerPermit(false);
		groupRequests = newPlayerPermit(true);
	}

	/** Revoke the changed scope synchronously before client-thread cleanup is queued. */
	public synchronized void playerChatModeChanged(String key)
	{
		if ("groupChatMode".equals(key))
		{
			groupRequests.revoke();
			groupRequests = newPlayerPermit(true);
		}
		else if ("playerChatMode".equals(key))
		{
			publicRequests.revoke();
			publicRequests = newPlayerPermit(false);
		}
	}

	private RequestPermit requestsFor(ChatMessageType type)
	{
		return isGroupType(type) ? groupRequests : publicRequests;
	}

	private PlayerChatMode modeFor(ChatMessageType type)
	{
		return isGroupType(type) ? config.groupChatMode() : config.playerChatMode();
	}

	private boolean playerModeCurrent(Generation generation)
	{
		return generation.playerMode == null || (generation.playerRequests == requestsFor(generation.type)
				&& generation.playerMode != PlayerChatMode.OFF && generation.playerMode == modeFor(generation.type));
	}

	private boolean authorized(Generation generation)
	{
		return toggle.isChineseEnabled() && playerModeCurrent(generation) && current(generation);
	}

	/** Client-thread cleanup only; a delayed cleanup cannot remove a newer mode's deliveries. */
	public void discardRevokedPlayerMessages()
	{
		RequestPermit publicPermit = publicRequests;
		RequestPermit groupPermit = groupRequests;
		PlayerChatMode publicMode = config.playerChatMode();
		PlayerChatMode groupMode = config.groupChatMode();
		if (publicPermit == cleanedPublicRequests && groupPermit == cleanedGroupRequests
				&& publicMode == cleanedPublicMode && groupMode == cleanedGroupMode) return;
		cleanedPublicRequests = publicPermit;
		cleanedGroupRequests = groupPermit;
		cleanedPublicMode = publicMode;
		cleanedGroupMode = groupMode;
		boolean changed = false;
		for (Tracked t : new ArrayList<>(tracked.values()))
		{
			if (playerModeCurrent(t.generation)) continue;
			if (current(t.generation))
			{
				t.generation.node.setValue(t.origValue);
				t.generation.writtenValue = t.origValue;
				if (current(t.generation)) t.generation.node.setRuneLiteFormatMessage(t.origRlfm);
				changed = true;
			}
			t.generation.active = false;
			tracked.remove(t.generation.node, t);
		}
		for (Pending p : pending.values())
		{
			if (!playerModeCurrent(p.generation))
			{
				p.generation.active = false;
				pending.remove(p.generation.node, p);
			}
		}
		for (Insert in : inserts.values())
		{
			if (!playerModeCurrent(in.generation))
			{
				in.generation.active = false;
				inserts.remove(in.generation.node, in);
			}
		}
		if (changed) client.refreshChat();
	}

	// nodes we still re-assert each tick (AI may land late, or a plugin may overwrite our text)
	private final Map<MessageNode, Pending> pending = new ConcurrentHashMap<>();
	// Only the current explicit language switch waits here. Pending plus waiting owns at most
	// TRACKED_MAX switch members; each tick rotates at most PENDING_MAX of those same references.
	private final Map<MessageNode, Pending> toggleWaiting = new LinkedHashMap<>();
	// INSERT mode: player-chat lines waiting to have a separate Chinese line added once translated
	private final Map<MessageNode, Insert> inserts = new ConcurrentHashMap<>();
	// every node we've translated, with its original text + how to re-translate it, for the toggle (LRU)
	private final Map<MessageNode, Tracked> tracked = new LinkedHashMap<MessageNode, Tracked>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<MessageNode, Tracked> e)
		{
			return size() > TRACKED_MAX;
		}
	};
	// Current BUILD_CHATBOX identity map. RuneLite's patched script emits one UID callback for each
	// accepted message, in the same order as the contiguous Chatbox.LINE0..LINE499 hit boxes.
	private final Map<Generation, Integer> chatLines = new IdentityHashMap<>();
	private final List<Generation> buildingChatNodes = new ArrayList<>();
	private boolean chatBuildActive;
	private int chatBuildIndex;

	/** True only for the script that owns the chatMessageBuilding callbacks. */
	public static boolean isChatBuildScript(int scriptId)
	{
		return scriptId == CHATBOX_REBUILD_PROC;
	}

	/** A native message lifetime, not the reusable ChatLineBuffer object that happens to hold it. */
	private final class Generation
	{
		final MessageNode node;
		final int id;
		final ChatMessageType type;
		final String name;
		final String sender;
		final String originalValue;
		final PlayerChatMode playerMode;
		final RequestPermit playerRequests;
		final RequestPermit renderPermit;
		String writtenValue;
		boolean active = true;

		Generation(MessageNode node)
		{
			this.node = node;
			type = node.getType();
			playerMode = isPlayerType(type) ? modeFor(type) : null;
			playerRequests = requestsFor(type);
			renderPermit = playerMode == null ? null
					: new RequestPermit(playerRequests, () -> modeFor(type) == playerMode);
			id = node.getId();
			name = node.getName();
			sender = node.getSender();
			originalValue = node.getValue();
			writtenValue = originalValue;
		}
	}

	private static boolean isPlayerType(ChatMessageType type)
	{
		return type == ChatMessageType.PUBLICCHAT || type == ChatMessageType.MODCHAT
				|| type == ChatMessageType.AUTOTYPER || type == ChatMessageType.MODAUTOTYPER
				|| type == ChatMessageType.CLAN_CHAT || type == ChatMessageType.CLAN_GUEST_CHAT
				|| type == ChatMessageType.CLAN_GIM_CHAT || type == ChatMessageType.FRIENDSCHAT;
	}

	private static boolean isGroupType(ChatMessageType type)
	{
		return type == ChatMessageType.FRIENDSCHAT || type == ChatMessageType.CLAN_CHAT
				|| type == ChatMessageType.CLAN_GUEST_CHAT || type == ChatMessageType.CLAN_GIM_CHAT;
	}

	private boolean current(Generation generation)
	{
		MessageNode node = generation.node;
		// The current client publishes into getMessages before ChatMessage. Removal from chat history
		// unlinks that same table entry without changing the node's ID or body.
		boolean matches = generation.active && node.getId() == generation.id
				&& client.getMessages() != null && client.getMessages().get(generation.id) == node
				&& node.getType() == generation.type && Objects.equals(node.getName(), generation.name)
				&& Objects.equals(node.getSender(), generation.sender)
				&& (Objects.equals(node.getValue(), generation.originalValue)
						|| Objects.equals(node.getValue(), generation.writtenValue));
		if (!matches) generation.active = false;
		return matches;
	}

	private void forget(MessageNode node)
	{
		Tracked t = tracked.remove(node);
		Pending p = pending.remove(node);
		toggleWaiting.remove(node);
		Insert in = inserts.remove(node);
		if (t != null) t.generation.active = false;
		if (p != null) p.generation.active = false;
		if (in != null) in.generation.active = false;
	}

	private static final class Pending
	{
		final Generation generation;
		final String english;
		final int color;
		final int maxChars;
		final long deadline;
		final boolean persist;
		final long toggleEpoch;

		Pending(Generation generation, String english, int color, int maxChars, long deadline, boolean persist)
		{
			this(generation, english, color, maxChars, deadline, persist, -1);
		}

		Pending(Generation generation, String english, int color, int maxChars, long deadline, boolean persist,
				long toggleEpoch)
		{
			this.toggleEpoch = toggleEpoch;
			this.generation = generation;
			this.english = english;
			this.color = color;
			this.maxChars = maxChars;
			this.deadline = deadline;
			this.persist = persist;
		}
	}

	private static final class Tracked
	{
		final Generation generation;
		final String origValue;
		final String origRlfm;
		final String english;
		final int color;
		final boolean persist;
		final boolean nativeHoverColor;
		int appliedColor;
		String renderedText;
		boolean rendered;
		boolean complete;
		long retryDeadline = -1;

		Tracked(Generation generation, String origValue, String origRlfm, String english, int color, boolean persist,
				boolean nativeHoverColor)
		{
			this.generation = generation;
			this.origValue = origValue;
			this.origRlfm = origRlfm;
			this.english = english;
			this.color = color;
			this.persist = persist;
			this.nativeHoverColor = nativeHoverColor;
			this.appliedColor = color;
		}
	}

	private static final class Insert
	{
		final Generation generation;
		final String name;
		final String english;
		final int color;
		final long deadline;

		Insert(Generation generation, String name, String english, int color, long deadline)
		{
			this.generation = generation;
			this.name = name;
			this.english = english;
			this.color = color;
			this.deadline = deadline;
		}
	}

	/** Start a current-client BUILD_CHATBOX pass. The callback order is the native line order. */
	public void beginChatBuild()
	{
		buildingChatNodes.clear();
		chatBuildIndex = 0;
		chatBuildActive = true;
	}

	/** Capture one RuneLite chatMessageBuilding UID without comparing message text. */
	public void captureChatLine(int[] intStack, int intStackSize)
	{
		if (!chatBuildActive)
		{
			return;
		}
		chatBuildIndex++;
		int uid = messageUid(intStack, intStackSize);
		MessageNode node = uid < 0 || client.getMessages() == null ? null : client.getMessages().get(uid);
		Tracked t = node == null ? null : tracked.get(node);
		if (chatBuildIndex <= 500)
		{
			buildingChatNodes.add(t != null && t.generation.id == uid && current(t.generation)
					? t.generation : null);
		}
	}

	/** Publish only a complete build, so a partial or unrelated callback can never cross-wire rows. */
	public void finishChatBuild()
	{
		if (!chatBuildActive)
		{
			return;
		}
		chatBuildActive = false;
		chatLines.clear();
		int builtRows = 0;
		for (int i = 0; i < 500; i++)
		{
			Widget line = client.getWidget(chatLineId(i));
			if (line == null || line.getWidth() <= 0 || line.getHeight() <= 0)
			{
				break;
			}
			builtRows++;
		}
		// The current script may prepend exactly one non-message row for the public-chat text filter.
		// Infer that offset from native row allocation, never from row text.
		int offset = builtRows - buildingChatNodes.size();
		if (offset == 0 || offset == 1)
		{
			for (int i = 0; i < buildingChatNodes.size(); i++)
			{
				Generation generation = buildingChatNodes.get(i);
				if (generation != null && current(generation))
				{
					chatLines.put(generation, i + offset);
				}
			}
		}
		buildingChatNodes.clear();
	}

	/**
	 * Match char-image colour to the visible native chat row. Chatbox.LINE* is the row hit box; the
	 * actual text and colour live in SCROLLAREA's {@code lineIndex * 4} dynamic child.
	 */
	public void refreshNativeColors()
	{
		discardRevokedPlayerMessages();
		if (chatLines.isEmpty())
		{
			return;
		}
		Widget scroll = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		Widget[] children = scroll == null ? null : scroll.getDynamicChildren();
		Point mouse = client.getMouseCanvasPosition();
		if (children == null || mouse == null)
		{
			return;
		}
		boolean changed = false;
		for (Map.Entry<Generation, Integer> e : new ArrayList<>(chatLines.entrySet()))
		{
			Generation generation = e.getKey();
			Tracked t = tracked.get(generation.node);
			int lineIndex = e.getValue();
			int textIndex = lineIndex * 4;
			if (t == null || t.generation != generation || !current(generation)
					|| textIndex < 0 || textIndex >= children.length)
			{
				continue;
			}
			Widget line = client.getWidget(chatLineId(lineIndex));
			Widget text = children[textIndex];
			if (line == null || text == null || line.isHidden() || text.isHidden())
			{
				continue;
			}
			int nativeColor = nativeLineColor(line.getBounds(), mouse, text.getTextColor(),
					t.color, t.appliedColor, t.nativeHoverColor);
			// Capacity-blocked partials use the existing visible-row pass to regain a retry slot.
			// Admission preserves the original deadline; translation remains on the tick path.
			if (!t.complete)
			{
				addPending(generation.node, t.english, nativeColor, t.persist);
			}
			Map<MessageNode, Pending> queue = pending.containsKey(generation.node) ? pending : toggleWaiting;
			Pending p = queue.get(generation.node);
			if (p != null && p.generation == generation && p.color != nativeColor)
			{
				queue.put(generation.node, new Pending(generation, p.english, nativeColor, p.maxChars,
						p.deadline, p.persist, p.toggleEpoch));
			}
			if (needsNativeRerender(t.appliedColor, nativeColor, t.rendered))
			{
				changed |= renderTracked(generation.node, t, nativeColor);
			}
		}
		if (changed)
		{
			client.refreshChat();
		}
	}

	private static int messageUid(int[] intStack, int intStackSize)
	{
		return intStack == null || intStackSize <= 0 || intStackSize > intStack.length
				? -1 : intStack[intStackSize - 1];
	}

	private static int chatLineId(int lineIndex)
	{
		return lineIndex < 0 || lineIndex > InterfaceID.Chatbox.LINE499 - InterfaceID.Chatbox.LINE0
				? -1 : InterfaceID.Chatbox.LINE0 + lineIndex;
	}

	private static boolean isChatLineId(int widgetId)
	{
		return widgetId >= InterfaceID.Chatbox.LINE0 && widgetId <= InterfaceID.Chatbox.LINE499;
	}

	private static int nativeLineColor(Rectangle bounds, Point mouse, int widgetColor,
			int fallbackColor, int appliedColor, boolean nativeHoverColor)
	{
		int fallback = fallbackColor & 0xffffff;
		if (!nativeHoverColor || bounds == null || mouse == null
				|| !bounds.contains(mouse.getX(), mouse.getY()))
		{
			return fallback;
		}
		int widget = widgetColor & 0xffffff;
		if (widget != fallback)
		{
			return widget;
		}
		// Writing new char-image tags calls refreshChat(), which rebuilds the native text child at its
		// base colour even though the pointer never left the row. Keep the last confirmed hover colour
		// latched until the bounds test observes a real mouse leave.
		int applied = appliedColor & 0xffffff;
		return applied != fallback ? applied : widget;
	}

	private static boolean needsNativeRerender(int appliedColor, int nativeColor, boolean rendered)
	{
		return !rendered || (appliedColor & 0xffffff) != (nativeColor & 0xffffff);
	}

	public void handle(ChatMessage event)
	{
		MessageNode node = event.getMessageNode();
		if (node == null) return;
		// A ChatMessage is a new delivery even when the buffer reuses an object, ID, or body.
		// Do this before OFF/disabled/unsupported/empty paths; those must not retain older work.
		forget(node);
		discardRevokedPlayerMessages();
		if (event.getType() != node.getType()) return;
		switch (event.getType())
		{
			case PUBLICCHAT:
			case MODCHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
			case FRIENDSCHAT:
				if (!isGroupType(event.getType()) || modeFor(event.getType()) != PlayerChatMode.OFF)
				{
					handlePlayer(node, event.getType());
				}
				break;
			case GAMEMESSAGE:
			case ENGINE:
			case SPAM:
			case WELCOME:
			case BROADCAST:
			case DIDYOUKNOW:
			case LEVELUPMESSAGE:
			case NPC_EXAMINE:
			case ITEM_EXAMINE:
			case OBJECT_EXAMINE:
				if (config.translateGameMessages())
				{
					handleGame(node, event.getType());
				}
				break;
			default:
				break; // private chat, channel system notices, dialogue: leave alone
		}
	}

	private void handlePlayer(MessageNode node, ChatMessageType type)
	{
		if (node == null || !toggle.isChineseEnabled())
		{
			return;
		}
		String value = node.getValue();
		if (value == null || value.isEmpty() || value.contains("<img="))
		{
			return; // empty or already our char-image translation
		}
		int color = playerChatColor(type);
		switch (modeFor(type))
		{
			case INLINE:
				// player chat: memory-only (slang rarely recurs, don't bloat the disk cache)
				Tracked t = translateNode(node, Tags.stripCol(value), color, false, false);
				if (t != null && current(t.generation) && !isTranslated(node))
				{
					recolour(t.generation, value, color); // keep native-colour English until translation is ready
				}
				break;
			case INSERT:
				// leave the English line as the game drew it; add a separate Chinese line below it
				queueInsert(node, value, color);
				break;
			case OFF:
			default:
				recolour(new Generation(node), value, color); // not tracked: preserve the channel's native colour
				break;
		}
	}

	private long pendingTimeoutMs()
	{
		// Capture once when work is admitted. Ticks and colour refreshes never renew this budget.
		return config.useLocalAi() && config.aiBackend() == AiBackend.OLLAMA
				? AiTranslator.OLLAMA_REQUEST_TIMEOUT_MS + PENDING_TIMEOUT_MS : PENDING_TIMEOUT_MS;
	}

	/** INSERT mode: remember this player-chat line so {@link #tick()} can add a Chinese line for it. */
	private void queueInsert(MessageNode node, String value, int color)
	{
		if (inserts.containsKey(node) || inserts.size() >= PENDING_MAX)
		{
			return;
		}
		String name = node.getName();
		Generation generation = new Generation(node);
		if (!current(generation)) return;
		inserts.put(node, new Insert(generation, name == null ? "" : name, Tags.stripCol(value), color,
				clock.getAsLong() + pendingTimeoutMs()));
		tryInsert(node); // table hits land immediately; AI misses retry next tick
	}

	/**
	 * Add a "OSRS_CN: Name: 你好" line for one queued player message once its translation is ready.
	 * Returns true when handled (inserted, or nothing translatable) so the caller can stop retrying.
	 */
	private boolean tryInsert(MessageNode node)
	{
		Insert in = inserts.get(node);
		if (in == null)
		{
			return true;
		}
		if (!authorized(in.generation))
		{
			inserts.remove(node, in);
			return true;
		}
		long epoch = writeEpoch;
		Translator.Rendered r = renderChat(in.generation, in.english, in.color, chatMaxChars(), false);
		if (epoch != writeEpoch || !authorized(in.generation) || inserts.get(node) != in)
		{
			inserts.remove(node, in);
			return true;
		}
		if (r == null)
		{
			return false; // not translated yet
		}
		inserts.remove(node, in);
		String prefix = "OSRS_CN: " + (in.name.isEmpty() ? "" : in.name + ": ");
		client.addChatMessage(ChatMessageType.CONSOLE, "", prefix + r.text, null);
		return true;
	}

	private void handleGame(MessageNode node, ChatMessageType type)
	{
		if (node == null)
		{
			return;
		}
		String value = node.getValue();
		if (value == null || value.isEmpty() || value.contains("<img="))
		{
			return; // empty, our own message, or already translated
		}
		int fallback = engineDefaultColor(type);
		boolean nativeHoverColor = hasNativeHoverColor(type);
		if (!toggle.isChineseEnabled())
		{
			// English mode: track only, so goChinese() can translate messages that arrived
			// while the toggle was off.
			track(node, value, Tags.firstColor(value, fallback), true, nativeHoverColor);
			return;
		}
		translateNode(node, value, Tags.firstColor(value, fallback), true, nativeHoverColor);
	}

	private static boolean hasNativeHoverColor(ChatMessageType type)
	{
		return type == ChatMessageType.LEVELUPMESSAGE || type == ChatMessageType.BROADCAST;
	}

	/**
	 * Colour the engine would paint an untagged message of this type. Baked glyph images can't
	 * inherit the engine's per-type colouring, so we have to reproduce it. Broadcast and
	 * "Did you know?" have separate current-client colour settings; everything else is black on the
	 * opaque chat box and white on the transparent one.
	 */
	private int engineDefaultColor(ChatMessageType type)
	{
		boolean transparent = client.getVarbitValue(net.runelite.api.gameval.VarbitID.CHATBOX_TRANSPARENCY) != 0;
		if (type == ChatMessageType.DIDYOUKNOW)
		{
			return configuredChatColor(transparent,
					net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_DIDYOUKNOW_OPAQUE,
					net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_DIDYOUKNOW_TRANSPARENT,
					DIDYOUKNOW_OPAQUE_RGB, DIDYOUKNOW_TRANSPARENT_RGB);
		}
		if (type == ChatMessageType.BROADCAST)
		{
			return configuredChatColor(transparent,
					net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_BROADCAST_OPAQUE,
					net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_BROADCAST_TRANSPARENT,
					GAME_OPAQUE_RGB, GAME_TRANSPARENT_RGB);
		}
		return transparent ? GAME_TRANSPARENT_RGB : GAME_OPAQUE_RGB;
	}

	private int playerChatColor(ChatMessageType type)
	{
		boolean transparent = client.getVarbitValue(net.runelite.api.gameval.VarbitID.CHATBOX_TRANSPARENCY) != 0;
		switch (type)
		{
			case AUTOTYPER:
			case MODAUTOTYPER:
				return configuredChatColor(transparent,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_AUTOCHAT_OPAQUE,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_AUTOCHAT_TRANSPARENT,
						AUTOCHAT_OPAQUE_RGB, AUTOCHAT_TRANSPARENT_RGB);
			case FRIENDSCHAT:
				return configuredChatColor(transparent,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_FRIENDSCHAT_OPAQUE,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_FRIENDSCHAT_TRANSPARENT,
						FRIENDSCHAT_OPAQUE_RGB, FRIENDSCHAT_TRANSPARENT_RGB);
			case CLAN_CHAT:
				return configuredChatColor(transparent,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_CLANCHAT_OPAQUE,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_CLANCHAT_TRANSPARENT,
						CLANCHAT_RGB, CLANCHAT_RGB);
			case CLAN_GUEST_CHAT:
				return configuredChatColor(transparent,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_GUESTCLAN_OPAQUE,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_GUESTCLAN_TRANSPARENT,
						GUESTCLAN_OPAQUE_RGB, GUESTCLAN_TRANSPARENT_RGB);
			case CLAN_GIM_CHAT:
				return configuredChatColor(transparent,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_GIMCHAT_OPAQUE,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_GIMCHAT_TRANSPARENT,
						GIMCHAT_RGB, GIMCHAT_RGB);
			case PUBLICCHAT:
			case MODCHAT:
			default:
				return configuredChatColor(transparent,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_PUBLIC_OPAQUE,
						net.runelite.api.gameval.VarPlayerID.OPTION_CHAT_COLOUR_PUBLIC_TRANSPARENT,
						PUBLIC_OPAQUE_RGB, PUBLIC_TRANSPARENT_RGB);
		}
	}

	private int configuredChatColor(boolean transparent, int opaqueVarp, int transparentVarp,
			int opaqueDefault, int transparentDefault)
	{
		int setting = client.getVarpValue(transparent ? transparentVarp : opaqueVarp);
		return setting > 0 ? (setting - 1) & 0xffffff
				: (transparent ? transparentDefault : opaqueDefault);
	}

	private Translator.Rendered renderChat(Generation generation, String text, int color, int maxChars, boolean persist)
	{
		if (!authorized(generation)) return null;
		return generation.playerMode == null
				? translator.renderChat(text, color, maxChars, glyph.uiSize(), true, persist)
				: translator.renderChat(text, color, maxChars, glyph.uiSize(), true, false, generation.renderPermit);
	}

	private Tracked translateNode(MessageNode node, String english, int color, boolean persist,
			boolean nativeHoverColor)
	{
		Tracked t = track(node, english, color, persist, nativeHoverColor);
		if (t == null || !authorized(t.generation)) return null;
		if (t.retryDeadline < 0)
		{
			t.retryDeadline = clock.getAsLong() + pendingTimeoutMs();
		}
		long epoch = writeEpoch;
		Translator.Rendered r = renderChat(t.generation, english, color, chatMaxChars(), persist);
		if (epoch != writeEpoch || !authorized(t.generation)) return null;
		if (r != null)
		{
			boolean changed = write(t.generation, r.text, epoch);
			markRendered(t, color, r);
			if (changed)
			{
				client.refreshChat();
			}
		}
		addPending(node, english, color, persist);
		return t;
	}

	private boolean renderTracked(MessageNode node, Tracked t, int color)
	{
		if (!authorized(t.generation)) return false;
		long epoch = writeEpoch;
		boolean retryActive = t.retryDeadline >= 0 && clock.getAsLong() <= t.retryDeadline;
		if (!retryActive && !t.rendered)
		{
			return false; // Only a new message or the language toggle may start another retry window.
		}
		// A new colour may need glyph uploads after translation retries have ended. Read existing
		// translations without dispatching AI or collecting missing text; never renew the deadline.
		Translator.Rendered r = retryActive
				? renderChat(t.generation, t.english, color, chatMaxChars(), t.persist)
				: translator.renderChatCached(t.english, color, chatMaxChars(), glyph.uiSize());
		if (epoch != writeEpoch || !authorized(t.generation)) return false;
		if (r == null)
		{
			if (retryActive)
			{
				addPending(node, t.english, color, t.persist);
			}
			return false;
		}
		boolean changed = write(t.generation, r.text, epoch);
		markRendered(t, color, r);
		return changed;
	}

	/** Retry/re-assert chat translations; call each tick. */
	public void tick()
	{
		discardRevokedPlayerMessages();
		if (!toggle.isChineseEnabled()) return;
		long epoch = writeEpoch;
		long now = clock.getAsLong();
		if (!inserts.isEmpty())
		{
			for (Iterator<Map.Entry<MessageNode, Insert>> it = inserts.entrySet().iterator(); it.hasNext(); )
			{
				Map.Entry<MessageNode, Insert> e = it.next();
				if (!current(e.getValue().generation) || now > e.getValue().deadline)
				{
					it.remove();
				}
				else
				{
					tryInsert(e.getKey()); // removes itself from the map on success
					if (epoch != writeEpoch) return;
				}
			}
		}
		fillTogglePending();
		if (pending.isEmpty())
		{
			return;
		}
		boolean changed = false;
		// A fixed batch prevents newly admitted or reentrant switch work from running twice this tick.
		List<Map.Entry<MessageNode, Pending>> batch = new ArrayList<>(pending.entrySet());
		for (Map.Entry<MessageNode, Pending> e : batch)
		{
			if (epoch != writeEpoch) return;
			Pending p = e.getValue();
			if (pending.get(e.getKey()) != p) continue;
			if (!authorized(p.generation) || now > p.deadline)
			{
				pending.remove(e.getKey(), p);
				continue;
			}
			Tracked t = tracked.get(e.getKey());
			if (t != null && t.generation != p.generation) t = null;
			if (p.toggleEpoch >= 0 && (p.toggleEpoch != epoch || t == null))
			{
				pending.remove(e.getKey(), p);
				continue;
			}
			if (t != null && t.rendered && t.complete && t.appliedColor == p.color
					&& t.renderedText != null && t.renderedText.equals(displayed(e.getKey())))
			{
				continue;
			}
			Translator.Rendered r = renderChat(p.generation, p.english, p.color, p.maxChars, p.persist);
			if (epoch != writeEpoch) return;
			if (!authorized(p.generation) || pending.get(e.getKey()) != p) continue;
			if (r != null)
			{
				if (write(p.generation, r.text, epoch))
				{
					changed = true;
				}
				if (epoch != writeEpoch) return;
				if (t != null)
				{
					markRendered(t, p.color, r);
				}
			}
		}
		// Complete results keep their re-assertion opportunity, but cannot monopolize all 96 slots.
		// Natural retries retain their original queue membership and deadline.
		for (Map.Entry<MessageNode, Pending> e : batch)
		{
			Pending p = e.getValue();
			if (p.toggleEpoch == epoch && pending.remove(e.getKey(), p))
			{
				toggleWaiting.put(e.getKey(), p);
			}
		}
		fillTogglePending();
		if (changed)
		{
			client.refreshChat();
		}
	}

	/** Put the original English back on every translated chat line (switch to English). */
	public void goEnglish()
	{
		discardRevokedPlayerMessages();
		writeEpoch++;
		pending.clear();
		toggleWaiting.clear();
		for (Insert in : inserts.values()) in.generation.active = false;
		inserts.clear(); // stop adding new Chinese lines; already-inserted lines stay in chat history
		boolean changed = false;
		for (Map.Entry<MessageNode, Tracked> e : new ArrayList<>(tracked.entrySet()))
		{
			Tracked t = e.getValue();
			if (!current(t.generation)) continue;
			e.getKey().setValue(t.origValue);
			t.generation.writtenValue = t.origValue;
			if (!current(t.generation)) continue;
			e.getKey().setRuneLiteFormatMessage(t.origRlfm);
			t.retryDeadline = -1;
			t.rendered = false;
			t.complete = false;
			t.renderedText = null;
			changed = true;
		}
		if (changed)
		{
			client.refreshChat();
		}
	}

	/** Re-translate every tracked chat line (switch back to Chinese). */
	public void goChinese()
	{
		discardRevokedPlayerMessages();
		writeEpoch++;
		long deadline = clock.getAsLong() + pendingTimeoutMs();
		pending.clear();
		toggleWaiting.clear();
		for (Map.Entry<MessageNode, Tracked> e : tracked.entrySet())
		{
			Tracked t = e.getValue();
			if (!current(t.generation)) continue;
			t.retryDeadline = deadline;
			toggleWaiting.put(e.getKey(), new Pending(t.generation, t.english, t.color, chatMaxChars(),
					deadline, t.persist, writeEpoch));
		}
		tick();
	}

	/** Forget everything without reverting (plugin shutdown). */
	public void clear()
	{
		writeEpoch++;
		for (Tracked t : tracked.values()) t.generation.active = false;
		for (Pending p : pending.values()) p.generation.active = false;
		for (Insert in : inserts.values()) in.generation.active = false;
		pending.clear();
		toggleWaiting.clear();
		inserts.clear();
		tracked.clear();
		chatLines.clear();
		buildingChatNodes.clear();
		chatBuildActive = false;
		chatBuildIndex = 0;
	}

	private Tracked track(MessageNode node, String english, int color, boolean persist,
			boolean nativeHoverColor)
	{
		Tracked t = tracked.get(node);
		if (t != null && !current(t.generation))
		{
			forget(node);
			t = null;
		}
		if (t == null)
		{
			Generation generation = new Generation(node);
			if (!current(generation)) return null;
			t = new Tracked(generation, node.getValue(), node.getRuneLiteFormatMessage(), english, color, persist,
					nativeHoverColor);
			tracked.put(node, t);
		}
		return t;
	}

	private static void markRendered(Tracked t, int color, Translator.Rendered result)
	{
		t.appliedColor = color & 0xffffff;
		t.renderedText = result.text;
		t.complete = result.complete;
		t.rendered = true;
	}

	/** Write our text to the node's value and (if it has one) its rlfm; returns true if it changed. */
	private boolean write(Generation generation, String text, long epoch)
	{
		if (epoch != writeEpoch || !authorized(generation)) return false;
		MessageNode node = generation.node;
		if (text.equals(displayed(node)))
		{
			return false;
		}
		node.setValue(text);
		generation.writtenValue = text;
		if (epoch == writeEpoch && authorized(generation) && node.getRuneLiteFormatMessage() != null)
		{
			node.setRuneLiteFormatMessage(text);
		}
		return true;
	}

	private void recolour(Generation generation, String value, int color)
	{
		if (!current(generation)) return;
		MessageNode node = generation.node;
		String wrapped = String.format("<col=%06x>%s</col>", color & 0xffffff, Tags.stripCol(value));
		if (wrapped.equals(node.getValue()))
		{
			return;
		}
		node.setValue(wrapped);
		generation.writtenValue = wrapped;
		client.refreshChat();
	}

	private boolean isTranslated(MessageNode node)
	{
		String shown = displayed(node);
		return shown != null && shown.contains("<img=");
	}

	private static String displayed(MessageNode node)
	{
		String rlfm = node.getRuneLiteFormatMessage();
		return rlfm != null ? rlfm : node.getValue();
	}

	private void addPending(MessageNode node, String english, int color, boolean persist)
	{
		// Reclaimed switch slots belong to the FIFO before new natural or visible-row admissions.
		fillTogglePending();
		Tracked t = tracked.get(node);
		if (t == null || !authorized(t.generation) || t.retryDeadline < 0 || clock.getAsLong() > t.retryDeadline)
		{
			return;
		}
		Pending current = pending.get(node);
		if (current != null)
		{
			if (current.color != color)
			{
				pending.put(node, new Pending(t.generation, current.english, color, current.maxChars,
						current.deadline, current.persist, current.toggleEpoch));
			}
			return;
		}
		Pending waiting = toggleWaiting.get(node);
		if (waiting != null)
		{
			if (waiting.color != color)
			{
				toggleWaiting.put(node, new Pending(t.generation, waiting.english, color, waiting.maxChars,
						waiting.deadline, waiting.persist, waiting.toggleEpoch));
			}
			return;
		}
		if (pending.size() >= PENDING_MAX)
		{
			return;
		}
		pending.put(node, new Pending(t.generation, english, color, chatMaxChars(), t.retryDeadline, persist));
	}

	private void fillTogglePending()
	{
		if (!toggle.isChineseEnabled()) return;
		long now = clock.getAsLong();
		for (Iterator<Map.Entry<MessageNode, Pending>> it = toggleWaiting.entrySet().iterator();
				it.hasNext() && pending.size() < PENDING_MAX; )
		{
			Map.Entry<MessageNode, Pending> e = it.next();
			Pending p = e.getValue();
			it.remove();
			Tracked t = tracked.get(e.getKey());
			if (p.toggleEpoch != writeEpoch || now > p.deadline || t == null
					|| t.generation != p.generation || !authorized(p.generation)) continue;
			pending.put(e.getKey(), p);
		}
	}

	private int chatMaxChars()
	{
		return Math.max(8, glyph.wrapChars(CHAT_WIDTH_PX - TIMESTAMP_PAD_PX, glyph.uiSize()));
	}

}

package com.osrscn.hooks;

import com.osrscn.glyph.GlyphService;
import com.osrscn.text.Tags;
import com.osrscn.translate.Translator;
import com.osrscn.ui.DialogueHistory;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Translates the NPC/player dialogue boxes and option list each tick.
 *
 * <p>No need to remember the English source: when a line is set we record what we wrote, so the
 * next tick we skip it; when the dialogue advances the game overwrites the widget with new English
 * and we translate again. AI misses simply stay English and retry on a later tick.
 */
@Slf4j
@Singleton
public class DialogueHandler
{
	// horizontal padding (px) kept clear of the widget edge so wrapped lines never overflow
	private static final int WRAP_PAD = 8;

	// Single text widgets (component id -> last text we wrote).
	// ChatRight.NAME is the local player's own name - never translate it.
	private static final int[] TEXT_WIDGETS = {
			InterfaceID.ChatLeft.TEXT,      // NPC line
			InterfaceID.ChatLeft.NAME,      // NPC name
			InterfaceID.ChatLeft.CONTINUE,  // "Click here to continue"
			InterfaceID.ChatRight.TEXT,     // player line
			InterfaceID.ChatRight.CONTINUE,
	};

	private static final String NPC_TEXT_KEY = Integer.toString(InterfaceID.ChatLeft.TEXT);
	private static final String PLAYER_TEXT_KEY = Integer.toString(InterfaceID.ChatRight.TEXT);

	@Inject
	private Client client;
	@Inject
	private Translator translator;
	@Inject
	private GlyphService glyph;
	@Inject
	private DialogueHistory history;

	private final Map<String, String> lastSet = new HashMap<>();
	private final Map<String, String> original = new HashMap<>(); // our translation -> original text, for restore
	private final Map<String, Integer> lastColor = new HashMap<>(); // colour we baked the glyphs with
	private String lastNpcName = ""; // remembered across ticks: the options screen has no name widget

	public void translateDialogues()
	{
		for (int id : TEXT_WIDGETS)
		{
			translateWidget(client.getWidget(id), Integer.toString(id));
		}
		translateOptions();
	}

	private void translateOptions()
	{
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		if (options == null)
		{
			return;
		}
		Widget[] children = options.getDynamicChildren();
		if (children == null)
		{
			return;
		}
		for (int i = 0; i < children.length; i++)
		{
			translateWidget(children[i], "opt" + i);
		}
	}

	/** Put the original English back on any dialogue widget we translated (instant EN switch). */
	public void restore()
	{
		for (int id : TEXT_WIDGETS)
		{
			restoreWidget(client.getWidget(id), Integer.toString(id));
		}
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		if (options != null && options.getDynamicChildren() != null)
		{
			Widget[] children = options.getDynamicChildren();
			for (int i = 0; i < children.length; i++)
			{
				restoreWidget(children[i], "opt" + i);
			}
		}
		lastSet.clear();
		original.clear();
		lastColor.clear();
	}

	private void restoreWidget(Widget w, String key)
	{
		if (w == null)
		{
			return;
		}
		String orig = original.get(key);
		// only restore if the widget still holds the exact translation we wrote
		if (orig != null && lastSet.containsKey(key) && lastSet.get(key).equals(w.getText()))
		{
			w.setText(orig);
		}
	}

	private void translateWidget(Widget w, String key)
	{
		if (w == null || w.isHidden())
		{
			return;
		}
		String text = w.getText();
		if (text == null || text.isEmpty())
		{
			return;
		}
		if (text.equals(lastSet.get(key)))
		{
			// our translation is still in place. Char-images bake their colour at render time, so a
			// native recolour (an option highlights under the mouse) does not change them - re-render
			// when the widget's colour no longer matches what we baked, so hover highlight follows.
			Integer baked = lastColor.get(key);
			if (baked == null || baked == w.getTextColor())
			{
				return;
			}
			String orig = original.get(key);
			if (orig != null)
			{
				String zh = translator.plain(Tags.stripTags(orig));
				if (zh != null)
				{
					applyGlyphs(w, key, zh, null); // recolour only: keep original + history intact
				}
			}
			return;
		}
		String english = Tags.stripTags(text);
		if (english.isEmpty())
		{
			return;
		}
		// translate once and reuse for both the history panel and the widget render. Pass NPC + speaker so
		// a collected miss (when enabled) records the same columns as the transcript tables. The options
		// screen has no name widget, so remember the conversation's NPC across ticks and reuse it there.
		String npc = npcSpeakerEn();
		if (!npc.isEmpty())
		{
			lastNpcName = npc;
		}
		else
		{
			npc = lastNpcName;
		}
		String speaker = key.equals(NPC_TEXT_KEY) ? npc : "Player";
		String zh = translator.plainColored(text, "dialogue", npc, speaker);
		// record new NPC/player dialogue lines into the history panel (this runs only when the line
		// actually changed, so it captures each line once as the dialogue advances). The panel shows
		// plain Chinese; the widget render below keeps the inline <col> segments.
		captureHistory(key, english, zh == null ? null : Tags.stripCol(zh));
		if (zh == null)
		{
			return; // not translated yet; a later tick retries
		}
		applyGlyphs(w, key, zh, text);
	}

	/**
	 * Render {@code zh} to char-images in the widget's current colour. When {@code origText} is
	 * non-null it is recorded as the English to restore; pass null for a colour-only re-render that
	 * must not disturb the stored original or the history capture.
	 */
	private void applyGlyphs(Widget w, String key, String zh, String origText)
	{
		// wrap long lines: a glyph string has no spaces for the client to break on, and a single
		// line wider than the widget renders as nothing, so wrap conservatively by measured width.
		int size = glyph.dialogueSize();
		int maxChars = glyph.wrapChars(w.getWidth() - WRAP_PAD, size);
		int color = w.getTextColor();
		String translated = glyph.toImgTags(zh, color, maxChars, size);
		if (translated == null)
		{
			return;
		}
		if (origText != null)
		{
			original.put(key, origText); // remember the English we are replacing, for instant restore
		}
		w.setText(translated);
		// native line height is sized for the small bitmap font; wrapped char-image lines
		// overflow and render blank unless we raise it to fit the taller glyphs.
		if (translated.contains("<br>"))
		{
			w.setLineHeight(glyph.glyphHeight(size));
		}
		lastSet.put(key, translated);
		lastColor.put(key, color);
	}

	private void captureHistory(String key, String english, String zh)
	{
		if (key.equals(NPC_TEXT_KEY))
		{
			String en = npcSpeakerEn();
			String zhName = npcSpeakerZh(en);
			history.add(zhName, en, zh, english);
		}
		else if (key.equals(PLAYER_TEXT_KEY))
		{
			String player = playerSpeaker();
			history.add(player, player, zh, english); // player name is never translated
		}
	}

	/** Current NPC speaker name in English (empty if no name widget). */
	private String npcSpeakerEn()
	{
		Widget name = client.getWidget(InterfaceID.ChatLeft.NAME);
		if (name == null)
		{
			return "";
		}
		String key = Integer.toString(InterfaceID.ChatLeft.NAME);
		// the name widget may already hold our char-images; use the stored English in that case
		return (name.getText() != null && name.getText().contains("<img="))
				? Tags.stripTags(original.getOrDefault(key, ""))
				: Tags.stripTags(name.getText() == null ? "" : name.getText());
	}

	/** NPC speaker name in Chinese, or the English name if it has no translation. */
	private String npcSpeakerZh(String en)
	{
		if (en.isEmpty())
		{
			return "";
		}
		String zh = translator.plain(en);
		return zh != null ? zh : en;
	}

	private String playerSpeaker()
	{
		return client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null
				? client.getLocalPlayer().getName() : "玩家";
	}

	/** Forget what we translated so everything re-translates (e.g. after a font-size change). */
	public void reset()
	{
		lastSet.clear();
		original.clear();
		lastColor.clear();
		lastNpcName = "";
	}
}

package com.osrscn.hooks;

import com.osrscn.glyph.GlyphService;
import com.osrscn.translate.AiTranslator;
import com.osrscn.translate.TranslationStore;
import com.osrscn.translate.Translator;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;

/**
 * Translates text in interface "pages" (skills, quests, settings, equipment, etc.).
 *
 * <p>Generic by design: it walks the widget tree of each open interface group and only replaces
 * text that is found in the interface table. Because that table holds real interface labels, the
 * lookup itself scopes what gets translated - arbitrary text (names, numbers) simply misses and is
 * left alone. Dialogue/chat groups are excluded since {@link DialogueHandler} owns them.
 */
@Slf4j
@Singleton
public class InterfaceTranslator
{
	private static final int WRAP_PAD = 8;
	private static final int MIN_WRAP = 6; // don't auto-wrap widgets narrower than this many glyphs
	// chat-tab labels render a touch smaller than normal UI text: the name pins to the top and the
	// On/Off filter (smaller still) tucks against the bottom, so the two glyph lines stay well apart.
	private static final int CHAT_TAB_NAME_SIZE = 10;
	private static final int CHAT_TAB_FILTER_SIZE = 9;

	// All per-group translation policy (excluded / small / per-frame-excluded / reconstruct / no-AI) and the
	// build-script hooks now live in one declarative table; see SurfaceRegistry. The chat box's message
	// lines are excluded there; its static tab labels are translated separately by translateChatTabs().
	private final SurfaceRegistry registry = SurfaceRegistry.build();

	private static final Set<Integer> CHAT_TAB_WIDGETS = new HashSet<>();
	// the On/Off/Filter/Hide indicator widgets: right-aligned in our horizontal layout (see
	// translateChatTabs). Everything else in CHAT_TAB_WIDGETS is a tab-name widget (left-aligned).
	private static final Set<Integer> CHAT_TAB_FILTERS = new HashSet<>();

	static
	{
		CHAT_TAB_FILTERS.add(InterfaceID.Chatbox.CHAT_GAME_FILTER);
		CHAT_TAB_FILTERS.add(InterfaceID.Chatbox.CHAT_PUBLIC_FILTER);
		CHAT_TAB_FILTERS.add(InterfaceID.Chatbox.CHAT_PRIVATE_FILTER);
		CHAT_TAB_FILTERS.add(InterfaceID.Chatbox.CHAT_FRIENDSCHAT_FILTER);
		CHAT_TAB_FILTERS.add(InterfaceID.Chatbox.CHAT_CLAN_FILTER);
		CHAT_TAB_FILTERS.add(InterfaceID.Chatbox.CHAT_TRADE_FILTER);

		CHAT_TAB_WIDGETS.add(InterfaceID.Chatbox.CHAT_ALL_TEXT1);
		CHAT_TAB_WIDGETS.add(InterfaceID.Chatbox.CHAT_GAME_TEXT1);
		CHAT_TAB_WIDGETS.add(InterfaceID.Chatbox.CHAT_PUBLIC_TEXT1);
		CHAT_TAB_WIDGETS.add(InterfaceID.Chatbox.CHAT_PRIVATE_TEXT1);
		CHAT_TAB_WIDGETS.add(InterfaceID.Chatbox.CHAT_FRIENDSCHAT_TEXT1);
		CHAT_TAB_WIDGETS.add(InterfaceID.Chatbox.CHAT_CLAN_TEXT1);
		CHAT_TAB_WIDGETS.add(InterfaceID.Chatbox.CHAT_TRADE_TEXT);
		CHAT_TAB_WIDGETS.addAll(CHAT_TAB_FILTERS);
	}

	@Inject
	private Client client;
	@Inject
	private Translator translator;
	@Inject
	private GlyphService glyph;
	@Inject
	private com.osrscn.OsrscnConfig config;
	// read only for their sizes, as invalidation signals for the negative memo (see revalidateMisses)
	@Inject
	private TranslationStore store;
	@Inject
	private AiTranslator aiTranslator;

	// keyed by id+index: dynamic children (skill/quest lists) share one id, so id alone collides
	private final Map<Long, String> lastSet = new HashMap<>();
	// the exact English that missed every table (and the AI) per widget: without it every untranslatable
	// label - item names, numbers, world rows - re-runs the whole lookup pipeline on every client tick AND
	// every frame, forever. Keyed on widget + exact text, so a widget whose text changed still translates
	// on the very same frame. See revalidateMisses() for how entries are invalidated.
	private final Map<Long, String> lastMiss = new HashMap<>();
	private final Map<Long, Integer> lastColor = new HashMap<>(); // colour baked into the glyphs, for hover re-render
	private final Map<Long, String> original = new HashMap<>(); // -> original text, for instant restore
	// per journal root: the raw slot text the last tick saw, to debounce the client's multi-stage population
	private final Map<Integer, String> journalSig = new HashMap<>();
	// per journal root: consecutive ticks that signature has held, gating collection (see reconstructRoot)
	private final Map<Integer, Integer> journalStable = new HashMap<>();
	// widgets we translated only partially (some AI lines pending): re-translate until complete
	private final Set<Long> incomplete = new HashSet<>();
	// prose slots (860) whose position we changed while compacting: original x/y to revert on restore/decommit
	private final Map<Long, Integer> movedX = new HashMap<>();
	private final Map<Long, Integer> movedY = new HashMap<>();
	// native width before we widened a slot: without reverting it, the next layout's column measurement
	// reads our own widened slots and the column inflates a little more on every re-layout / tab switch
	private final Map<Long, Integer> movedW = new HashMap<>();
	// where WE put each moved widget: live != placed means the client repositioned it (repopulation evidence),
	// and live == placed corroborates the geometry is still ours and safe to revert
	private final Map<Long, Integer> placedX = new HashMap<>();
	private final Map<Long, Integer> placedY = new HashMap<>();
	// chat tab labels are handled explicitly by component id (the generic walk's index-based key proved
	// unreliable for them across re-translation, leaving them stuck in Chinese on an English toggle).
	private final Map<Integer, String> tabOriginal = new HashMap<>();
	// original X/Y text alignment per tab widget, captured before we pin name=top / filter=bottom
	private final Map<Integer, Integer> tabAlignX = new HashMap<>();
	private final Map<Integer, Integer> tabAlignY = new HashMap<>();

	private static long widgetKey(Widget w)
	{
		return ((long) w.getId() << 21) | (w.getIndex() & 0x1FFFFF);
	}

	// ===== Per-pass state =====
	// Config values the walk needs, read once per pass: a RuneLite config proxy call costs far more than
	// the check it guards, and the walk touches thousands of widgets per client tick AND per frame.
	private boolean cfgAiInterface;
	private boolean cfgReconstruct;
	private boolean cfgDebug;
	private boolean cfgSearchResults;
	// A memoised miss may survive at most this many passes: anything we failed to detect (a glyph sprite
	// that finished uploading, a config toggle, a backend that came back) then costs a fraction of a second
	// of English instead of sticking forever. ~4 revalidations/s across the tick + frame lanes.
	private static final int MISS_REVALIDATE_PASSES = 25;
	private int missPasses;
	private int missStoreSize = -1;
	private int missAiCacheSize = -1;
	// debugMonitor-only counters; every increment sits behind cfgDebug so they cost nothing when off
	private int statVisited;
	private int statMissRun;
	private int statMissSkip;
	private int statPasses;
	private long statSince;
	private volatile String statLine = "";
	private boolean promptPerFrame;
	private String promptDump; // debugMonitor: last logged chatbox prompt layout, to log each one once

	/** Start one walk: refresh the cached config values and revalidate the negative memo. */
	private void beginPass()
	{
		cfgAiInterface = config.aiFillInterface();
		cfgReconstruct = config.reconstructJournals();
		cfgDebug = config.debugMonitor();
		cfgSearchResults = config.translateSearchResults();
		revalidateMisses();
		if (cfgDebug)
		{
			statPasses++;
		}
	}

	/**
	 * Drop the negative memo whenever a miss could have become a hit: the translation tables finished an
	 * (async) load or reload, an AI translation landed in the cache, or the revalidation timeout expired.
	 * Both sizes are O(1)-ish reads of concurrent maps, taken once per pass and never per widget.
	 */
	private void revalidateMisses()
	{
		if (lastMiss.isEmpty())
		{
			return;
		}
		int tables = store.size();
		int aiCache = aiTranslator.cacheSize();
		if (++missPasses >= MISS_REVALIDATE_PASSES || tables != missStoreSize || aiCache != missAiCacheSize)
		{
			missPasses = 0;
			missStoreSize = tables;
			missAiCacheSize = aiCache;
			lastMiss.clear();
		}
	}

	/** Roll the debug counters into {@link #debugStats()} once a second. Only called with debugMonitor on. */
	private void reportStats()
	{
		long now = System.currentTimeMillis();
		if (statSince == 0)
		{
			statSince = now;
			return;
		}
		if (now - statSince < 1000)
		{
			return;
		}
		int passes = Math.max(statPasses, 1);
		statLine = statVisited / passes + " widgets/pass, " + statMissRun + " misses/s, "
				+ statMissSkip + " memo hits/s, " + passes + " passes/s";
		log.info("OSRSCN-perf {}", statLine);
		statVisited = 0;
		statMissRun = 0;
		statMissSkip = 0;
		statPasses = 0;
		statSince = now;
	}

	/** Re-translate every loaded interface root. Lookup self-scopes (only table hits are replaced). */
	public void translateOpen()
	{
		beginPass();
		scan(false);
		translateChatTabs();
		translateChatPrompts(false);
		reconstructJournals();
		reconstructWordSplit(); // PROTOTYPE Phase 3: new-style (word-per-widget) skill guide, group 860
		if (cfgDebug)
		{
			reportStats();
		}
	}

	// ===== Experimental whole-task journal translation (config.reconstructJournals) =====

	/**
	 * Translate the achievement diary / quest journal as whole tasks instead of per wrapped line.
	 *
	 * <p>The client hard-wraps each task across several fixed-height line slots, so the generic scan only
	 * ever sees half-sentences. Here we rebuild each task from its slots ({@link JournalReconstructor}),
	 * translate the whole task, then re-flow the rendered Chinese back across those same slots (one
	 * wrapped line per slot, blanking any left over). Reconstruction reads each slot's <em>current</em>
	 * text: once a task is translated its slots hold char-images / blanks, which {@code reconstruct()}
	 * classifies as structural, so a translated task is naturally skipped next tick (idempotent, needs no
	 * extra state, and a different diary's fresh English re-translates cleanly). Untranslatable tasks
	 * (table miss + AI off/pending) are left in English, exactly as the generic scan would.
	 */
	private void reconstructJournals()
	{
		if (!cfgReconstruct)
		{
			return;
		}
		reconstructRoot(InterfaceID.Journalscroll.UNIVERSE);
		reconstructRoot(InterfaceID.Questjournal.UNIVERSE);
	}

	private static final int SKILL_GUIDE_NEW_GROUP = 860;
	private static final int PROSE_CHILD = 0x0e; // the guide's description column (word-per-widget prose)
	private static final int PROSE_COMPONENT_ID = (SKILL_GUIDE_NEW_GROUP << 16) | PROSE_CHILD;
	private static final int PROSE_SCROLLBAR_ID = (SKILL_GUIDE_NEW_GROUP << 16) | 0x10; // its scrollbar
	private String lastProseSig = ""; // debounce: only reflow the prose once its raw text settles
	private String committedSig = null; // the effective-English frame we last fully laid out (skip if unchanged)
	// Collection settle gate (2026-07-16 council action 6): missing rows and AI disk-cache writes only
	// happen once the prose signature has held still this many consecutive ticks (~300ms). Frames still
	// translate and render immediately - mid-relayout scrambles just never persist anywhere.
	private static final int COLLECT_SETTLE_TICKS = 15;
	private int settleTicks;
	private boolean collectOk;
	private final List<String> pendingCollect = new ArrayList<>(); // keys laid before settle; collected once stable
	private int gatedRuns; // debug: runs translated while the gate was closed (undercollection stays visible)
	private Integer proseNativeScrollHeight = null; // container scrollHeight before we shrank it
	private int appliedScrollHeight = -1; // what we last set; -2 = gave up (a clientscript keeps fighting us)
	private int scrollFights = 0;
	private String failedSig = null; // frame that last failed layout (translation pending): retry throttle
	private int pendingCooldown = 0;
	private boolean pendingHasAi = false; // last incomplete pass waited on AI (throttle) vs glyph upload (don't)
	private int sigTick = 0; // committed-state signature is only rebuilt every 8th tick (cost control)

	/**
	 * Reflow the new-style skill guide (group 860), whose prose is split one word per widget, into readable
	 * Chinese. Title, tabs and item/quest lists are whole labels translated in place ({@link #translateLabel});
	 * the prose column (child {@code 0x0e}) is reflowed by {@link #reflowProse}, which pins each translated
	 * line to the client's own line grid so fixed-position sprite icons stay put and inline links stay
	 * clickable. Gated on {@code skillGuideOverlay}.
	 */
	private void reconstructWordSplit()
	{
		if (!config.skillGuideOverlay())
		{
			return;
		}
		Widget root = client.getWidget(SKILL_GUIDE_NEW_GROUP, 0);
		if (root == null || root.isHidden())
		{
			return;
		}
		Widget container = client.getWidget(SKILL_GUIDE_NEW_GROUP, PROSE_CHILD);
		if (container == null)
		{
			return; // interface mid-close
		}
		List<Widget> slots = new ArrayList<>();
		collectTextSlots(root, slots);
		// The description column (widget child 0x0e) is real prose split one word per widget: reflow it
		// (icons, inline links and headers inside it are handled by reflowProse). Everything else - title,
		// tabs, and the item / quest name lists - is a complete label per widget, so translate those in
		// place (setText keeps the widget and its click target, so tabs stay clickable).
		List<Widget> prose = new ArrayList<>();
		for (Widget w : slots)
		{
			if ((w.getId() & 0xFFFF) == PROSE_CHILD)
			{
				// Only the container's DIRECT children take part in the flow. The wiki banner is a type-0
				// sub-layer child whose own children (caps/bars/badge/text) carry coordinates relative to
				// the LAYER (0..20) - flowed raw they shredded paragraph one. The banner moves as one unit.
				if (w.getParent() == container && flowMember(w))
				{
					prose.add(w);
				}
			}
			else
			{
				translateLabel(w);
			}
		}
		// The prose column also holds TEXTLESS children - sprite icons and horizontal divider lines
		// (getText()==null, so collectTextSlots skips them). They are part of the reading flow and must be
		// repositioned with the text, so collect them here.
		Widget[] kids = container.getDynamicChildren();
		if (kids != null)
		{
			for (Widget w : kids)
			{
				if (w == null)
				{
					continue;
				}
				if (w.getText() == null && w.getSpriteId() > 0 && flowMember(w))
				{
					prose.add(w);
				}
				// A sub-layer (the wiki banner) stays out of the flow, but its own label ("View X on the
				// Wiki") is translated in place - text only, geometry untouched, so the banner keeps its
				// centring and click behaviour.
				if (w.getType() == 0 && !w.isSelfHidden())
				{
					for (Widget[] group : new Widget[][]{
							w.getDynamicChildren(), w.getStaticChildren(), w.getNestedChildren()})
					{
						if (group == null)
						{
							continue;
						}
						for (Widget c : group)
						{
							if (c != null && c.getText() != null && !c.getText().isEmpty())
							{
								translateLabel(c);
							}
						}
					}
				}
			}
		}
		reflowProse(container, prose);
	}

	// The wiki banner's frame furniture: end caps (917/919, 9x16), long bars (918/920, 173x9) and the WIKI
	// badge (2420, 40x14). They are absolutely positioned at y=0..20 (the client places the drawn banner
	// itself) yet render nowhere near there, so flowing them shredded paragraph one with invisible spacers.
	// The banner's functional part - the "View X on the Wiki" icon+link row - is separate and flows fine.
	private static final Set<Integer> BANNER_SPRITES = new HashSet<>(java.util.Arrays.asList(917, 918, 919, 920, 2420));

	/**
	 * True when a prose-column child takes part in the reading flow. Excluded: hidden slots, pool widgets
	 * still parked at (0,0), and - crucially - anything not ABSOLUTELY positioned. The wiki banner's frame
	 * (side caps, 173px bars, the WIKI badge and its text) is anchored to the container's bottom, so its
	 * raw coordinates read 0..20 and once sorted the whole banner shredded itself into paragraph one. The
	 * client keeps anchored widgets placed correctly on its own, including after we shrink the scroll area.
	 */
	private boolean flowMember(Widget w)
	{
		return !w.isSelfHidden() && !parkedAtOrigin(w)
				&& w.getXPositionMode() == 0 && w.getYPositionMode() == 0
				// banner furniture carries empty TEXT, so it arrives through the text walk - the sprite-id
				// quarantine must sit here on the shared path, not in the textless-sprite loop
				&& !BANNER_SPRITES.contains(w.getSpriteId());
	}

	/**
	 * True for a pool widget still parked at (0,0): the client creates children there and positions them a
	 * step later. Laying one out would prepend it to the flow (real prose starts at x/y >= 2). The ledger is
	 * consulted so a widget WE moved - whose live position is ours, not the pool's - is never mistaken for
	 * parked.
	 */
	private boolean parkedAtOrigin(Widget w)
	{
		return nativeX(w) == 0 && nativeY(w) == 0;
	}

	/** In-place whole-label translation of one widget (title / tab / item / quest name), keeping it clickable. */
	private void translateLabel(Widget w)
	{
		String t = w.getText();
		if (t == null || t.isEmpty() || t.contains("<img="))
		{
			return;
		}
		long key = widgetKey(w);
		if (t.equals(lastSet.get(key)))
		{
			return;
		}
		int size = glyph.uiSize();
		int maxChars = glyph.wrapChars(w.getWidth() - WRAP_PAD, size);
		if (maxChars < MIN_WRAP)
		{
			maxChars = 0; // short labels (tabs) shouldn't force-wrap
		}
		// Full interface render: splits <br> (item name + "Requires:" line), looks each line up, and keeps
		// the <col> requirement colour - item / quest names sit in the tables like any other UI text.
		Translator.Rendered r = translator.renderUi(t, w.getTextColor(), maxChars, size, cfgAiInterface);
		if (r == null)
		{
			return;
		}
		original.put(key, t);
		w.setText(r.text);
		w.setTextShadowed(false);
		if (r.text.contains("<br>"))
		{
			w.setLineHeight(glyph.glyphHeight(size));
		}
		lastSet.put(key, r.text);
	}

	private enum ProseKind
	{
		WORD,   // translatable prose word
		ICON,   // game sprite / divider line - flows as inline or block decoration
		LINK,   // clickable cross-reference (<u=ffff00>...</u>) - translate in place, keep the widget
		HITBOX, // transparent rectangle carrying a link's click listener: moved to wherever its link goes
		HEADER, // white section title (e.g. "Getting Started")
		OURS    // a slot we already translated or blanked this session (idempotent skip)
	}

	/**
	 * Classify one prose slot. Widget TYPE comes first: the real 860 dump shows sprites/dividers/hitboxes
	 * all carry an EMPTY text (not null), so a text-based check would misfile them as spacers - the exact
	 * bug that left icons stranded under the compacted text. Types: 3=rectangle (the invisible click hitbox
	 * of a link, opacity 255 + listener), 5=graphic (icon sprite), 9=line (divider).
	 */
	private ProseKind classify(Widget w)
	{
		int type = w.getType();
		if (type == 5 || type == 9)
		{
			return ProseKind.ICON;
		}
		if (type == 3)
		{
			// Only a LINE-SIZED rectangle is a link hitbox. The container also holds a huge transparent
			// rectangle (full-panel click zone, y=0): row-matching against it once backed the entire first
			// text row as "links" and shattered the paragraph into yellow fragments. Never touch it.
			return w.getHeight() <= 24 && w.getWidth() <= 250 ? ProseKind.HITBOX : ProseKind.OURS;
		}
		long key = widgetKey(w);
		String cur = w.getText();
		if (cur == null)
		{
			return ProseKind.ICON;
		}
		if (cur.equals(lastSet.get(key)))
		{
			return ProseKind.OURS; // exactly our char-image head or our blank
		}
		if (cur.isEmpty())
		{
			return ProseKind.OURS; // client spacer / already blank
		}
		if (cur.contains("<img="))
		{
			return ProseKind.ICON;
		}
		// A link is underlined or (yellow AND actually clickable). A merely-yellow word with no listener is
		// prose emphasis: keep it in the word run so the sentence translates whole instead of fragmenting.
		if (cur.contains("<u=") || ((w.getTextColor() & 0xFFFFFF) == 0xffff00 && w.hasListener()))
		{
			return ProseKind.LINK;
		}
		if ((w.getTextColor() & 0xFFFFFF) == 0xffffff)
		{
			return ProseKind.HEADER;
		}
		return ProseKind.WORD;
	}

	/**
	 * Reflow the word-per-widget description column (child {@code 0x0e}) into compact readable Chinese by
	 * treating the whole column as one inline flow (like an HTML paragraph engine) laid back onto the native
	 * widgets. Reading order (sort by y then x) is walked with a running cursor (cx,cy): a run of words is
	 * translated whole and its Chinese is poured across lines one-line-per-widget (never folding many lines
	 * into one widget, which garbled before); a sprite icon is repositioned inline to the cursor so it flows
	 * with the text it annotates (never left at its English x, which floated before); an inline link is
	 * rendered yellow into its own widget (click listener kept) at the cursor; a white header breaks the
	 * line. Because Chinese is denser the flow always ends higher than the English did, so it compacts with
	 * no blank gaps and nothing overlaps. Everything moved records its native x/y for restore.
	 *
	 * <p>Each pass first restores our slots to English (so it re-lays from a clean frame in one tick, no
	 * flicker) then re-flows; it only runs once the effective English is stable two ticks and stops once a
	 * complete pass is committed. If the client rewrites a slot we own (tab switch) we drop our state and
	 * wait for the rebuild to settle.
	 */
	private void reflowProse(Widget container, List<Widget> prose)
	{
		if (prose.size() < 2)
		{
			return;
		}
		// Sort by *native* position (moved widgets report their stored original), so once we compact the flow
		// the reading order - and therefore the signature computed from it - stays stable. Sorting by the live
		// (moved) position would change the order every tick and thrash debounce/commit forever. Y goes
		// through row CLUSTERING (adjacent native ys within 8px = one visual row): icons sit a few px off
		// their row's text baseline, and a fixed 16px bucket once split an icon (y=138) from its own link
		// (y=140) across a bucket edge, tearing pairs apart. Clusters are gap-based, so no boundary exists.
		java.util.TreeSet<Integer> ys = new java.util.TreeSet<>();
		for (Widget w : prose)
		{
			ys.add(nativeY(w));
		}
		Map<Integer, Integer> rowOf = new HashMap<>();
		int rowIdx = -1;
		int prevY = Integer.MIN_VALUE;
		for (int y : ys)
		{
			if (y - prevY > 8)
			{
				rowIdx++;
			}
			rowOf.put(y, rowIdx);
			prevY = y;
		}
		prose.sort((a, b) -> {
			int ra = rowOf.get(nativeY(a));
			int rb = rowOf.get(nativeY(b));
			return ra != rb ? Integer.compare(ra, rb) : Integer.compare(nativeX(a), nativeX(b));
		});

		String decision;
		// Repopulation check runs EVERY tick, before anything can short-circuit, and walks the container's
		// FULL child array - including hidden widgets. A tab switch hides pooled widgets it doesn't need
		// instead of resetting them; state ops that only saw the visible list once purged the position
		// ledger of hidden-but-still-moved hitboxes/icons, and when they came back their old laid position
		// masqueraded as "native" (links shattering paragraph one, icons on wrong rows, the vanishing wiki).
		String repop = repopReason(container);
		if (repop != null)
		{
			decommitRepop(container);
			committedSig = null;
			failedSig = null;
			lastProseSig = effectiveEnglishSig(container, prose);
			restartSettling();
			decision = "REPOP[" + repop + "]";
		}
		else if (committedSig != null)
		{
			// Committed steady state. Keep the scroll region we shrank pinned (a clientscript may re-grow it)
			// and clamp scrollY into range every tick; only rebuild the (expensive) signature every 8th tick.
			maintainProseScroll(container);
			if ((++sigTick & 7) != 0)
			{
				settleTicks++;
				collectSettled();
				decision = "SKIP";
			}
			else
			{
				String sig = effectiveEnglishSig(container, prose);
				if (sig.equals(committedSig))
				{
					settleTicks++;
					collectSettled();
					decision = "SKIP";
				}
				else if (!sig.equals(lastProseSig))
				{
					lastProseSig = sig; // a non-owned slot changed: wait for it to hold still
					restartSettling();
					decision = "DEBOUNCE";
				}
				else
				{
					committedSig = null; // stable divergent frame: drop the commit so the next tick re-lays
					restartSettling();
					decision = "DEBOUNCE";
				}
			}
		}
		else
		{
			String sig = effectiveEnglishSig(container, prose);
			if (!sig.equals(lastProseSig))
			{
				lastProseSig = sig;
				restartSettling();
				decision = "DEBOUNCE"; // still settling: wait for two identical ticks
			}
			else if (sig.equals(failedSig) && pendingCooldown-- > 0)
			{
				settleTicks++;
				decision = "LAID_WAIT"; // translation still pending: don't re-attempt 50x/s
			}
			else
			{
				settleTicks++;
				collectOk = settleTicks >= COLLECT_SETTLE_TICKS;
				// Re-lay from a clean English frame (revert our slots first, all within this one tick). The
				// native-coordinate snapshot is taken BEFORE the revert: relative coordinates only refresh
				// when the client re-lays the frame, so reading them back mid-tick after our own writes is
				// unreliable - the ledger/snapshot is the single source of truth for native geometry.
				Map<Long, int[]> nat = new HashMap<>();
				for (Widget w : prose)
				{
					nat.put(widgetKey(w), new int[]{nativeX(w), nativeY(w)});
				}
				restoreOwnedToEnglish(container);
				boolean complete = layoutInline(container, prose, nat, glyph.uiSize());
				if (complete)
				{
					committedSig = sig;
					failedSig = null;
				}
				else if (pendingHasAi)
				{
					committedSig = null;
					failedSig = sig;
					pendingCooldown = 30; // ~600ms before re-asking the AI about this same frame
				}
				else
				{
					committedSig = null;
					failedSig = null; // glyphs upload within a frame or two: retry every tick, no cooldown
				}
				decision = complete ? "LAID_OK" : "LAID_PENDING";
			}
		}
	}

	/**
	 * Signature of the column's effective English (our stored original where we own a slot, else live text),
	 * plus the container width (a resize must re-layout) and each sprite's native geometry (an icon moving
	 * or resizing natively means the client rebuilt the page).
	 */
	private String effectiveEnglishSig(Widget container, List<Widget> prose)
	{
		StringBuilder sb = new StringBuilder();
		sb.append(container.getWidth()).append('\n');
		for (Widget w : prose)
		{
			long key = widgetKey(w);
			String cur = w.getText();
			if (cur == null)
			{
				sb.append("SPR:").append(w.getSpriteId());
			}
			else
			{
				boolean ours = cur.equals(lastSet.get(key));
				sb.append(ours ? original.getOrDefault(key, "") : cur);
			}
			// Native geometry is part of the frame identity: the client fills pooled widgets in stages (text
			// first, position a frame later), and laying out such a half-placed frame filed the wiki link
			// into the middle of paragraph one. Position changes now fail the debounce until settled.
			sb.append('@').append(nativeX(w)).append(',').append(nativeY(w)).append('\n');
		}
		return sb.toString();
	}

	/**
	 * Non-null with a short diagnostic when the client repopulated a slot we own. Text mismatch on an owned
	 * slot is the primary signal; geometry is compared through {@code getOriginalX/Y} - the very fields we
	 * wrote - because relative coordinates only update when the client re-lays the frame, so comparing them
	 * right after our own pass false-positives and decommits our freshly laid page into a blank. Walks the
	 * container's FULL child array so hidden pooled widgets are covered too.
	 */
	private String repopReason(Widget container)
	{
		Widget[] kids = container.getDynamicChildren();
		if (kids == null)
		{
			return null;
		}
		for (Widget w : kids)
		{
			if (w == null)
			{
				continue;
			}
			long key = widgetKey(w);
			String cur = w.getText();
			if (lastSet.containsKey(key) && cur != null && !cur.equals(lastSet.get(key)))
			{
				return "TXT idx=" + w.getIndex();
			}
			// Geometry: the client rebuilding the page rewrites original x/y to its English layout.
			Integer px = placedX.get(key);
			if (px != null && (w.getOriginalX() != px || w.getOriginalY() != placedY.get(key)))
			{
				return "GEO idx=" + w.getIndex() + " orig=" + w.getOriginalX() + "," + w.getOriginalY()
						+ " placed=" + px + "," + placedY.get(key);
			}
		}
		return null;
	}

	/**
	 * Tab-switch decommit: blank our char-images (never refill stored English - the client is repopulating
	 * these pooled slots and stale refills both flash ghost text and can leak garbage sentences into the AI
	 * cache), revert geometry only where the original fields still corroborate as ours, then purge ALL prose
	 * state for this container (a shrinking tab reuses indexes, so per-member removal leaves ghost entries).
	 * MUST walk the full child array: hidden pooled widgets we moved would otherwise keep our laid position
	 * while the purge below forgets their true native one - the position then poisons every later layout.
	 */
	private void decommitRepop(Widget container)
	{
		Widget[] kids = container.getDynamicChildren();
		if (kids != null)
		{
			for (Widget w : kids)
			{
				if (w == null)
				{
					continue;
				}
				long key = widgetKey(w);
				String cur = w.getText();
				if (lastSet.containsKey(key) && cur != null && cur.equals(lastSet.get(key)) && cur.contains("<img="))
				{
					w.setText("");
					w.setTextShadowed(true); // the client's repopulation reuses the slot with native shadow
				}
				Integer px = placedX.get(key);
				boolean corroborated = px == null
						|| (w.getOriginalX() == px && w.getOriginalY() == placedY.get(key));
				if (corroborated)
				{
					revertGeom(key, w);
				}
				// not corroborated = the client already re-laid this widget itself: leave its geometry alone
			}
		}
		purgeProseState();
		restoreProseScroll();
	}

	/** Forget every prose-state entry for the 860 content column, including ghost indexes this tab never used. */
	private void purgeProseState()
	{
		java.util.function.Predicate<Long> isProse = k -> (k >>> 21) == (PROSE_COMPONENT_ID & 0xFFFFFFFFL);
		lastSet.keySet().removeIf(isProse);
		lastMiss.keySet().removeIf(isProse);
		original.keySet().removeIf(isProse);
		lastColor.keySet().removeIf(isProse);
		incomplete.removeIf(isProse);
		movedX.keySet().removeIf(isProse);
		movedY.keySet().removeIf(isProse);
		movedW.keySet().removeIf(isProse);
		placedX.keySet().removeIf(isProse);
		placedY.keySet().removeIf(isProse);
	}

	/**
	 * Revert every slot we own to its stored English and native position, and forget it (clean re-layout
	 * base). Walks the container's full child array so hidden pooled widgets we moved revert too.
	 */
	private void restoreOwnedToEnglish(Widget container)
	{
		Widget[] kids = container.getDynamicChildren();
		if (kids == null)
		{
			return;
		}
		for (Widget w : kids)
		{
			if (w == null)
			{
				continue;
			}
			long key = widgetKey(w);
			boolean owned = lastSet.containsKey(key) || movedX.containsKey(key);
			if (!owned)
			{
				continue;
			}
			String eng = original.get(key);
			if (eng != null)
			{
				w.setText(eng); // both char-image heads and blanked words carry their original English word
				w.setTextShadowed(true); // we disabled the shadow for glyphs; native prose is shadowed
			}
			revertGeom(key, w);
			original.remove(key);
			lastColor.remove(key);
			lastSet.remove(key);
			lastMiss.remove(key);
			incomplete.remove(key);
		}
	}

	/** One resolved atom of the inline flow: a word run, an icon, an inline link, or a white header. */
	private static final class FlowItem
	{
		static final int WORD = 0;
		static final int ICON = 1;
		static final int LINK = 2;
		static final int HEADER = 3;
		int kind;
		List<Widget> widgets; // run words (or merged header slots); a single-element list for icon/link
		String zh;            // translated Chinese (null for icons)
		int color;
		int iconWidth;
		int iconHeight;
		int iconNativeX;      // native x from the snapshot (a block keeps it so centering survives)
		boolean block;        // full-width decoration (divider line): own row, keep native x
		boolean lineStart;    // icon that natively begins a line (skill-list rows): keep it starting one
		boolean gapBefore;    // an English paragraph break precedes this item
	}

	/**
	 * The inline flow: walk the (now all-English) column in reading order and lay it out onto the native
	 * widgets under a compacting cursor. Runs all-or-nothing - phase 1 translates every run/link/header
	 * without touching a widget; if <em>any</em> is still pending (AI off/loading, or glyphs uploading) it
	 * returns false immediately so the whole column stays English (no half-translated, jittering frame).
	 * Only when everything is ready does phase 2 pour the Chinese in, reposition icons/dividers inline, and
	 * blank the leftover word slots. Finishes by shrinking the scroll region to the compacted height.
	 */
	private boolean layoutInline(Widget container, List<Widget> prose, Map<Long, int[]> nat, int size)
	{
		int gw = glyph.glyphWidth(size);
		int lineH = glyph.glyphHeight(size) + 2; // +2 leading: the raw glyph ink height sets lines touching
		boolean ai = cfgAiInterface;

		// All geometry below reads the pre-revert native snapshot (nat), never live relative coordinates:
		// mid-tick relative values are stale after our own writes and would corrupt grouping and the ledger.
		int col = 0;
		int leftMargin = Integer.MAX_VALUE;
		int startY = Integer.MAX_VALUE;
		for (Widget w : prose)
		{
			ProseKind k = classify(w);
			if (k == ProseKind.OURS || k == ProseKind.HITBOX)
			{
				continue; // hitboxes shadow their link's row: they must not skew the margins
			}
			int[] p = nat.get(widgetKey(w));
			if (k == ProseKind.WORD || k == ProseKind.LINK)
			{
				leftMargin = Math.min(leftMargin, p[0]);
			}
			startY = Math.min(startY, p[1]);
			col = Math.max(col, p[0] + w.getWidth());
		}
		if (col < MIN_WRAP * gw || leftMargin == Integer.MAX_VALUE)
		{
			return true; // nothing to lay out
		}
		if (startY == Integer.MAX_VALUE)
		{
			startY = 4;
		}

		// NOTE: links are identified by their text alone (<u=..> / yellow+listener). An earlier "hitbox
		// backing" classifier looked tidy but hitboxes spawn at (0,0) before the client positions them, and
		// row-matching those turned the first text row into fake links. Hitboxes are only ever PAIRED to an
		// already-identified link for repositioning, never used to classify.

		// Phase 1: build + translate every item, no widget mutation. If anything is still pending we keep
		// WALKING (so every missing sentence fires its async AI request in this same pass and they all
		// translate concurrently) and only then report incomplete. Bailing at the first pending key made
		// page warm-up serial: one new key discovered per retry cooldown, tens of seconds for a fresh page.
		boolean ready = true;
		pendingHasAi = false;
		List<FlowItem> items = new ArrayList<>();
		List<Widget> hitboxes = new ArrayList<>();
		int prevNativeY = -1;
		int i = 0;
		while (i < prose.size())
		{
			Widget a = prose.get(i);
			ProseKind k = classify(a);
			if (k == ProseKind.OURS)
			{
				i++;
				continue;
			}
			if (k == ProseKind.HITBOX)
			{
				// a link's invisible click rectangle: repositioned onto its link after the links are placed.
				// It must not update prevNativeY (it shares the link's row) or take part in the flow itself.
				hitboxes.add(a);
				i++;
				continue;
			}
			int ay = nat.get(widgetKey(a))[1];
			boolean gap = prevNativeY >= 0 && ay - prevNativeY > 20;

			if (k == ProseKind.ICON)
			{
				FlowItem it = new FlowItem();
				it.kind = FlowItem.ICON;
				it.widgets = java.util.Collections.singletonList(a);
				it.iconWidth = Math.max(a.getWidth(), 1);
				it.iconHeight = Math.max(a.getHeight(), 1);
				// near-column-wide, tall, or an actual LINE widget = page decoration (divider), not inline
				it.block = a.getType() == 9
						|| it.iconWidth >= (col - leftMargin) * 6 / 10 || it.iconHeight > 2 * lineH;
				it.iconNativeX = nat.get(widgetKey(a))[0];
				// an icon that natively started its line (the skill-interaction rows) keeps starting one, so
				// those entries read one-per-line like the English page instead of running together
				it.lineStart = it.iconNativeX <= leftMargin + 4;
				it.gapBefore = gap;
				items.add(it);
				prevNativeY = ay;
				i++;
				continue;
			}
			if (k == ProseKind.HEADER)
			{
				// A header may itself be split word-per-widget: merge consecutive same-row header slots into
				// one item so it translates whole instead of once per fragment.
				List<Widget> parts = new ArrayList<>();
				StringBuilder rawH = new StringBuilder();
				int j = i;
				while (j < prose.size())
				{
					Widget hw = prose.get(j);
					if (classify(hw) != ProseKind.HEADER || nat.get(widgetKey(hw))[1] != ay)
					{
						break;
					}
					parts.add(hw);
					if (rawH.length() > 0)
					{
						rawH.append(' ');
					}
					rawH.append(hw.getText());
					j++;
				}
				String zh = plainZh(rawH.toString(), ai);
				if (zh == null || glyph.toImgTags(zh, 0xffffff, 0, size) == null)
				{
					ready = false; // keep walking: warm every remaining translation this pass
					pendingHasAi |= zh == null;
					prevNativeY = ay;
					i = j;
					continue;
				}
				FlowItem it = new FlowItem();
				it.kind = FlowItem.HEADER;
				it.widgets = parts;
				it.zh = zh;
				it.color = parts.get(0).getTextColor() & 0xFFFFFF;
				it.gapBefore = gap;
				items.add(it);
				prevNativeY = ay;
				i = j;
				continue;
			}
			if (k == ProseKind.LINK)
			{
				// links carry their colour in the <u=RRGGBB> tag (yellow normally, GREEN for a completed
				// quest) - render the Chinese in the same colour instead of hardcoding yellow
				int lc = linkColor(a.getText(), a.getTextColor() & 0xFFFFFF);
				String zh = plainZh(a.getText(), ai);
				if (zh == null || glyph.toImgTags(zh, lc, 0, size) == null)
				{
					ready = false;
					pendingHasAi |= zh == null;
					prevNativeY = ay;
					i++;
					continue;
				}
				FlowItem it = new FlowItem();
				it.kind = FlowItem.LINK;
				it.widgets = java.util.Collections.singletonList(a);
				it.zh = zh;
				it.color = lc;
				it.gapBefore = gap;
				items.add(it);
				prevNativeY = ay;
				i++;
				continue;
			}

			// WORD run: gather consecutive words (no big native y-gap).
			List<Widget> words = new ArrayList<>();
			StringBuilder raw = new StringBuilder();
			int lastY = ay;
			int maxNativeY = ay;
			int j = i;
			while (j < prose.size())
			{
				Widget ww = prose.get(j);
				if (classify(ww) != ProseKind.WORD)
				{
					break;
				}
				int wy = nat.get(widgetKey(ww))[1];
				if (j > i && wy - lastY > 20)
				{
					break; // paragraph gap
				}
				words.add(ww);
				if (raw.length() > 0)
				{
					raw.append(' ');
				}
				raw.append(ww.getText());
				lastY = wy;
				maxNativeY = Math.max(maxNativeY, wy);
				j++;
			}
			int bodyColor = dominantColor(words, a.getTextColor());
			String english = JournalReconstructor.strip(raw.toString()).trim();
			String zh = english.isEmpty() ? null : plainZh(english, ai);
			if (zh == null)
			{
				// Tiny glue fragments between two adjacent links ("or a", "on the") miss the tables and the
				// AI refuses them - they'd block the whole page forever. Map the common ones, pass any other
				// short scrap through as literal English; only real sentences may hold the page pending.
				zh = glueZh(english);
			}
			if (zh == null || glyph.toImgTags(zh, bodyColor, 0, size) == null)
			{
				ready = false; // keep walking so the remaining runs fire their AI requests too
				pendingHasAi |= zh == null;
				prevNativeY = maxNativeY;
				i = j;
				continue;
			}
			FlowItem it = new FlowItem();
			it.kind = FlowItem.WORD;
			it.widgets = words;
			it.zh = zh;
			it.color = bodyColor;
			it.gapBefore = gap;
			items.add(it);
			prevNativeY = maxNativeY;
			i = j;
		}
		if (!ready)
		{
			return false; // some translations still pending (all fired concurrently above): retry next tick
		}

		// Phase 2: everything is ready - pour it onto the widgets under the compacting cursor. rowH is the
		// current line's height (an inline icon taller than the text grows the row instead of overlapping the
		// next line); every line break advances cy by rowH then resets it.
		int padPx = gw; // right-edge safety margin inside the column
		int cx = leftMargin;
		int cy = startY;
		int rowH = lineH;
		for (FlowItem it : items)
		{
			if (it.gapBefore)
			{
				if (cx > leftMargin)
				{
					cx = leftMargin;
					cy += rowH;
					rowH = lineH;
				}
				cy += lineH / 2; // preserve the paragraph break as a half-line gap
			}
			if (it.kind == FlowItem.ICON)
			{
				Widget icon = it.widgets.get(0);
				seedNative(icon, nat);
				if (it.block)
				{
					// divider / full-width art: own row, keep its native x (centering stays intact)
					if (cx > leftMargin)
					{
						cx = leftMargin;
						cy += rowH;
						rowH = lineH;
					}
					moveWidget(icon, it.iconNativeX, cy);
					icon.revalidate();
					cy += it.iconHeight + 4;
					continue;
				}
				if (cx > leftMargin && (it.lineStart || cx + it.iconWidth > col))
				{
					cx = leftMargin;
					cy += rowH;
					rowH = lineH;
				}
				moveWidget(icon, cx, cy);
				icon.revalidate();
				rowH = Math.max(rowH, it.iconHeight);
				cx += it.iconWidth + 2;
				continue;
			}
			if (it.kind == FlowItem.HEADER)
			{
				if (cx > leftMargin)
				{
					cx = leftMargin;
					cy += rowH;
					rowH = lineH;
				}
				seedNative(it.widgets.get(0), nat);
				int lines = placeSingle(it.widgets.get(0), it.zh, it.color, false,
						leftMargin, cy, col - leftMargin - padPx, size, gw, lineH);
				for (int p = 1; p < it.widgets.size(); p++)
				{
					blankWord(it.widgets.get(p)); // merged header fragments
				}
				cy += lines * lineH;
				continue;
			}
			if (it.kind == FlowItem.LINK)
			{
				int w = advancePx(it.zh, gw);
				if (cx > leftMargin && cx + w > col - padPx)
				{
					cx = leftMargin;
					cy += rowH;
					rowH = lineH;
				}
				seedNative(it.widgets.get(0), nat);
				int lines = placeSingle(it.widgets.get(0), it.zh, it.color, true,
						cx, cy, col - cx - padPx, size, gw, lineH);
				// The click listener lives on a separate invisible rectangle at the link's ENGLISH spot
				// (860 dump: type=3, opacity 255, hasListener) - drag it onto the Chinese or the link is dead.
				placeLinkHitbox(it.widgets.get(0), hitboxes, nat, cx, cy,
						Math.min(w, col - cx - padPx));
				if (lines > 1)
				{
					cy += (lines - 1) * lineH;
					cx = leftMargin; // a wrapped link ends its row; prose resumes on the next line
					cy += rowH;
					rowH = lineH;
				}
				else
				{
					cx += w + 2;
				}
				continue;
			}

			// WORD run: wrap by pixel budget (first line = what's left of the current row, rest = full column)
			// and pour one line per word widget at the cursor.
			List<Widget> words = it.widgets;
			if (cx == leftMargin)
			{
				// a run that begins at a line start must not open with closing punctuation (", 你需要..."
				// happens when the preceding fragment became a header/link) - drop the orphaned leaders
				it.zh = trimLeadingPunct(it.zh);
			}
			int firstPx = col - cx - padPx;
			int restPx = col - leftMargin - padPx;
			if (firstPx < 2 * gw && cx > leftMargin)
			{
				cx = leftMargin;
				cy += rowH;
				rowH = lineH;
				firstPx = restPx;
			}
			List<String> lines = glyph.wrapPlain(it.zh, firstPx, restPx, size);
			if (lines.size() > words.size() && cx > leftMargin)
			{
				// more lines than slots from a mid-row start: restart the run at the left margin (each line
				// then gets the full column, minimising lines) before falling back to slot absorption
				cx = leftMargin;
				cy += rowH;
				rowH = lineH;
				lines = glyph.wrapPlain(it.zh, restPx, restPx, size);
			}
			int lastStartX = cx;
			for (int k = 0; k < lines.size() && k < words.size(); k++)
			{
				boolean last = k == words.size() - 1 && lines.size() > words.size();
				int x = k == 0 ? cx : leftMargin;
				if (k > 0)
				{
					cy += rowH;
					rowH = lineH;
				}
				lastStartX = x;
				seedNative(words.get(k), nat);
				if (last)
				{
					// final slot absorbs every remaining line (it sits at the left margin by construction)
					StringBuilder rem = new StringBuilder();
					int extra = 0;
					for (int p = k; p < lines.size(); p++)
					{
						String piece = glyph.toImgTags(lines.get(p), it.color, 0, size);
						if (piece == null)
						{
							continue;
						}
						if (rem.length() > 0)
						{
							rem.append("<br>");
							extra++;
						}
						rem.append(piece);
					}
					writeRunPiece(words.get(k), rem.toString(), col - x - padPx, x, cy, lineH, true);
					cy += extra * lineH;
					lastStartX = leftMargin;
				}
				else
				{
					String piece = glyph.toImgTags(lines.get(k), it.color, 0, size);
					if (piece != null)
					{
						writeRunPiece(words.get(k), piece, advancePx(lines.get(k), gw) + 2, x, cy, lineH, false);
					}
				}
			}
			for (int p = lines.size(); p < words.size(); p++)
			{
				blankWord(words.get(p));
			}
			cx = lastStartX + advancePx(lines.isEmpty() ? "" : lines.get(lines.size() - 1), gw) + 2;
		}
		// Park sub-layer children (the wiki banner) right under the compacted content: the banner natively
		// sits at the ENGLISH page bottom (e.g. y=716), far past the shrunk scroll height, i.e. invisible.
		// Moving the layer moves its children with it, so the banner arrives whole and functional.
		Widget[] all = container.getDynamicChildren();
		if (all != null)
		{
			List<Widget> layers = new ArrayList<>();
			for (Widget w : all)
			{
				if (w != null && w.getType() == 0 && !w.isSelfHidden() && w.getHeight() > 0
						&& w.getXPositionMode() == 0 && w.getYPositionMode() == 0 && !parkedAtOrigin(w))
				{
					layers.add(w);
				}
			}
			layers.sort(java.util.Comparator.comparingInt(this::nativeY));
			for (Widget layer : layers)
			{
				if (cx > leftMargin)
				{
					cx = leftMargin;
					cy += rowH;
					rowH = lineH;
				}
				cy += lineH / 2;
				moveWidget(layer, nativeX(layer), cy);
				layer.revalidate();
				cy += Math.max(layer.getHeight(), 1) + 4;
			}
		}
		applyProseScroll(container, cy + rowH);
		return true;
	}

	/**
	 * Move a link's invisible click hitbox onto the link's new position and width. The hitbox is a type-3
	 * transparent rectangle sharing the link's native row; it is matched by native geometry and consumed so
	 * a row with several links pairs each hitbox once. Without this the visible Chinese link is dead while
	 * an unmarked zone at the old English spot still clicks.
	 */
	private void placeLinkHitbox(Widget link, List<Widget> hitboxes, Map<Long, int[]> nat, int x, int y, int wPx)
	{
		int[] lp = nat.get(widgetKey(link));
		if (lp == null)
		{
			return;
		}
		for (java.util.Iterator<Widget> iter = hitboxes.iterator(); iter.hasNext(); )
		{
			Widget hb = iter.next();
			int[] hp = nat.get(widgetKey(hb));
			if (hp == null || Math.abs(hp[1] - lp[1]) > 8)
			{
				continue; // not this link's row
			}
			if (hp[0] > lp[0] + 200 || hp[0] + hb.getWidth() + 8 < lp[0])
			{
				continue; // no horizontal overlap with the link's native span
			}
			seedNative(hb, nat);
			long key = widgetKey(hb);
			movedW.putIfAbsent(key, hb.getOriginalWidth());
			moveWidget(hb, x, y);
			hb.setOriginalWidth(Math.max(wPx, 1));
			hb.setWidth(Math.max(wPx, 1));
			hb.revalidate();
			iter.remove();
			return;
		}
	}

	/**
	 * Seed the native-position ledger from the pre-revert snapshot before moving a widget. moveWidget's own
	 * putIfAbsent would read live relative coordinates, which are stale mid-tick right after our reverts and
	 * would poison the ledger with compacted positions as "native".
	 */
	private void seedNative(Widget w, Map<Long, int[]> nat)
	{
		long key = widgetKey(w);
		int[] p = nat.get(key);
		if (p != null)
		{
			movedX.putIfAbsent(key, p[0]);
			movedY.putIfAbsent(key, p[1]);
		}
	}

	private static final String NO_LEADING_PUNCT = "、。，．；：！？）｝】》」』〉〕…—·％”’,.;:!?)";

	/** Colour of a link from its {@code <u=RRGGBB>} tag (green = completed quest), else the widget colour. */
	private static int linkColor(String text, int fallback)
	{
		int u = text == null ? -1 : text.indexOf("<u=");
		if (u >= 0)
		{
			int end = text.indexOf('>', u);
			if (end > u + 3)
			{
				try
				{
					return Integer.parseInt(text.substring(u + 3, end).trim(), 16) & 0xFFFFFF;
				}
				catch (NumberFormatException ignored)
				{
					// plain <u> or malformed: fall through to the widget colour
				}
			}
		}
		return fallback;
	}

	/**
	 * Chinese for the glue scraps left between two adjacent inline links ("...with the [Fishing skill]
	 * or a [Range]..."). Tables miss them and the AI refuses such stubs, which would pin the whole page
	 * in English forever. Unknown scraps up to a few words pass through literally; longer text returns
	 * null and keeps the normal pending path.
	 */
	private static String glueZh(String english)
	{
		switch (english.toLowerCase(java.util.Locale.ROOT))
		{
			case "or":
			case "or a":
			case "or an":
			case "or on a":
			case "or the":
				return "或";
			case "and":
			case "and a":
			case "and an":
			case "and the":
				return "和";
			case "the":
			case "a":
			case "an":
			case "of":
			case "of the":
				return "";
			case "on":
			case "on a":
			case "on an":
			case "on the":
			case "in":
			case "in a":
			case "in the":
			case "at":
			case "at a":
			case "at the":
				return "在";
			case "with":
			case "with a":
			case "with the":
			case "using":
			case "using the":
				return "用";
			case "from":
			case "from a":
			case "from the":
				return "从";
			case "to":
			case "to a":
			case "to the":
				return "到";
			case "such as the":
			case "such as a":
			case "such as":
				return "例如";
			default:
				return english.length() <= 14 ? english : null; // short scrap: show literally, never block
		}
	}

	/** Drop closing punctuation (and following spaces) stranded at the start of a line-leading run. */
	private static String trimLeadingPunct(String zh)
	{
		int i = 0;
		while (i < zh.length()
				&& (NO_LEADING_PUNCT.indexOf(zh.charAt(i)) >= 0 || Character.isWhitespace(zh.charAt(i))))
		{
			i++;
		}
		return i == 0 ? zh : zh.substring(i);
	}

	/** Advance width in px of a rendered plain segment: CJK counts a full glyph, anything else half. */
	private static int advancePx(String plain, int gw)
	{
		int half = (gw + 1) / 2;
		int px = 0;
		for (int i = 0; i < plain.length(); )
		{
			int cp = plain.codePointAt(i);
			px += cp >= 0x2E80 ? gw : half;
			i += Character.charCount(cp);
		}
		return px;
	}

	private static final String SKILLGUIDE_TAG = "skillguide860"; // provenance tag on every collected 860 row
	private static final Pattern LEADING_PUNCT = Pattern.compile("^[,.;:!?]+\\s*");

	/** Translate a stripped English fragment to plain Chinese (tags removed), or null if pending. */
	private String plainZh(String english, boolean ai)
	{
		String raw = JournalReconstructor.strip(english == null ? "" : english).trim();
		if (raw.isEmpty())
		{
			return null;
		}
		// A run that starts right after an inline link keeps the link's trailing punctuation (", first
		// obtain a mould..."); the SANITISED form is the true table key, so only that form may ever be
		// collected - recording the punctuated raw would bake an unreachable key.
		Matcher lead = LEADING_PUNCT.matcher(raw);
		String key = lead.find() ? raw.substring(lead.end()) : raw;
		boolean clean = key.equals(raw);
		if (!collectOk && !key.isEmpty())
		{
			// gate closed (frame still settling): translate for the screen now, collect once it holds
			if (pendingCollect.size() < 400 && !pendingCollect.contains(key))
			{
				pendingCollect.add(key);
			}
			gatedRuns++;
		}
		// The exact key first: every table row and AI-cache entry accumulated so far lives under it.
		String zh = translator.translateJournalSentence(raw, ai, SKILLGUIDE_TAG, collectOk && clean);
		if (zh == null && !clean && !key.isEmpty())
		{
			zh = translator.translateJournalSentence(key, ai, SKILLGUIDE_TAG, collectOk);
		}
		return zh == null ? null : zh.replaceAll("<[^>]*>", ""); // char images can't carry residual tags
	}

	/**
	 * The frame stopped holding still (debounce / repopulation): restart the settle count AND drop the
	 * queue. Anything queued belonged to a frame that never proved stable - the client fills the guide's
	 * prose word by word across frames, so those fragments are half-sentences ("word salad"), and
	 * replaying them once a LATER frame settles is exactly how they used to reach the missing file.
	 * Nothing legitimate is lost: a frame that did hold still for {@link #COLLECT_SETTLE_TICKS} was
	 * already flushed by {@link #collectSettled()} on one of those ticks, which empties the queue.
	 */
	private void restartSettling()
	{
		settleTicks = 0;
		collectOk = false;
		pendingCollect.clear();
	}

	/**
	 * The frame held still long enough: replay the (cheap, lookup-only) translations of everything
	 * laid before the gate opened, this time with collection on - so committing a fast layout never
	 * silently loses the rows, and nothing mid-relayout ever reaches the file.
	 */
	private void collectSettled()
	{
		if (settleTicks < COLLECT_SETTLE_TICKS || pendingCollect.isEmpty())
		{
			return;
		}
		for (String en : pendingCollect)
		{
			translator.translateJournalSentence(en, cfgAiInterface, SKILLGUIDE_TAG, true);
		}
		log.info("OSRSCN-860 settle-collect: {} runs recorded after {} stable ticks",
				pendingCollect.size(), settleTicks);
		pendingCollect.clear();
	}

	/**
	 * Write one rendered piece (a single line, or the absorbing tail with {@code <br>}s) into a word slot at
	 * (x,y) with an explicit pixel width. Width is recorded in {@code movedW} before mutation so the next
	 * layout can restore the native width - without that the column measurement reads our own widened slots
	 * and inflates a little more on every re-layout.
	 */
	private void writeRunPiece(Widget slot, String img, int widthPx, int x, int y, int lineH, boolean multi)
	{
		if (img == null || img.isEmpty())
		{
			return;
		}
		long key = widgetKey(slot);
		original.putIfAbsent(key, slot.getText() == null ? "" : slot.getText());
		movedW.putIfAbsent(key, slot.getOriginalWidth());
		slot.setText(img);
		slot.setTextShadowed(false);
		slot.setOriginalWidth(Math.max(widthPx, 1));
		slot.setWidth(Math.max(widthPx, 1));
		if (multi || img.contains("<br>"))
		{
			slot.setLineHeight(lineH);
		}
		moveWidget(slot, x, y);
		slot.revalidate();
		lastSet.put(key, img);
	}

	/**
	 * Place a single-widget label (header / link) at (x,y), wrapping to {@code availPx} when it is too wide
	 * (the extra lines stay inside this same widget, so a link's click listener covers all of them). Links
	 * keep their {@code <u=ffff00>} underline wrapper. Returns the number of lines written (0 = pending).
	 */
	private int placeSingle(Widget w, String zh, int color, boolean underline, int x, int y,
			int availPx, int size, int gw, int lineH)
	{
		List<String> lines = glyph.wrapPlain(zh, availPx, availPx, size);
		if (lines.isEmpty())
		{
			return 0;
		}
		StringBuilder sb = new StringBuilder();
		int maxPx = 0;
		for (int k = 0; k < lines.size(); k++)
		{
			String img = glyph.toImgTags(lines.get(k), color, 0, size);
			if (img == null)
			{
				return 0; // glyphs still uploading (phase 1 pre-checked, so this is a rare race)
			}
			if (k > 0)
			{
				sb.append("<br>");
			}
			sb.append(img);
			maxPx = Math.max(maxPx, advancePx(lines.get(k), gw));
		}
		String out = underline
				? "<u=" + String.format("%06x", color & 0xFFFFFF) + ">" + sb + "</u>"
				: sb.toString();
		long key = widgetKey(w);
		original.putIfAbsent(key, w.getText() == null ? "" : w.getText());
		movedW.putIfAbsent(key, w.getOriginalWidth());
		w.setText(out);
		w.setTextShadowed(false);
		w.setOriginalWidth(Math.max(maxPx, gw)); // widget width == ink width: no dead click-zone past the text
		w.setWidth(Math.max(maxPx, gw));
		if (lines.size() > 1)
		{
			w.setLineHeight(lineH);
		}
		moveWidget(w, x, y);
		w.revalidate();
		lastColor.put(key, color);
		lastSet.put(key, out);
		return lines.size();
	}

	/** Blank a word slot the flow didn't need (its Chinese went into an earlier line-head). */
	private void blankWord(Widget w)
	{
		long key = widgetKey(w);
		if (!original.containsKey(key))
		{
			original.put(key, w.getText() == null ? "" : w.getText());
		}
		w.setText("");
		lastSet.put(key, "");
	}

	/** Move a prose widget to (x,y) in the compacted flow, remembering its native position to revert later. */
	private void moveWidget(Widget w, int x, int y)
	{
		long key = widgetKey(w);
		movedX.putIfAbsent(key, w.getRelativeX());
		movedY.putIfAbsent(key, w.getRelativeY());
		placedX.put(key, x); // always the latest target: live != placed later means the client moved it
		placedY.put(key, y);
		w.setOriginalX(x);
		w.setOriginalY(y);
	}

	/** Native (pre-move) x/y of a prose widget: the stored original if we moved it, else its live position. */
	private int nativeX(Widget w)
	{
		Integer x = movedX.get(widgetKey(w));
		return x != null ? x : w.getRelativeX();
	}

	private int nativeY(Widget w)
	{
		Integer y = movedY.get(widgetKey(w));
		return y != null ? y : w.getRelativeY();
	}

	/** Put a moved prose widget back at its native position and width (English toggle / decommit). */
	private void revertGeom(long key, Widget w)
	{
		Integer ox = movedX.remove(key);
		Integer oy = movedY.remove(key);
		Integer ow = movedW.remove(key);
		placedX.remove(key);
		placedY.remove(key);
		if (ox != null)
		{
			w.setOriginalX(ox);
		}
		if (oy != null)
		{
			w.setOriginalY(oy);
		}
		if (ow != null)
		{
			w.setOriginalWidth(ow); // mirror both fields: the next layout reads getWidth() for the column
			w.setWidth(ow);
		}
		if (ox != null || oy != null || ow != null)
		{
			w.revalidate();
		}
	}

	// ===== 860 prose scroll-region management (the compacted Chinese is much shorter than the English) =====

	/** After a committed layout: shrink the scroll region to the Chinese content height. */
	private void applyProseScroll(Widget container, int contentBottom)
	{
		if (container.getScrollHeight() <= 0 || appliedScrollHeight == -2)
		{
			return; // not a scroll container, or a clientscript kept fighting us and we gave up
		}
		if (proseNativeScrollHeight == null)
		{
			proseNativeScrollHeight = container.getScrollHeight();
		}
		int newH = Math.max(container.getHeight(), contentBottom + 8);
		container.setScrollHeight(newH);
		int maxY = Math.max(0, newH - container.getHeight());
		if (container.getScrollY() > maxY)
		{
			container.setScrollY(maxY);
		}
		container.revalidateScroll();
		syncScrollbar(container);
		appliedScrollHeight = newH;
	}

	/**
	 * Tell the native scrollbar its range changed. Without this the bar keeps the OLD range: after we
	 * shrink for Chinese and the player toggles back to English, the bar refuses to scroll past the
	 * shrunken height and the page bottom is unreachable until a tab switch rebuilds it.
	 */
	private void syncScrollbar(Widget container)
	{
		client.runScript(net.runelite.api.ScriptID.UPDATE_SCROLLBAR,
				PROSE_SCROLLBAR_ID, PROSE_COMPONENT_ID, container.getScrollY());
	}

	/** Committed steady state: re-pin our scroll height if a clientscript re-grew it; clamp scrollY. */
	private void maintainProseScroll(Widget container)
	{
		if (appliedScrollHeight <= 0)
		{
			return;
		}
		if (container.getScrollHeight() != appliedScrollHeight)
		{
			if (++scrollFights > 5)
			{
				appliedScrollHeight = -2; // stop fighting: dead space at the bottom beats a tug-of-war
				return;
			}
			container.setScrollHeight(appliedScrollHeight);
			container.revalidateScroll();
			syncScrollbar(container);
		}
		int maxY = Math.max(0, appliedScrollHeight - container.getHeight());
		if (container.getScrollY() > maxY)
		{
			container.setScrollY(maxY);
		}
	}

	/** Give the scroll region back to the client (decommit / EN toggle / reset). */
	private void restoreProseScroll()
	{
		if (proseNativeScrollHeight != null)
		{
			Widget container = client.getWidget(SKILL_GUIDE_NEW_GROUP, PROSE_CHILD);
			if (container != null)
			{
				container.setScrollHeight(proseNativeScrollHeight);
				int maxY = Math.max(0, proseNativeScrollHeight - container.getHeight());
				if (container.getScrollY() > maxY)
				{
					container.setScrollY(maxY);
				}
				container.revalidateScroll();
				syncScrollbar(container);
			}
		}
		proseNativeScrollHeight = null;
		appliedScrollHeight = -1;
		scrollFights = 0;
	}

	/**
	 * Fully hand the 860 prose column back to the client: our text out, native geometry back, scroll region
	 * restored, all state purged. Used by {@link #reset()} (font change) and when the guide toggle is turned
	 * off. Safe when the interface is closed (only purges state then).
	 */
	public void revertSkillGuide()
	{
		Widget container = client.getWidget(SKILL_GUIDE_NEW_GROUP, PROSE_CHILD);
		if (container != null)
		{
			Widget[] kids = container.getDynamicChildren();
			if (kids != null)
			{
				for (Widget w : kids)
				{
					if (w == null)
					{
						continue;
					}
					long key = widgetKey(w);
					if (!lastSet.containsKey(key) && !movedX.containsKey(key))
					{
						continue; // never ours
					}
					String eng = original.get(key);
					String cur = w.getText();
					if (eng != null && cur != null && (cur.equals(lastSet.get(key)) || cur.contains("<img=")))
					{
						w.setText(eng);
						w.setTextShadowed(true);
					}
					revertGeom(key, w);
				}
			}
		}
		restoreProseScroll();
		purgeProseState();
		committedSig = null;
		failedSig = null;
		lastProseSig = "";
		settleTicks = 0;
		pendingCollect.clear();
	}

	/** Most common colour among a segment's words, so a stray coloured word doesn't tint the paragraph. */
	private static int dominantColor(List<Widget> words, int fallback)
	{
		HashMap<Integer, Integer> hist = new HashMap<>();
		int best = 0;
		int bestColor = fallback & 0xFFFFFF;
		for (Widget w : words)
		{
			int c = w.getTextColor() & 0xFFFFFF;
			int cnt = hist.merge(c, 1, Integer::sum);
			if (cnt > best)
			{
				best = cnt;
				bestColor = c;
			}
		}
		return bestColor;
	}

	private void reconstructRoot(int componentId)
	{
		Widget root = client.getWidget(componentId);
		if (root == null || root.isHidden())
		{
			return;
		}
		List<Widget> slots = new ArrayList<>();
		collectTextSlots(root, slots);
		if (slots.isEmpty())
		{
			return;
		}
		// Debounce the client's multi-stage population. When a diary opens / is switched the client first writes
		// the bare task sentences, then a frame later appends the colour-coded "(requirement)" (red = unmet, navy
		// = met, strike-through on met). Translating a half-built frame races that update and produces the flicker
		// / all-black / missing-requirement states. So only act once the raw slot text is identical two ticks
		// running, i.e. the client has finished building this diary. Our own translation changes the text too, so
		// this also means we re-evaluate once after writing (a harmless no-op tick).
		StringBuilder sigBuf = new StringBuilder();
		for (Widget w : slots)
		{
			String t = w.getText();
			sigBuf.append(t == null ? "" : t).append('\n');
		}
		String sig = sigBuf.toString();
		if (!sig.equals(journalSig.put(componentId, sig)))
		{
			journalStable.put(componentId, 0);
			return; // still settling: wait one more tick before translating
		}
		// One identical tick is enough to translate, but NOT to persist: this path used to record every
		// reconstructed sentence unconditionally, so a journal caught mid-population wrote half-sentences
		// into the missing file. Collection now needs the same COLLECT_SETTLE_TICKS the group-860 reflow
		// uses (~300ms of an unchanged frame); the screen still updates on the first stable tick.
		int stable = journalStable.merge(componentId, 1, Integer::sum);
		boolean collect = stable >= COLLECT_SETTLE_TICKS;
		String journalTag = "journal" + (componentId >>> 16); // provenance, like the 860 reflow's tag
		// When the diary / difficulty is switched (or the scroll rebuilt) the client reuses these widgets and
		// overwrites at least one slot we translated with fresh English. That can leave a *mixed* frame - one
		// slot fresh English, a sibling still our char-image - which the reconstructor mis-groups (it treats a
		// "<img=" slot as structural), so the leftover image gets stuck and the task's text vanishes and can no
		// longer be restored. To stay robust, detect any such overwrite and first "decommit" the whole root:
		// revert every slot we still own to its stored English and forget our state for this root, so the rest
		// of this method re-groups and re-translates the full task list from one clean all-English slate.
		boolean repopulated = false;
		for (Widget w : slots)
		{
			String t = w.getText();
			if (t != null && !t.isEmpty() && !t.contains("<img="))
			{
				String last = lastSet.get(widgetKey(w));
				if (last != null && !t.equals(last))
				{
					repopulated = true;
					break;
				}
			}
		}
		if (repopulated)
		{
			for (Widget w : slots)
			{
				long key = widgetKey(w);
				String cur = w.getText();
				String eng = original.get(key);
				// only revert slots that still hold exactly our char-image translation; never touch text the
				// client rewrote, and never push stored English into a blank (which the new diary may not use).
				if (eng != null && cur != null && cur.equals(lastSet.get(key)) && cur.contains("<img="))
				{
					w.setText(eng);
				}
				original.remove(key);
				lastSet.remove(key);
				lastMiss.remove(key);
				incomplete.remove(key);
			}
		}
		List<String> texts = new ArrayList<>(slots.size());
		for (Widget w : slots)
		{
			texts.add(w.getText() == null ? "" : w.getText());
		}
		List<JournalReconstructor.Unit> units = JournalReconstructor.reconstruct(texts);

		int size = glyph.uiSize();
		boolean aiFallback = cfgAiInterface;
		for (JournalReconstructor.Unit unit : units)
		{
			if (!unit.content)
			{
				translateHeader(unit, slots, size, aiFallback); // difficulty band / area subtitle headers
				continue;
			}
			Widget head = slots.get(unit.start);
			int slotChars = glyph.wrapChars(head.getWidth() - WRAP_PAD, size);
			if (slotChars < MIN_WRAP)
			{
				slotChars = MIN_WRAP;
			}
			// Always split the requirement "(...)" off first and translate it inline, so its live colours
			// (red = unmet, navy = met, strike-through on met parts) survive even when the sentence itself
			// hits a promoted whole-task table entry. The requirement state is per player, so it must be
			// read from the widget every render, never baked into a flat translation. The sentence part still
			// goes table-first inside translateJournalSentence, so promoted whole tasks stay instant.
			String raw = rawJoin(slots, unit.start, unit.count);
			int reqStart = findRequirementStart(raw);
			String sentenceRaw = reqStart >= 0 ? raw.substring(0, reqStart) : raw;
			String reqRaw = reqStart >= 0 ? raw.substring(reqStart) : "";
			String sentenceZh = translator.translateJournalSentence(
					JournalReconstructor.strip(sentenceRaw).trim(), aiFallback, journalTag, collect);
			if (sentenceZh == null)
			{
				continue; // prose not translatable yet (AI off/pending): leave the task in English
			}
			// Stored table / AI-cache values can carry <str> (a completed task was cached with its strike tag).
			// Strip it: a <str> line can't cross our glyph-images, it would only strike a stray ASCII digit.
			sentenceZh = sentenceZh.replaceAll("(?i)</?str>", "");
			// Paint the sentence in its own colour, taken from the leading inline "<col=...>" if present (the
			// red "Achievement Diary - <area>" title, the green "completed" difficulty band) and otherwise the
			// widget's colour. Without this the sentence always rendered black. The requirement keeps its own
			// per-segment colours from translateReqInline.
			// Completion handling. A finished task is struck through in English; our CJK glyph-images can't carry
			// a strike line, and the font pack has no check-mark glyph, so a done task is rendered in dim grey
			// instead. Detected live from the sentence's own <str> every render (a <str> inside the requirement
			// only means that requirement is met), so it updates automatically as you complete tasks.
			boolean done = sentenceRaw.contains("<str>");
			int sentenceColor = done ? 0x404040 : (headerColor(sentenceRaw, head.getTextColor()) & 0xFFFFFF);
			String sentenceColorTag = "<col=" + String.format("%06x", sentenceColor) + ">";
			String zh;
			if (reqRaw.isEmpty())
			{
				zh = sentenceColorTag + sentenceZh;
			}
			else
			{
				String reqZh = translateReqInline(reqRaw, aiFallback);
				if (reqZh == null)
				{
					continue; // a requirement name is AI-pending: leave English, retry next tick
				}
				zh = sentenceColorTag + sentenceZh + reqZh;
			}
			String img = glyph.toImgTags(zh, head.getTextColor(), slotChars, size);
			if (img == null)
			{
				continue; // some glyphs still uploading: retry next tick
			}
			String[] pieces = img.split("<br>", -1);
			if (pieces.length > unit.count)
			{
				// Chinese wrapped to more lines than the task had slots: skip rather than cram many <br>
				// lines into one widget (the client caps a widget at 100 lines and crashes past it).
				continue;
			}
			for (int k = 0; k < unit.count; k++)
			{
				Widget w = slots.get(unit.start + k);
				long key = widgetKey(w);
				// overwrite, not putIfAbsent: at translate time the slot still holds its true current
				// English, so this is always the right text to restore (even after a different diary reused
				// the widget).
				original.put(key, w.getText() == null ? "" : w.getText());
				String text;
				if (k < unit.count - 1)
				{
					text = k < pieces.length ? pieces[k] : "";
				}
				else
				{
					// last slot absorbs any leftover wrapped lines so no Chinese is dropped
					StringBuilder rem = new StringBuilder();
					for (int p = k; p < pieces.length; p++)
					{
						if (p > k)
						{
							rem.append("<br>");
						}
						rem.append(pieces[p]);
					}
					text = rem.toString();
				}
				w.setText(text);
				w.setTextShadowed(false);
				if (text.contains("<br>"))
				{
					w.setLineHeight(glyph.glyphHeight(size));
				}
				lastSet.put(key, text); // lets restore() put English back even on the blanked slots
			}
		}
	}

	/**
	 * Translate a journal's structural single-slot headers: the difficulty bands ("Easy"/"Medium"/"Hard"/
	 * "Elite", already in the data table) and the area subtitle ("Karamja Area Tasks"). Reconstruction
	 * skips these because they delimit tasks, so they would otherwise stay English. Looks the stripped
	 * label up the normal way and re-renders it in the header's own colour (parsed from the inline
	 * {@code <col=...>} if present, e.g. the yellow difficulty bands).
	 */
	private void translateHeader(JournalReconstructor.Unit unit, List<Widget> slots, int size, boolean aiFallback)
	{
		if (unit.count != 1)
		{
			return;
		}
		Widget w = slots.get(unit.start);
		String text = w.getText();
		if (text == null || text.isEmpty() || text.contains("<img="))
		{
			return; // empty separator line or already our translation
		}
		long key = widgetKey(w);
		if (text.equals(lastSet.get(key)))
		{
			return;
		}
		String plain = JournalReconstructor.strip(text).trim();
		if (plain.isEmpty())
		{
			return; // pure tag / whitespace line: nothing to translate
		}
		int slotChars = glyph.wrapChars(w.getWidth() - WRAP_PAD, size);
		if (slotChars < MIN_WRAP)
		{
			slotChars = 0; // short labels: don't force-wrap them
		}
		String r = translator.lookupRenderUi(plain, headerColor(text, w.getTextColor()), slotChars, size, aiFallback);
		if (r == null)
		{
			return; // unknown label (and AI off/pending): leave it in English
		}
		original.put(key, text);
		w.setText(r);
		w.setTextShadowed(false);
		if (r.contains("<br>"))
		{
			w.setLineHeight(glyph.glyphHeight(size));
		}
		lastSet.put(key, r);
	}

	/** Glyph colour for a header: the inline {@code <col=rrggbb>} if present, else the widget's own colour. */
	private static int headerColor(String text, int widgetColor)
	{
		int c = text.indexOf("<col=");
		if (c >= 0)
		{
			// Mixed-colour line (base text with highlighted words): the tag colour only covers the
			// highlights, so painting the whole translation with it looks wrong - keep the base colour.
			if (c > 0 && text.lastIndexOf("</col>") < text.length() - "</col>".length())
			{
				return widgetColor;
			}
			int end = text.indexOf('>', c);
			if (end > c + 5)
			{
				try
				{
					return Integer.parseInt(text.substring(c + 5, end).trim(), 16);
				}
				catch (NumberFormatException ignored)
				{
					// malformed colour tag: fall back to the widget's own colour
				}
			}
		}
		return widgetColor;
	}

	private void collectTextSlots(Widget w, List<Widget> out)
	{
		if (w == null)
		{
			return;
		}
		if (w.getText() != null)
		{
			out.add(w);
		}
		collectTextSlotsArray(w.getStaticChildren(), out);
		collectTextSlotsArray(w.getDynamicChildren(), out);
		collectTextSlotsArray(w.getNestedChildren(), out);
	}

	private void collectTextSlotsArray(Widget[] children, List<Widget> out)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			collectTextSlots(c, out);
		}
	}

	/** Join a unit's raw slot texts (tags kept) with spaces, mirroring the client's wrap. */
	private static String rawJoin(List<Widget> slots, int start, int count)
	{
		StringBuilder sb = new StringBuilder();
		for (int k = 0; k < count; k++)
		{
			String t = slots.get(start + k).getText();
			if (t == null)
			{
				t = "";
			}
			if (sb.length() > 0 && !t.isEmpty())
			{
				sb.append(' ');
			}
			sb.append(t);
		}
		return sb.toString();
	}

	/** First literal '(' that opens the requirement, ignoring '(' inside {@code <...>} tags; -1 if none. */
	static int findRequirementStart(String raw)
	{
		int i = 0;
		int n = raw.length();
		while (i < n)
		{
			char c = raw.charAt(i);
			if (c == '<')
			{
				int end = raw.indexOf('>', i);
				if (end != -1)
				{
					i = end + 1;
					continue;
				}
			}
			if (c == '(')
			{
				// Include a colour tag sitting immediately before the '(' (the client paints the opening paren
				// white via "<col=ffffff>(") so the paren keeps its colour instead of falling back to black.
				if (i >= 1 && raw.charAt(i - 1) == '>')
				{
					int open = raw.lastIndexOf('<', i - 1);
					if (open >= 0 && raw.startsWith("<col=", open))
					{
						return open;
					}
				}
				return i;
			}
			i++;
		}
		return -1;
	}

	/**
	 * Translate the names inside a diary requirement {@code (...)} while keeping every {@code <...>} tag in
	 * place, so the requirement's live colours (and any strike-through) survive. Each plain run between tags
	 * goes to {@link Translator#translateReqSegment} ("65 Slayer" -> "65级杀戮"); punctuation/spaces pass through.
	 */
	private String translateReqInline(String reqRaw, boolean aiFallback)
	{
		StringBuilder out = new StringBuilder(reqRaw.length() + 8);
		StringBuilder run = new StringBuilder();
		int i = 0;
		int n = reqRaw.length();
		while (i < n)
		{
			char c = reqRaw.charAt(i);
			if (c == '<')
			{
				int end = reqRaw.indexOf('>', i);
				if (end != -1)
				{
					if (run.length() > 0)
					{
						String seg = translator.translateReqSegment(run.toString(), aiFallback);
						if (Translator.REQ_PENDING.equals(seg))
						{
							return null; // a requirement name is still being translated: retry next tick
						}
						out.append(seg);
						run.setLength(0);
					}
					// Drop strike-through tags: the client strikes met requirements, but our CJK text renders as
					// glyph-images that a <str> line can't cross (only a stray ASCII digit gets struck, which looks
					// broken). The met/unmet colour (navy / dark red) already conveys state, so keep colour, drop <str>.
					String tag = reqRaw.substring(i, end + 1);
					if (!"<str>".equals(tag) && !"</str>".equals(tag))
					{
						out.append(tag);
					}
					i = end + 1;
					continue;
				}
			}
			run.append(c);
			i++;
		}
		if (run.length() > 0)
		{
			String seg = translator.translateReqSegment(run.toString(), aiFallback);
			if (Translator.REQ_PENDING.equals(seg))
			{
				return null;
			}
			out.append(seg);
		}
		return out.toString();
	}

	// ===== TEMP DEBUG P1-1 (remove after we know the achievement/quest journal widget structure) =====
	// Achievement-diary task scroll (Journalscroll, group 741) and quest journal (Questjournal, group
	// 119): dump every text widget's id/index/colour/bounds/text so we can see whether one task is a
	// single widget or wrapped across several QJ lines. Gated on the developer-only "开发者：日志转储"
	// ===== END TEMP DEBUG P1-1 =====

	/**
	 * Translate the chat channel tabs (Game/Public/.../Trade + On/Off) by component id.
	 *
	 * <p>OSRS stacks each tab name and its On/Off filter as two widgets sharing one ~56x22 button,
	 * separated by a single {@code <br>} line: each widget actually holds "token + blank line" (or
	 * "blank line + token") and the client vertically centres that 2-line block, which is how the name
	 * lands in the top half and the filter in the bottom half. Our CJK char-images are taller than a
	 * native line, so once both halves carry glyphs the two blocks overlap vertically. We drop the
	 * {@code <br>} trick and instead pin each widget with real vertical alignment: the name is
	 * top-aligned and the filter bottom-aligned (both horizontally centred), with the filter rendered a
	 * notch smaller than the name. The name uses the empty space at the top while the small green filter
	 * tucks against the bottom, keeping the native top/bottom stacking without the two glyph lines
	 * touching. The "All" tab has no filter, so its name is centred instead of pinned to the top.
	 */
	/**
	 * Chatbox prompt panel: GE item search, bank search, "enter a name". The whole chatbox group is
	 * excluded from the generic walk, so these had no owner and stayed English. Reach them directly from
	 * MES_LAYER rather than relying on the walk to descend into an excluded group, the same way the chat
	 * tab labels are handled. Skipped on purpose: the two widgets holding what the player is typing, and
	 * the result list, which core RuneLite rewrites with {@code </u>} highlights that would cut an img tag
	 * in half.
	 */
	/**
	 * The prompt line holds the question and, once the player starts typing, their own text too. Table
	 * lookups only ever match the untouched question, so a typed line simply misses and is left alone -
	 * but only as long as the AI never sees it, and it is never written to the missing file.
	 */
	private static final SurfaceRegistry.Surface PROMPT_SURFACE = SurfaceRegistry.promptSurface();

	/**
	 * Result rows carry core RuneLite's fuzzy-search underline markup, inserted at a character offset
	 * into whatever the widget currently holds. Once a name is char-images that offset can land inside
	 * an img tag, so drop the markup before we take the widget over: the highlight is lost, a cut tag
	 * would be visible garbage.
	 */
	private static final Pattern SEARCH_UNDERLINE = Pattern.compile("</?u(?:=[^>]*)?>");

	private void translateChatPrompts(boolean perFrame)
	{
		Widget layer = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
		if (cfgDebug && !perFrame)
		{
			dumpPrompts(layer);
		}
		promptPerFrame = perFrame;
		if (layer == null || layer.isHidden())
		{
			return;
		}
		// Static children only. RuneLite builds its own chatbox panels (bank tag search, wiki search,
		// anything using ChatboxPanelManager) as DYNAMIC children of this same layer, and dynamic children
		// inherit the parent's id, so they cannot be told apart by id. Those hold what the player is
		// typing: a table lookup would hit the 21k-entry name table and turn "logs" into Chinese as they
		// type. The vanilla prompt, hints and results we do want are all static components of group 162.
		promptWalkArray(layer.getStaticChildren());
		promptWalkArray(layer.getNestedChildren());
	}

	/** debugMonitor only: log the prompt subtree once per distinct layout, to identify components by eye. */
	private void dumpPrompts(Widget layer)
	{
		if (layer == null || layer.isHidden())
		{
			promptDump = null;
			return;
		}
		StringBuilder sb = new StringBuilder();
		collectPrompts(layer, sb, "root");
		String s = sb.toString();
		if (!s.equals(promptDump))
		{
			promptDump = s;
			log.info("OSRSCN-prompt\n{}", s);
		}
	}

	private void collectPrompts(Widget w, StringBuilder sb, String kind)
	{
		if (w == null || w.isHidden())
		{
			return;
		}
		String t = w.getText();
		if (t != null && !t.isEmpty())
		{
			sb.append(String.format("  %s id=%d (grp=%d child=%d) item=%d text=%s%n",
					kind, w.getId(), w.getId() >>> 16, w.getId() & 0xffff,
					w.getItemId(), t));
		}
		collectPromptsArray(w.getStaticChildren(), sb, "static");
		collectPromptsArray(w.getDynamicChildren(), sb, "dynamic");
		collectPromptsArray(w.getNestedChildren(), sb, "nested");
	}

	private void collectPromptsArray(Widget[] children, StringBuilder sb, String kind)
	{
		if (children != null)
		{
			for (Widget c : children)
			{
				collectPrompts(c, sb, kind);
			}
		}
	}

	private void promptWalk(Widget w)
	{
		if (w == null || w.isHidden())
		{
			return;
		}
		int id = w.getId();
		if (id == InterfaceID.Chatbox.INPUT || id == InterfaceID.Chatbox.MES_LAYER)
		{
			// INPUT is the player's own typing. A widget still carrying the layer's id is one of
			// RuneLite's dynamically built panels (see translateChatPrompts) and is equally off limits.
			return;
		}
		boolean results = id == InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS;
		if (results && promptPerFrame)
		{
			// Results only change when the player types, so a screen of them does not need redrawing
			// every frame; the tick pass picks them up 20ms later, which nobody can see.
			return;
		}
		String text = w.getText();
		if (results && !cfgSearchResults && text != null && isItemName(text))
		{
			// Switch off: candidate names stay English, but the prompt and hints stay Chinese, which is
			// what the setting promises. Names carry no terminal punctuation, hints and labels always do.
			return;
		}
		if (id == InterfaceID.Chatbox.MES_TEXT2 && text != null && translateTypedPrompt(w, text))
		{
			return;
		}
		if (results && text != null && text.indexOf('<') >= 0 && !text.contains("<img="))
		{
			// Drop core RuneLite's fuzzy-search highlight before taking the widget over: it is inserted
			// at a character offset, and once the name is char-images that offset can land inside an img
			// tag. Losing the underline is cosmetic, a cut tag is visible garbage.
			String bare = SEARCH_UNDERLINE.matcher(text).replaceAll("");
			if (!bare.equals(text))
			{
				w.setText(bare);
				text = bare;
			}
		}
		translateWidget(w, false, PROMPT_SURFACE);
		promptWalkArray(w.getStaticChildren());
		promptWalkArray(w.getDynamicChildren());
		promptWalkArray(w.getNestedChildren());
	}

	/** A candidate item name, as opposed to a prompt or hint: those always end in a full stop or colon. */
	private static boolean isItemName(String text)
	{
		String t = text.trim();
		return !t.isEmpty() && !t.endsWith(".") && !t.endsWith(":") && !t.endsWith("：");
	}

	private void promptWalkArray(Widget[] children)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			promptWalk(c);
		}
	}

	private boolean translateTypedPrompt(Widget w, String text)
	{
		if (text.contains("<img="))
		{
			return true; // already translated for this keystroke; the game rewrites it on the next one
		}
		int end = text.lastIndexOf("</col>");
		if (end < 0)
		{
			return false;
		}
		String tail = text.substring(end + 6);
		if (tail.equals(" *"))
		{
			return false;
		}
		String zh = translator.lookupRenderUi(text.substring(0, end + 6) + " *",
				w.getTextColor(), 0, glyph.uiSize(), false);
		if (zh == null || !zh.endsWith(" *"))
		{
			return false;
		}
		w.setText(zh.substring(0, zh.length() - 2) + tail);
		w.setTextShadowed(false);
		return true;
	}

	private void translateChatTabs()
	{
		for (int id : CHAT_TAB_WIDGETS)
		{
			Widget w = client.getWidget(id);
			if (w == null || w.isHidden())
			{
				continue;
			}
			String text = w.getText();
			if (text == null || text.contains("<img="))
			{
				continue; // empty or already our translation
			}
			// the name comes as "Public<br> " and the filter as "<br>On"; strip the <br> so each widget
			// renders a single line that we then pin vertically.
			String clean = text.replace("<br>", " ").trim();
			if (clean.isEmpty())
			{
				continue;
			}
			boolean isFilter = CHAT_TAB_FILTERS.contains(id);
			boolean nameOnly = id == InterfaceID.Chatbox.CHAT_ALL_TEXT1; // "All" tab has no filter line
			int size = isFilter ? CHAT_TAB_FILTER_SIZE : CHAT_TAB_NAME_SIZE;
			String r = translator.lookupRenderUi(clean, w.getTextColor(), 0, size, cfgAiInterface);
			if (r == null)
			{
				continue;
			}
			int yAlign;
			if (isFilter)
			{
				yAlign = WidgetTextAlignment.BOTTOM;
			}
			else if (nameOnly)
			{
				yAlign = WidgetTextAlignment.CENTER;
			}
			else
			{
				yAlign = WidgetTextAlignment.TOP;
			}
			tabOriginal.put(id, text);
			tabAlignX.putIfAbsent(id, w.getXTextAlignment());
			tabAlignY.putIfAbsent(id, w.getYTextAlignment());
			w.setText(r);
			w.setXTextAlignment(WidgetTextAlignment.CENTER);
			w.setYTextAlignment(yAlign);
			w.setTextShadowed(false);
		}
	}

	/** Put the English chat tab labels back (English toggle). */
	private void restoreChatTabs()
	{
		for (int id : CHAT_TAB_WIDGETS)
		{
			Widget w = client.getWidget(id);
			String orig = tabOriginal.get(id);
			if (w != null && orig != null && w.getText() != null && w.getText().contains("<img="))
			{
				w.setText(orig);
				Integer ax = tabAlignX.get(id);
				Integer ay = tabAlignY.get(id);
				if (ax != null)
				{
					w.setXTextAlignment(ax);
				}
				if (ay != null)
				{
					w.setYTextAlignment(ay);
				}
			}
		}
		tabOriginal.clear();
		tabAlignX.clear();
		tabAlignY.clear();
	}

	/**
	 * Re-translate only the groups the client rewrites every frame. Call from a per-frame hook
	 * (before render). Walk only known small roots so it costs almost nothing the rest of the time.
	 */
	public void translateRedraw()
	{
		beginPass();
		// Per-frame freshness pass: walk every visible interface root and re-translate, so any text the
		// client rewrote to English this frame (panel switch/redraw, per-frame tooltip rewrite, etc.) is
		// translated before it is drawn. This is what kills the "flash" generally instead of per-panel.
		// walk() prunes hidden subtrees and translateWidget short-circuits already-translated widgets
		// (lastSet), so the pass is cheap. Hit-test-sensitive panels (EXCLUDE_FROM_PERFRAME) are skipped
		// here and kept fresh by the per-tick backstop + their script hook.
		scan(true);
		translateChatTabs();
		translateChatPrompts(true);
	}

	private Widget[] widgetRootsWhenAvailable()
	{
		// Root enumeration dereferences widget definitions before checking whether they exist.
		// The sprite-cache accessor is null-safe for that same container during client startup.
		return client.getWidgetSpriteCache() == null ? null : client.getWidgetRoots();
	}

	private void scan(boolean perFrame)
	{
		Widget[] roots = widgetRootsWhenAvailable();
		if (roots == null)
		{
			return;
		}
		for (Widget root : roots)
		{
			walk(root, perFrame);
		}
	}

	/**
	 * Translate a single interface group's subtree right now. Called from a script hook the moment a
	 * client script rebuilds that group's text (e.g. opening/switching to the Character Summary panel),
	 * so the freshly written English is translated before the frame draws instead of flashing until the
	 * next per-tick scan. One-shot per call - not a per-frame path - so it never fights the panel's own
	 * hover/tooltip widgets (unlike adding the group to REDRAW_GROUPS, which broke its mouseover).
	 */
	public void translateGroup(int rootComponentId)
	{
		beginPass();
		Widget root = client.getWidget(rootComponentId);
		if (root == null || root.isHidden())
		{
			return;
		}
		walk(root, false);
	}

	/**
	 * Like {@link #translateGroup} but for a whole interface group given only its group id: translate every
	 * loaded root that belongs to {@code groupId}. Use when the group has no single named root component
	 * (e.g. the old skill guide): we walk whatever root the client registered for it, exactly as the
	 * per-tick scan reaches it, instead of guessing which component index is the container.
	 */
	/**
	 * Translate one component (and its subtree) directly via {@code client.getWidget(componentId)}. Needed
	 * for components a group-root walk can't reach: e.g. the skill guide's TITLE / CATEGORIES are group 214
	 * but live outside the root that {@link #translateGroupId} walks, so they must be addressed directly.
	 */
	public void translateComponent(int componentId)
	{
		beginPass();
		Widget w = client.getWidget(componentId);
		if (w == null || w.isHidden())
		{
			return;
		}
		walk(w, false);
	}

	// True while the game-tick slow lane is walking its groups; client-thread only, so a plain field.
	private boolean slowLane;

	/**
	 * Translate the {@link SurfaceRegistry.Surface#slowScan} groups. Called once per game tick (600ms)
	 * instead of the 50x/s client-tick scan: these are big miss-heavy lists whose recursion and lookup
	 * cost at client-tick rate tanks the frame rate. A full-tree walk (not translateGroupId) because
	 * side panels live nested inside the top-level root, not as their own widget root; non-slowScan
	 * widgets are skipped in translateWidget, so the fast lanes' work is not duplicated.
	 */
	public void translateSlowGroups()
	{
		beginPass();
		slowLane = true;
		try
		{
			scan(false);
		}
		finally
		{
			slowLane = false;
		}
	}

	public void translateGroupId(int groupId)
	{
		beginPass();
		Widget[] roots = widgetRootsWhenAvailable();
		if (roots == null)
		{
			return;
		}
		for (Widget root : roots)
		{
			if (root != null && (root.getId() >>> 16) == groupId)
			{
				walk(root, false);
			}
		}
	}

	/**
	 * Re-translate whatever surface(s) the just-fired client script rebuilds, per the registry. Called from
	 * onScriptPostFired so a panel's freshly-written English is translated before the frame draws, instead of
	 * flashing until the next per-tick scan. No-op for scripts no surface registers.
	 */
	public void translateForScript(int scriptId)
	{
		java.util.List<SurfaceRegistry.Target> targets = registry.forScript(scriptId);
		if (targets == null)
		{
			return;
		}
		for (SurfaceRegistry.Target t : targets)
		{
			switch (t.reach)
			{
				case GROUP_ROOT:
					translateGroup(t.id);
					break;
				case GROUP_ID:
					translateGroupId(t.id);
					break;
				case COMPONENT:
					translateComponent(t.id);
					break;
			}
		}
	}

	private void walk(Widget w, boolean perFrame)
	{
		// Prune entire hidden subtrees instead of recursing into them (translateWidget would skip each
		// hidden widget anyway, but recursing into a closed panel's deep tree is wasted work - RuneLite's
		// own UI lags on deep hidden trees without this). This makes the scan cheap enough to raise to
		// per-frame later, and lowers the current per-tick cost now. Visible widgets are unaffected.
		if (w == null || w.isHidden())
		{
			return;
		}
		// Grouping mixes static activity labels with a player-controlled member list. Dynamic
		// rows inherit this component id; skip the whole list before lookup, AI or collection.
		if (w.getId() == InterfaceID.Grouping.PLAYERLIST)
		{
			return;
		}
		// One registry lookup per widget, handed down to translateWidget (it used to repeat both this and
		// the isHidden() check above on every widget of every pass).
		SurfaceRegistry.Surface s = registry.forGroup(w.getId() >>> 16);
		// Prune slow-scan subtrees from the fast lanes entirely: merely skipping them in
		// translateWidget still recurses hundreds of rows and clones their child arrays 50x/s,
		// which is what actually tanked FPS with the world switcher open.
		if (!slowLane && s.slowScan)
		{
			return;
		}
		if (cfgDebug)
		{
			statVisited++;
		}
		translateWidget(w, perFrame, s);
		walkArray(w.getStaticChildren(), perFrame);
		walkArray(w.getDynamicChildren(), perFrame);
		walkArray(w.getNestedChildren(), perFrame);
	}

	private void walkArray(Widget[] children, boolean perFrame)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			walk(c, perFrame);
		}
	}

	private void translateWidget(Widget w, boolean perFrame, SurfaceRegistry.Surface s)
	{
		// Policy comes from the widget's own group (info boxes can be nested under another group's root),
		// resolved once by walk() and passed in: excluded/chatbox never translate; the per-frame pass
		// additionally skips hit-test-sensitive panels (kept on the tick backstop + their script hook, to
		// not break mouseover); reconstruct groups are owned by reconstructJournals.
		if (s.excluded || (perFrame && s.perFrameExcluded) || (s.slowScan != slowLane))
		{
			// slowScan != slowLane: fast lanes skip slow groups; the slow lane only translates them
			// (it re-walks the whole tree to reach nested side panels, so skip everything else).
			return;
		}
		if (s.reconstruct && cfgReconstruct)
		{
			return; // whole-task reconstruction owns these groups (see reconstructJournals)
		}
		int size = s.small ? glyph.smallSize() : glyph.uiSize();
		boolean aiFallback = cfgAiInterface && !s.noAi;
		long key = widgetKey(w);
		String text = w.getText();
		if (text == null || text.isEmpty())
		{
			return;
		}
		// true when we came in through our own char-images (partial AI box / recolour): those retries must
		// never consult or feed the negative memo, or a hover recolour would stall until revalidation
		boolean retranslate = false;
		if (text.contains("<img="))
		{
			// already shows our translation. Revisit if it was partial (AI pending), or if the widget's
			// colour changed since we baked the glyphs - char-images don't follow a native recolour, so
			// hover highlights (e.g. the music list) need a re-render in the new colour.
			Integer baked = lastColor.get(key);
			boolean recolour = baked != null && baked != w.getTextColor();
			if (!incomplete.contains(key) && !recolour)
			{
				return;
			}
			String eng = original.get(key);
			if (eng == null)
			{
				incomplete.remove(key);
				return;
			}
			text = eng; // re-translate from the stored English, not the partial char-images
			retranslate = true;
		}
		else if (text.equals(lastSet.get(key)))
		{
			return;
		}
		else if (text.equals(lastMiss.get(key)))
		{
			// exactly the text that missed every table last time: skip the whole pipeline until something
			// could have changed (revalidateMisses). Any edit to the widget's text fails this test.
			if (cfgDebug)
			{
				statMissSkip++;
			}
			return;
		}

		int maxChars = glyph.wrapChars(w.getWidth() - WRAP_PAD, size);
		// narrow widgets (buttons like emote/chat tabs) shouldn't auto-wrap short labels into a mess
		if (maxChars < MIN_WRAP)
		{
			maxChars = 0;
		}

		// Look the whole widget up as one templated string (numbers -> <Num0>...), so multi-line info
		// boxes (prayer/spell/XP) and any numbered label match a single table entry. Info boxes also
		// fall back to AI for description lines the table doesn't have (e.g. "Requires Mage Arena I").
		// Reconstruct groups reaching this point mean the reflow toggle is OFF: their per-widget lines
		// are wrapped sentence halves, so translate them but never collect (same for noCollect panels).
		Translator.Rendered r = (s.reconstruct || s.noCollect)
				? translator.renderUiNoCollect(text, w.getTextColor(), maxChars, size, aiFallback)
				: translator.renderUi(text, w.getTextColor(), maxChars, size, aiFallback);
		if (r == null)
		{
			if (!retranslate)
			{
				lastMiss.put(key, text);
			}
			if (cfgDebug)
			{
				statMissRun++;
			}
			return;
		}
		lastMiss.remove(key);
		original.put(key, text); // remember the English we are replacing, for instant restore
		w.setText(r.text);
		// native text shadow draws the glyph twice at a 1px offset, which on char-images looks
		// like doubled/overlapping characters (e.g. the chat tab buttons) - turn it off.
		w.setTextShadowed(false);
		if (r.text.contains("<br>"))
		{
			w.setLineHeight(glyph.glyphHeight(size));
		}
		lastSet.put(key, r.text);
		lastColor.put(key, w.getTextColor());
		// keep retrying partial boxes (AI lines pending) until every translatable line is done
		if (r.complete)
		{
			incomplete.remove(key);
		}
		else
		{
			incomplete.add(key);
		}
	}

	/** Put the original English back on every interface widget we translated (instant EN switch). */
	public void restore()
	{
		Widget[] roots = widgetRootsWhenAvailable();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				restoreWalk(root);
			}
		}
		restoreChatTabs();
		restoreProseScroll();
		lastSet.clear();
		lastMiss.clear();
		lastColor.clear();
		original.clear();
		incomplete.clear();
		movedX.clear();
		movedY.clear();
		movedW.clear();
		placedX.clear();
		placedY.clear();
		// the 860 signatures must die with the state: a surviving committedSig would match the very first
		// re-derived frame after an EN->CN toggle and SKIP forever, sticking the guide in English
		committedSig = null;
		failedSig = null;
		lastProseSig = "";
		settleTicks = 0;
		pendingCollect.clear();
	}

	private void restoreWalk(Widget w)
	{
		if (w == null)
		{
			return;
		}
		long key = widgetKey(w);
		String orig = original.get(key);
		// restore if the widget still holds our translation: either the exact string we last wrote, or
		// any char-image text (it may have been re-translated/AI-upgraded to a string != lastSet, which
		// would otherwise get stuck in Chinese on the next English toggle).
		String cur = w.getText();
		if (orig != null && cur != null && (cur.equals(lastSet.get(key)) || cur.contains("<img=")))
		{
			w.setText(orig);
			if ((key >>> 21) == (PROSE_COMPONENT_ID & 0xFFFFFFFFL))
			{
				w.setTextShadowed(true); // 860 prose is natively shadowed; we disabled it for glyphs
			}
		}
		revertGeom(key, w); // 860 prose widgets we compacted: put back at their native x/y
		restoreArray(w.getStaticChildren());
		restoreArray(w.getDynamicChildren());
		restoreArray(w.getNestedChildren());
	}

	private void restoreArray(Widget[] children)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			restoreWalk(c);
		}
	}

	/** Forget what we translated so everything re-translates (e.g. after a font-size change). Client thread. */
	public void reset()
	{
		// put the 860 prose back to English FIRST: clearing the maps below would orphan its stored English
		// (the column would keep old-size char-images with no way back until the client rebuilds it)
		revertSkillGuide();
		lastSet.clear();
		lastMiss.clear();
		lastColor.clear();
		original.clear();
		incomplete.clear();
		tabOriginal.clear();
		journalSig.clear();
		journalStable.clear();
		movedX.clear();
		movedY.clear();
		movedW.clear();
		placedX.clear();
		placedY.clear();
	}
}

package com.osrscn.hooks;

import java.util.ArrayList;
import java.util.List;

/**
 * Reconstructs full logical "tasks/paragraphs" from the per-line widget fragments of the
 * achievement diary (Journalscroll, group 741) and quest journal (Questjournal, group 119).
 *
 * <p>The OSRS client wraps prose to fixed-width line slots, so one logical task is split across
 * several consecutive widgets at hard wrap points computed from the <em>English</em> text width.
 * Translating each fragment on its own gives meaningless half-sentences (and the Chinese would wrap
 * at the wrong place). This class joins the fragments back into one string per task so the caller can
 * translate the whole task, then re-flow the translation into the same slots.
 *
 * <p>Pure string logic, no RuneLite dependency, so it is unit-testable against captured widget dumps
 * (see {@code JournalReconstructorTest}). The caller supplies the raw widget texts in render order
 * (top to bottom); this returns {@link Unit}s that cover every input line exactly once.
 */
public final class JournalReconstructor
{
	/**
	 * One span of consecutive line slots. A <em>content</em> unit ({@link #content} == true) is a real
	 * task/sentence whose {@link #english} is the reconstructed plain text to translate. A structural
	 * unit (blank line, section header, title) has {@code content == false} and {@code english == null};
	 * the caller leaves those slots untouched.
	 */
	public static final class Unit
	{
		public final int start;      // index of the first source line this unit covers
		public final int count;      // number of consecutive lines covered (>= 1)
		public final String english; // reconstructed plain text (content units), else null
		public final boolean content;

		Unit(int start, int count, String english, boolean content)
		{
			this.start = start;
			this.count = count;
			this.english = english;
			this.content = content;
		}
	}

	private JournalReconstructor()
	{
	}

	/**
	 * Group {@code lines} (raw widget texts, top-to-bottom) into units. Every input index is covered by
	 * exactly one returned unit, in order, so the caller can map units back to widgets 1:1.
	 */
	public static List<Unit> reconstruct(List<String> lines)
	{
		List<Unit> units = new ArrayList<>();
		int i = 0;
		int n = lines.size();
		while (i < n)
		{
			if (!isContent(lines.get(i)))
			{
				units.add(new Unit(i, 1, null, false)); // blank / header / title: pass through
				i++;
				continue;
			}
			// Accumulate fragments until the task is complete: keep going while the running text is not
			// yet a finished sentence/requirement AND the next line is itself content (not a header/blank).
			int j = i;
			StringBuilder sb = new StringBuilder(strip(lines.get(i)));
			while (j + 1 < n && isContent(lines.get(j + 1)))
			{
				String next = strip(lines.get(j + 1));
				if (isComplete(sb.toString(), next))
				{
					break;
				}
				j++;
				if (sb.length() > 0 && !next.isEmpty())
				{
					sb.append(' ');
				}
				sb.append(next);
			}
			units.add(new Unit(i, j - i + 1, collapse(sb.toString()), true));
			i = j + 1;
		}
		return units;
	}

	/**
	 * Is the accumulated task text finished, given the text that would come next?
	 *
	 * <p>Not finished while a {@code (requirement)} is still open (unbalanced parens), or when the next
	 * line begins a {@code (requirement)} that belongs to this task (wrapped onto its own line). Finished
	 * once parens are balanced and the text ends in a sentence terminator or a closing paren.
	 */
	static boolean isComplete(String accumulated, String next)
	{
		String text = accumulated.trim();
		if (text.isEmpty())
		{
			return false;
		}
		if (parenDepth(text) > 0)
		{
			return false; // a requirement list is still open and wraps onto the next line(s)
		}
		if (next != null && next.trim().startsWith("("))
		{
			return false; // the requirement is wrapped onto the next line; pull it in
		}
		char last = text.charAt(text.length() - 1);
		return last == '.' || last == '!' || last == '?' || last == ')';
	}

	/** A line carries real task text if, after stripping tags, it has any letter or digit. */
	static boolean isContent(String rawLine)
	{
		if (rawLine == null)
		{
			return false;
		}
		// Already our translation: rendered Chinese always carries <img=N> glyph tags, while raw English
		// diary text never does. Treat translated lines as structural so a finished task is not re-grouped
		// and re-translated (its rendered text keeps literal ASCII like "70"/"(" which would otherwise look
		// like fresh content and feed an amplifying loop -> a widget with 100+ <br> lines -> client crash).
		if (rawLine.contains("<img="))
		{
			return false;
		}
		// Yellow lines are difficulty section headers ("Easy"/"Medium"/"Hard"/"Elite") and the area
		// subtitle - never task text. Treat them as structural so they delimit tasks instead of merging.
		if (rawLine.contains("<col=ffff00"))
		{
			return false;
		}
		String s = strip(rawLine);
		for (int k = 0; k < s.length(); k++)
		{
			if (Character.isLetterOrDigit(s.charAt(k)))
			{
				return true;
			}
		}
		return false;
	}

	/** Net unclosed '(' count (never negative), ignoring any inside angle-bracket tags. */
	private static int parenDepth(String s)
	{
		int depth = 0;
		for (int k = 0; k < s.length(); k++)
		{
			char c = s.charAt(k);
			if (c == '(')
			{
				depth++;
			}
			else if (c == ')' && depth > 0)
			{
				depth--;
			}
		}
		return depth;
	}

	/** Remove all {@code <...>} tags (col/str/img/br/...) leaving plain text. */
	static String strip(String s)
	{
		if (s == null || s.isEmpty())
		{
			return "";
		}
		StringBuilder out = new StringBuilder(s.length());
		int i = 0;
		int n = s.length();
		while (i < n)
		{
			char c = s.charAt(i);
			if (c == '<')
			{
				int end = s.indexOf('>', i);
				if (end != -1)
				{
					i = end + 1;
					continue;
				}
			}
			out.append(c);
			i++;
		}
		return out.toString();
	}

	/** Collapse runs of whitespace to single spaces and trim (joined fragments can double-space). */
	static String collapse(String s)
	{
		StringBuilder out = new StringBuilder(s.length());
		boolean prevSpace = false;
		for (int k = 0; k < s.length(); k++)
		{
			char c = s.charAt(k);
			boolean ws = c == ' ' || c == '\t' || c == ' ';
			if (ws)
			{
				if (!prevSpace && out.length() > 0)
				{
					out.append(' ');
				}
				prevSpace = true;
			}
			else
			{
				out.append(c);
				prevSpace = false;
			}
		}
		int len = out.length();
		while (len > 0 && out.charAt(len - 1) == ' ')
		{
			out.setLength(--len);
		}
		return out.toString();
	}
}

package com.osrscn.hooks;

import com.osrscn.glyph.GlyphService;
import com.osrscn.text.Tags;
import com.osrscn.translate.TranslationStore.Category;
import com.osrscn.translate.Translator;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.MenuOpened;

/**
 * Translates right-click menu entries and supplies translated text for the hover tooltip.
 *
 * <p>A menu entry has an option (the action verb, e.g. "Attack") and a target (the entity, e.g.
 * "{@code <col=ffff00>Goblin</col> (level-2)}"). The verb is looked up in the actions table, the
 * entity name in the name table, and a trailing "(level-N)" is localised; each part is rendered to
 * char-image tags. Lookup only - no AI - so menus never flicker or lag.
 */
@Singleton
public class MenuTranslator
{
	// White is OSRS's default for both a menu option (the verb) and a target with no colour tag; kept as
	// two named constants because they describe different fields, even though the value is the same.
	private static final int OPTION_COLOR = 0xffffff;
	private static final int DEFAULT_TARGET_COLOR = 0xffffff;
	// Current native menu renderer (Client build 32956056058.238): one 15px row, with strict
	// (baseline-13, baseline+3) mouse bounds and a baseline offset of 31px from menuY.
	private static final int NATIVE_HOVER_COLOR = 0xffff00;
	private static final int NATIVE_ROW_HEIGHT = 15;
	private static final int NATIVE_BASELINE_OFFSET = 31;
	private static final int NATIVE_HIT_TOP = 13;
	private static final int NATIVE_HIT_BOTTOM = 3;

	private static final Pattern LEVEL = Pattern.compile("\\((?:level|combat)-(\\d+)\\)", Pattern.CASE_INSENSITIVE);

	// "Use" on an inventory item selects it to apply to something else, and the confirm step reads
	// "Use <item> -> <target>" as a sentence; the generic table word (使用) only suits a direct "Use"
	// on an object/NPC. The distinction is the entry's MenuAction - runtime state the TSV schema can't
	// express - so the two scene words live here instead of in the actions table.
	private static final String USE_SELECT_ZH = "选用";
	private static final String USE_APPLY_ZH = "用";

	@Inject
	private Client client;
	@Inject
	private Translator translator;
	@Inject
	private GlyphService glyph;

	// Entry objects are pooled by the client. Identity locates a snapshot; the action and exact last
	// written strings must still match before that snapshot can repaint or restore anything.
	private final Map<MenuEntry, EntryState> entryStates = new IdentityHashMap<>();

	private static final class EntryState
	{
		final String option;
		final String target;
		final MenuAction type;
		final int identifier;
		final int param0;
		final int param1;
		final int itemId;
		final int worldViewId;
		final Consumer<MenuEntry> onClick;
		String liveOption;
		String liveTarget;
		int optionColor = -1;
		int targetColor = -1;
		boolean optionRendered;
		boolean targetRendered;

		EntryState(MenuEntry entry)
		{
			option = entry.getOption();
			target = entry.getTarget();
			type = entry.getType();
			identifier = entry.getIdentifier();
			param0 = entry.getParam0();
			param1 = entry.getParam1();
			itemId = entry.getItemId();
			worldViewId = entry.getWorldViewId();
			onClick = entry.onClick();
			liveOption = option;
			liveTarget = target;
		}

		boolean owns(MenuEntry entry)
		{
			return entry.getType() == type && entry.getIdentifier() == identifier
					&& entry.getParam0() == param0 && entry.getParam1() == param1
					&& entry.getItemId() == itemId && entry.getWorldViewId() == worldViewId
					&& entry.onClick() == onClick && Objects.equals(entry.getOption(), liveOption)
					&& Objects.equals(entry.getTarget(), liveTarget);
		}
	}

	/** Translate every entry (and sub-entries) of a freshly opened right-click menu, in place. */
	public void handleMenuOpened(MenuOpened event)
	{
		entryStates.clear();
		if (client.getMenu() != null)
		{
			refreshNativeColors();
		}
		else
		{
			translateEntries(event.getMenuEntries(), OPTION_COLOR);
		}
	}

	/**
	 * Re-translate the menu that is currently open. A brand-new glyph's sprite is only uploaded on the
	 * client cycle after it is first registered, so {@link Translator#lookupRender} returns null on the
	 * first right-click and that option/target is left in English. The menu is a one-shot ({@code
	 * onMenuOpened}) with no retry, so it would stay English until the menu is reopened (the "need a
	 * second right-click" bug). Calling this every client tick while the menu stays open lets such
	 * entries pick up their now-ready glyphs a cycle later, exactly like the per-tick interface scan
	 * does. Already-translated entries are no-ops: their char-image text strips to empty, so the lookups
	 * return null and leave them unchanged; untranslatable entries (other plugins, table misses) stay
	 * English as before.
	 */
	public void retranslateOpenMenu()
	{
		if (!client.isMenuOpen())
		{
			return;
		}
		refreshNativeColors();
	}

	private void refreshNativeColors()
	{
		Menu root = client.getMenu();
		if (root == null)
		{
			translateEntries(client.getMenuEntries(), OPTION_COLOR);
			return;
		}
		Point mouse = client.getMouseCanvasPosition();
		MenuEntry hovered = hoveredEntry(root, client.getMenuScroll(), mouse);
		applyMenu(root, hovered);
	}

	private void applyMenu(Menu menu, MenuEntry hovered)
	{
		for (MenuEntry entry : menu.getMenuEntries())
		{
			translateInPlace(entry, entry == hovered ? NATIVE_HOVER_COLOR : OPTION_COLOR);
			Menu sub = entry.getSubMenu();
			if (sub != null)
			{
				applyMenu(sub, hovered);
			}
		}
	}

	private MenuEntry hoveredEntry(Menu menu, int scroll, Point mouse)
	{
		if (mouse == null)
		{
			return null;
		}
		MenuEntry[] entries = menu.getMenuEntries();
		// The native renderer draws an active submenu over its parent. Prefer the deepest menu whose
		// real bounds contain the mouse so root and submenu rows never share hover state.
		for (MenuEntry entry : entries)
		{
			Menu sub = entry.getSubMenu();
			if (sub != null)
			{
				MenuEntry hit = hoveredEntry(sub, 0, mouse);
				if (hit != null)
				{
					return hit;
				}
			}
		}
		int index = nativeEntryAt(menu.getMenuX(), menu.getMenuY(), menu.getMenuWidth(), entries.length,
				scroll, mouse.getX(), mouse.getY());
		return index >= 0 ? entries[index] : null;
	}

	static int nativeEntryAt(int menuX, int menuY, int menuWidth, int entryCount, int scroll,
			int mouseX, int mouseY)
	{
		for (int index = 0; index < entryCount; index++)
		{
			if (entryCount - 1 - index < scroll)
			{
				continue;
			}
			int baseline = menuY + (entryCount - 1 - index - scroll) * NATIVE_ROW_HEIGHT
					+ NATIVE_BASELINE_OFFSET;
			if (mouseX > menuX && mouseX < menuX + menuWidth
					&& mouseY > baseline - NATIVE_HIT_TOP && mouseY < baseline + NATIVE_HIT_BOTTOM)
			{
				return index;
			}
		}
		return -1;
	}

	private void translateEntries(MenuEntry[] entries, int color)
	{
		for (MenuEntry entry : entries)
		{
			translateInPlace(entry, color);
			Menu sub = entry.getSubMenu();
			if (sub != null)
			{
				translateEntries(sub.getMenuEntries(), color);
			}
		}
	}

	private void translateInPlace(MenuEntry entry, int rowColor)
	{
		if (entry.getType().name().startsWith("RUNELITE"))
		{
			entryStates.remove(entry);
			return; // keep custom plugin actions matchable by their English text
		}
		EntryState state = entryStates.get(entry);
		if (state != null && !state.owns(entry))
		{
			entryStates.remove(entry);
			state = null;
		}
		if (state == null)
		{
			String option = entry.getOption();
			String target = entry.getTarget();
			if (option == null || target == null || option.contains("<img=") || target.contains("<img="))
			{
				return;
			}
			state = new EntryState(entry);
			entryStates.put(entry, state);
		}

		if (!state.optionRendered || state.optionColor != rowColor)
		{
			String opt = translateOption(state.option, state.type, glyph.uiSize(), rowColor);
			if (opt != null)
			{
				entry.setOption(opt);
				state.liveOption = opt;
				state.optionRendered = true;
				state.optionColor = rowColor;
			}
		}
		int targetColor = Tags.firstColor(state.target, rowColor);
		if (!state.targetRendered || state.targetColor != targetColor)
		{
			String tgt = translateTarget(state.target, glyph.uiSize(), rowColor);
			if (tgt != null)
			{
				entry.setTarget(tgt);
				state.liveTarget = tgt;
				state.targetRendered = true;
				state.targetColor = targetColor;
			}
		}
	}

	/**
	 * Put the English option/target back on a clicked entry, so plugins that match on English text (and
	 * the game's own action handling) work. Safe because actions execute by opcode/params, not text, and
	 * the menu is already closed - this has no visual effect.
	 */
	public void restoreForClick(MenuEntry entry)
	{
		if (entry == null)
		{
			return;
		}
		EntryState state = entryStates.remove(entry);
		if (state == null || !state.owns(entry))
		{
			return;
		}
		if (state.optionRendered) entry.setOption(state.option);
		if (state.targetRendered) entry.setTarget(state.target);
	}

	/**
	 * @param type the entry's MenuAction, used to pick the scene word for "Use" (null = generic)
	 * @return rendered option, or null to leave the English option unchanged
	 */
	public String translateOption(String option, MenuAction type, int size)
	{
		return translateOption(option, type, size, OPTION_COLOR);
	}

	private String translateOption(String option, MenuAction type, int size, int color)
	{
		// Scene-specific "Use" must run before the table lookups, which would return the generic word.
		String use = useZh(Tags.stripTags(option), type);
		if (use != null)
		{
			return glyph.toImgTags(use, color, 0, size);
		}
		// Whole-option entries that embed a coloured name ("Open <col=..>Ardougne Journal</col>") are stored
		// colour-templated in ACTIONS; match that first so the embedded name is translated and keeps its colour.
		String whole = translator.lookupRenderMenuOption(option, color, size);
		if (whole != null)
		{
			return whole;
		}
		String plain = Tags.stripTags(option);
		if (plain.isEmpty())
		{
			return null;
		}
		// general world actions live in ACTIONS; item actions (Wear/Wield/Eat/Drink/...) in INVENTORY_ACTIONS
		String r = translator.lookupRender(Category.ACTIONS, plain, color, 0, size);
		if (r == null)
		{
			r = translator.lookupRender(Category.INVENTORY_ACTIONS, plain, color, 0, size);
		}
		if (r == null)
		{
			// some menu options are interface/tab labels (e.g. "Sailing Options") stored in INTERFACE
			r = translator.lookupRender(Category.INTERFACE, plain, color, 0, size);
		}
		return r;
	}

	/** Scene word for a "Use" option, or null to fall through to the table translation (使用). */
	private static String useZh(String plainOption, MenuAction type)
	{
		if (type == null || !"Use".equals(plainOption))
		{
			return null;
		}
		switch (type)
		{
			case WIDGET_TARGET:
				return USE_SELECT_ZH; // selecting the inventory item to use on something else
			case WIDGET_TARGET_ON_WIDGET:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_NPC:
			case WIDGET_TARGET_ON_PLAYER:
			case WIDGET_TARGET_ON_GROUND_ITEM:
				return USE_APPLY_ZH; // "Use <item> -> <target>" reads as 用 <item> -> <target>
			default:
				return null; // direct "Use" on an object/NPC keeps the generic word
		}
	}

	/** @return rendered target (name + localised level), or null to leave the English target */
	public String translateTarget(String target, int size)
	{
		return translateTarget(target, size, DEFAULT_TARGET_COLOR);
	}

	private String translateTarget(String target, int size, int rowColor)
	{
		// "Use <item> -> <target>" (item selected, hovering another) joins two names; the combined
		// string never matches the name table, so translate each side and keep the separator.
		int arrow = target.indexOf(" -> ");
		if (arrow >= 0)
		{
			String left = target.substring(0, arrow);
			String right = target.substring(arrow + 4);
			String lr = translateTarget(left, size, rowColor);
			String rr = translateTarget(right, size, rowColor);
			if (lr == null && rr == null)
			{
				return null;
			}
			return (lr != null ? lr : left) + " -> " + (rr != null ? rr : right);
		}
		String plainTarget = Tags.stripTags(target);
		if (plainTarget.isEmpty())
		{
			return null;
		}
		int color = Tags.firstColor(target, rowColor);

		String levelSuffix = "";
		Matcher lm = LEVEL.matcher(plainTarget);
		if (lm.find())
		{
			String lvl = translator.lookupRender(Category.GAME_TEXT, "level", color, 0, size);
			String lvlText = (lvl != null) ? lvl : "level";
			levelSuffix = "<col=" + Tags.hex(color) + "> (" + lvlText + "-" + lm.group(1) + ")</col>";
		}

		String name = LEVEL.matcher(plainTarget).replaceAll("").trim();
		String renderedName = translator.lookupRender(Category.NAME, name, color, 0, size);
		if (renderedName == null)
		{
			// some targets are interface/tab labels (e.g. "Sailing Options") stored in INTERFACE
			renderedName = translator.lookupRender(Category.INTERFACE, name, color, 0, size);
		}
		if (renderedName == null)
		{
			// skill-guide link targets ("Courses tab", "Cook's Assistant quest") live in SKILL_GUIDE
			renderedName = translator.lookupRender(Category.SKILL_GUIDE, name, color, 0, size);
		}
		if (renderedName == null)
		{
			return null; // not in table (or not ready): leave English so it stays readable
		}
		return renderedName + levelSuffix;
	}

}

package com.osrscn.hooks;

import com.osrscn.translate.Translator;
import java.util.Iterator;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.events.OverheadTextChanged;

/**
 * Translates NPC speech bubbles (overhead text). Player chat is left alone.
 *
 * <p>The lookup table answers instantly; AI answers asynchronously, so a bubble that misses the
 * table shows English at first. We keep such bubbles in a pending set and retry each tick until the
 * AI result is cached (then re-apply it to the still-showing bubble) or it times out.
 */
@Singleton
public class OverheadHandler
{
	private static final int OVERHEAD_COLOR = 0xffff00; // yellow, like the native bubble
	private static final long TIMEOUT_MS = 10_000;

	@Inject
	private Translator translator;

	// actor -> (english source, deadline) for bubbles still awaiting an async translation
	private final ConcurrentMap<Actor, Pending> pending = new ConcurrentHashMap<>();

	private static final class Pending
	{
		final String english;
		final long deadline;

		Pending(String english, long deadline)
		{
			this.english = english;
			this.deadline = deadline;
		}
	}

	public void handle(OverheadTextChanged event)
	{
		Actor actor = event.getActor();
		if (!(actor instanceof NPC))
		{
			pending.remove(actor);
			return; // NPC bubbles only - never translate player chat
		}
		String english = event.getOverheadText();
		if (english == null || english.isEmpty())
		{
			pending.remove(actor);
			return;
		}
		String zh = translator.translate(english, OVERHEAD_COLOR, 0);
		if (zh != null)
		{
			actor.setOverheadText(zh);
			pending.remove(actor);
		}
		else
		{
			pending.put(actor, new Pending(english, System.currentTimeMillis() + TIMEOUT_MS));
		}
	}

	/** Retry bubbles whose translation wasn't ready yet; call each tick. */
	public void tick()
	{
		if (pending.isEmpty())
		{
			return;
		}
		long now = System.currentTimeMillis();
		for (Iterator<ConcurrentMap.Entry<Actor, Pending>> it = pending.entrySet().iterator(); it.hasNext(); )
		{
			ConcurrentMap.Entry<Actor, Pending> e = it.next();
			Actor actor = e.getKey();
			Pending p = e.getValue();
			String current = actor.getOverheadText();
			// give up if it timed out or the bubble is gone / replaced by new (already-img) text
			if (now > p.deadline || current == null || current.isEmpty() || current.contains("<img="))
			{
				it.remove();
				continue;
			}
			String zh = translator.translate(p.english, OVERHEAD_COLOR, 0);
			if (zh != null)
			{
				actor.setOverheadText(zh);
				it.remove();
			}
		}
	}

	public void clear()
	{
		pending.clear();
	}
}

package com.osrscn.hooks;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;

/**
 * Declarative routing table for interface translation: one row per surface (widget group) carrying its
 * translation policy, plus a script-id -> targets map for surfaces a build script rewrites.
 *
 * <p>This collapses what used to be five scattered {@code Set}s (excluded / small / per-frame-excluded /
 * reconstruct / chatbox) and a hand-written {@code onScriptPostFired} if/else chain into one place. Adding
 * a newly-discovered flashing surface is now one builder line instead of edits in several methods, and an
 * unlisted group falls through to {@link #DEFAULT} (ordinary per-tick + per-frame UI text) automatically.
 */
final class SurfaceRegistry
{
	/** How a script hook reaches the widget(s) it must re-translate. */
	enum Reach
	{
		GROUP_ROOT,  // translateGroup(componentId): walk from this root component
		GROUP_ID,    // translateGroupId(groupId): walk every loaded root of this group
		COMPONENT    // translateComponent(componentId): walk just this component's subtree
	}

	static final class Target
	{
		final Reach reach;
		final int id;

		Target(Reach reach, int id)
		{
			this.reach = reach;
			this.id = id;
		}
	}

	/** Per-group translation policy. All flags default false (= ordinary per-tick + per-frame UI text). */
	static final class Surface
	{
		boolean excluded;         // never translated by the generic walk (player names, chatbox, new guide)
		boolean perFrameExcluded; // skipped by the per-frame pass (hit-test-sensitive / big list); tick only
		boolean slowScan;         // big list with many misses: only the game-tick slow lane walks it
		boolean small;            // render at the smaller info-box / tooltip glyph size
		boolean noAi;             // never AI-translate misses (HP bar: don't guess monster names)
		boolean reconstruct;      // owned by reconstructJournals (whole-task reflow), not the generic walk
		boolean noCollect;        // translated normally but never written to the missing file
	}

	private static final Surface DEFAULT = new Surface();

	// Build-time maps. They are sealed into the flat lookup structures below by seal(), because forGroup()
	// runs once per widget on every walk (~thousands of calls per client tick): an Integer-keyed map boxes
	// the group id on every one of them.
	private final Map<Integer, Surface> byGroup = new HashMap<>();
	private final Map<Integer, List<Target>> byScript = new HashMap<>();

	private Surface[] groups = new Surface[0]; // group id -> policy, null = DEFAULT

	/** Policy for a widget group; never null (unlisted groups get the default UI-text policy). */
	Surface forGroup(int groupId)
	{
		Surface s = (groupId >= 0 && groupId < groups.length) ? groups[groupId] : null;
		return s == null ? DEFAULT : s;
	}

	/** Table-only policy for the chatbox prompt line, which can also carry what the player is typing. */
	static Surface promptSurface()
	{
		Surface s = new Surface();
		s.noAi = true;
		s.noCollect = true;
		return s;
	}

	/** Targets to re-translate when {@code scriptId} fired, or null if no surface cares about it. */
	List<Target> forScript(int scriptId)
	{
		return byScript.get(scriptId);
	}

	private Surface row(int groupId)
	{
		return byGroup.computeIfAbsent(groupId, k -> new Surface());
	}

	private void script(int scriptId, Target... targets)
	{
		byScript.put(scriptId, Arrays.asList(targets));
	}

	private static int grp(int componentId)
	{
		return componentId >>> 16;
	}

	/** Freeze the builder maps into the flat arrays the hot lookups read. Group ids are &lt; 65536. */
	private void seal()
	{
		int max = 0;
		for (int g : byGroup.keySet())
		{
			max = Math.max(max, g);
		}
		groups = new Surface[max + 1];
		for (Map.Entry<Integer, Surface> e : byGroup.entrySet())
		{
			groups[e.getKey()] = e.getValue();
		}
	}

	static SurfaceRegistry build()
	{
		SurfaceRegistry r = new SurfaceRegistry();

		// ===== EXCLUDE: never translated by the generic walk =====
		// player-name lists (names are never translated) + dialogue/chat groups owned elsewhere.
		for (int g : new int[]{
				grp(InterfaceID.ChatLeft.NAME), grp(InterfaceID.ChatRight.NAME), grp(InterfaceID.Chatmenu.OPTIONS),
				grp(InterfaceID.Friends.UNIVERSE), grp(InterfaceID.Ignore.UNIVERSE), grp(InterfaceID.PmChat.CONTAINER),
				grp(InterfaceID.ChatchannelCurrent.UNIVERSE), grp(InterfaceID.SideChannels.UNIVERSE),
				grp(InterfaceID.SideChannelsLarge.UNIVERSE), grp(InterfaceID.ClansMembers.UNIVERSE),
				grp(InterfaceID.ClansSidepanel.UNIVERSE), grp(InterfaceID.ClansGuestSidepanel.UNIVERSE),
				860, // new-style skill guide: prose split into per-word widgets, unreadable word-by-word
				grp(InterfaceID.Chatbox.UNIVERSE) // messages -> ChatHandler; static tabs -> translateChatTabs()
		})
		{
			r.row(g).excluded = true;
		}

		// ===== SLOW SCAN: big lists full of lookup misses -> game-tick lane only =====
		// World switcher: hundreds of world rows that never enter the translated cache; the 50x/s
		// walk over them tanked FPS to 30-60 whenever the tab stayed open (e.g. after a hop). The
		// game-tick lane still translates the useful bits (activity names, filter/options).
		for (int g : new int[]{
				grp(InterfaceID.Worldswitcher.UNIVERSE),
				InterfaceID.WORLDSWITCHER_FILTER, InterfaceID.WORLDSWITCHER_OPTIONS // top-level ids are group ids
		})
		{
			r.row(g).slowScan = true;
		}

		// ===== SMALL: hover info-box / tooltip glyph size =====
		for (int g : new int[]{
				grp(InterfaceID.Stats.UNIVERSE), grp(InterfaceID.Prayerbook.UNIVERSE),
				grp(InterfaceID.MagicSpellbook.UNIVERSE), grp(InterfaceID.Emote.UNIVERSE),
				grp(InterfaceID.HpbarHud.UNIVERSE)
		})
		{
			r.row(g).small = true;
		}
		r.row(grp(InterfaceID.HpbarHud.UNIVERSE)).noAi = true; // HP bar: table only, never guess monster names

		// ===== PER-FRAME EXCLUDED: hit-test-sensitive / big list -> tick backstop + script hook only =====
		r.row(grp(InterfaceID.AccountSummarySidepanel.UNIVERSE)).perFrameExcluded = true; // SUMMARY_CLICK_LAYER hover
		r.row(grp(InterfaceID.CaTasks.UNIVERSE)).perFrameExcluded = true;                  // big scrollable task list

		// ===== RECONSTRUCT: whole-task reflow owns these (tick, debounced) =====
		r.row(grp(InterfaceID.Journalscroll.UNIVERSE)).reconstruct = true;
		r.row(grp(InterfaceID.Questjournal.UNIVERSE)).reconstruct = true;

		// ===== NO-COLLECT: translate but never write missing rows =====
		// For panels dominated by player-controlled text (boat naming, hiscore name lists). Populate
		// after an in-game group survey - only the player-text subpanels, NOT high-value label lists
		// like the report reasons. The mechanism ships first so the survey is one builder line each.
		// Trade screens carry the partner's display name in static labels ("Trading with: X"), a name
		// no fixed list can know in advance, so nothing from them may reach the missing file.
		for (int g : new int[]{334 /* trade confirm */, 335 /* trade offer */, 336 /* trade inventory side */})
		{
			r.row(g).noCollect = true;
		}

		// ===== SCRIPT hooks: a build script writes these on open/switch -> translate the instant it fires =====
		// Account summary: named TEXT_FORMAT(3948)/SECTION_FORMAT(3950) + the unnamed XP/play-time siblings 3947/3949.
		for (int s = ScriptID.ACCOUNT_SUMMARY_TEXT_FORMAT - 1; s <= ScriptID.ACCOUNT_SUMMARY_SECTION_FORMAT; s++)
		{
			r.script(s, new Target(Reach.GROUP_ROOT, InterfaceID.AccountSummarySidepanel.UNIVERSE));
		}
		// Old skill guide build script (9350): list slots via group-id walk + TITLE/CATEGORIES (outside that root).
		r.script(9350,
				new Target(Reach.GROUP_ID, InterfaceID.SKILL_GUIDE),
				new Target(Reach.COMPONENT, InterfaceID.SkillGuide.TITLE),
				new Target(Reach.COMPONENT, InterfaceID.SkillGuide.CATEGORIES));
		// Prayer hover tooltip draw-time rewrite (9444).
		r.script(9444, new Target(Reach.COMPONENT, InterfaceID.Prayerbook.TOOLTIP));

		r.seal();
		return r;
	}
}

package com.osrscn.text;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Shared helpers for the OSRS rich-text tags ({@code <col=RRGGBB>}, {@code </col>}, {@code <br>}, ...).
 * Previously each hook re-implemented these with slightly different regexes.
 */
public final class Tags
{
	// <u=RRGGBB> (coloured underline links, e.g. quest requirements) carry colour just like <col=RRGGBB>.
	private static final Pattern COL = Pattern.compile("<(?:col|u)=([0-9a-fA-F]{6})", Pattern.CASE_INSENSITIVE);
	private static final Pattern COL_TAG = Pattern.compile("</?col[^>]*>", Pattern.CASE_INSENSITIVE);
	private static final Pattern ALL_TAGS = Pattern.compile("<[^>]+>");
	// Opening colour tags only (<col=..>, <colHIGHLIGHT>); </col> has a '/' and is intentionally excluded.
	private static final Pattern OPEN_COL = Pattern.compile("<col[=a-zA-Z0-9]*?>");
	private static final Pattern COL_PLACEHOLDER = Pattern.compile("<colNum\\d+>");
	// Every colour/underline/strikethrough tag + colour placeholder, for stripping a line to plain text.
	private static final Pattern STYLE = Pattern.compile("(?i)</?(?:col|u|str)[^>]*>|<colNum\\d+>");
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	private Tags()
	{
	}

	/** First {@code <col=RRGGBB>} colour in the string, or {@code fallback} if there is none. */
	public static int firstColor(String s, int fallback)
	{
		if (s == null)
		{
			return fallback;
		}
		Matcher m = COL.matcher(s);
		return m.find() ? Integer.parseInt(m.group(1), 16) : fallback;
	}

	/** Remove every {@code <col>}/{@code </col>} tag, leaving other tags and the text intact. */
	public static String stripCol(String s)
	{
		return s == null ? "" : COL_TAG.matcher(s).replaceAll("");
	}

	/** Remove every tag and collapse whitespace; {@code <br>} becomes a space so words stay separated. */
	public static String stripTags(String s)
	{
		if (s == null)
		{
			return "";
		}
		String noTags = ALL_TAGS.matcher(s.replace("<br>", " ").replace('\u00A0', ' ')).replaceAll("");
		return WHITESPACE.matcher(noTags).replaceAll(" ").trim();
	}

	/** Lower-case 6-digit hex of an RGB value, for building {@code <col=RRGGBB>} tags. */
	public static String hex(int rgb)
	{
		return String.format("%06x", rgb & 0xFFFFFF);
	}

	// The <colNumN> colour-placeholder scheme below mirrors RuneLingual (BSD 2-Clause, see NOTICE) so we
	// can reuse its transcript data, whose English keys store colours as <colNum0>, <colNum1>, ... with
	// </col> left literal. We must produce identical keys at lookup time or coloured text never matches.

	/** Opening colour tags ({@code <col=..>}, {@code <colHIGHLIGHT>}) in order; {@code </col>} is excluded. */
	public static List<String> colorTags(String s)
	{
		List<String> out = new ArrayList<>();
		if (s != null)
		{
			Matcher m = OPEN_COL.matcher(s);
			while (m.find())
			{
				out.add(m.group());
			}
		}
		return out;
	}

	/** Replace opening colour tags with {@code <colNum0>}, {@code <colNum1>}, ... (transcript data format). */
	public static String placeholdColors(String s)
	{
		if (s == null)
		{
			return "";
		}
		// OPEN_COL can only match text starting with a literal lower-case "<col" (it is case-sensitive,
		// and "</col>" does not contain that substring), so anything else is returned unchanged - skip
		// the split + StringBuilder allocation. This runs several times per widget per lookup.
		if (s.indexOf("<col") < 0)
		{
			return s;
		}
		String[] parts = OPEN_COL.split(s);
		StringBuilder sb = new StringBuilder(s.length());
		for (int i = 0; i < parts.length; i++)
		{
			sb.append(parts[i]);
			if (i < parts.length - 1)
			{
				sb.append("<colNum").append(i).append('>');
			}
		}
		return sb.toString();
	}

	/** Inverse of {@link #placeholdColors}: substitute the captured tags back in by index. */
	public static String restoreColors(String s, List<String> tags)
	{
		if (s == null)
		{
			return "";
		}
		for (int i = 0; i < tags.size(); i++)
		{
			s = s.replace("<colNum" + i + ">", tags.get(i));
		}
		return s;
	}

	/** How many {@code <colNumN>} placeholders a string carries, to check a translation kept them all. */
	public static int placeholderCount(String s)
	{
		if (s == null)
		{
			return 0;
		}
		int n = 0;
		Matcher m = COL_PLACEHOLDER.matcher(s);
		while (m.find())
		{
			n++;
		}
		return n;
	}

	/** Drop colour placeholders and any literal {@code </col>}, for single-colour glyph rendering. */
	public static String stripColorPlaceholders(String s)
	{
		if (s == null)
		{
			return "";
		}
		return COL_TAG.matcher(COL_PLACEHOLDER.matcher(s).replaceAll("")).replaceAll("");
	}

	/** Drop every colour/underline/strikethrough tag and colour placeholder, leaving plain text, so a
	 *  styled line ({@code <u=ff0000>Temple of Ikov</u>}, struck {@code <str>...}) can match a plain
	 *  transcript key (quest/diary names are stored without styling). */
	public static String stripStyle(String s)
	{
		return s == null ? "" : STYLE.matcher(s).replaceAll("");
	}
}

package com.osrscn.translate;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.osrscn.AiBackend;
import com.osrscn.OsrscnConfig;
import java.io.BufferedReader;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Asynchronous AI fallback for text not found in the lookup table. Two backends (see {@code aiBackend}):
 * local Ollama ({@code /api/chat}) and any OpenAI-compatible online API ({@code /chat/completions}).
 *
 * <p>{@link #translate} never blocks: on a miss it returns {@code null} and fires a background
 * request; the result lands in the cache and is picked up by a later call.
 */
@Slf4j
@Singleton
public class AiTranslator
{
	// Includes local model loading and inference; never an unlimited read or whole-call wait.
	public static final long OLLAMA_REQUEST_TIMEOUT_MS = 60_000;
	private static final MediaType JSON = MediaType.parse("application/json");
	private static final Pattern THINK = Pattern.compile("(?s)<think>.*?</think>");
	// Value labels (bank/GE totals "(3.6B)", "(500)") change with every gp move, so they never form a
	// stable cross-session cache hit - keep them out of the on-disk reflow cache. Doses like "(4)" pass.
	private static final Pattern CACHE_DYNAMIC = Pattern.compile("\\([\\d.,]+[KkMmBb]\\)|\\(\\d[\\d.,]{2,}\\)");
	// Number-templated messages (kill counts "1,290", prices, durations "4:58", charges) differ by a value
	// every time, so a cached instance never matches the next - persisting them only bloats the file. The
	// live in-memory cache still serves them within a session; we just don't write them to disk.
	private static final Pattern CACHE_NUMTEMPLATE = Pattern.compile(
			"\\d,\\d|\\d:\\d\\d|kill count is:|completion count is:|Actively traded price|charges remaining"
			+ "|Personal best|Buy limit:|Guide price|You received:|received a drop:|You healed"
			+ "|Delve level:|Total duration|Fight duration|Value:\\s*\\d|Level:\\s*\\d|Wave:?\\s*\\d|Rank\\s+\\d");

	private static final String SYSTEM_PROMPT =
			"You are translating Old School RuneScape (OSRS) game text to Simplified Chinese.\n"
			+ "Rules:\n"
			+ "1. Concise, natural game-style Chinese. This is in-game text, not literature.\n"
			+ "2. Keep proper nouns without established translations in English.\n"
			+ "3. Preserve ALL tags exactly as-is: <br>, <colNum0>, </col>, [player name], [player 1], "
			+ "<osrscn-name-0>, [milady/sirrah] etc. Keep every <colNumN> placeholder in place around the "
			+ "same words it wraps in the source. Never translate placeholders and never add "
			+ "tags that are not in the source.\n"
			+ "4. Output ONLY the translation, nothing else.";

	@Inject
	private OkHttpClient httpClient;
	private OkHttpClient ollamaHttpClient; // shares the injected dispatcher and connection pool

	@Inject
	private OsrscnConfig config;

	@Inject
	private Gson gson;

	@Inject
	private java.util.concurrent.ScheduledExecutorService executor;
	private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
	private final Set<String> inFlight = ConcurrentHashMap.newKeySet();
	// Keys known to be on disk. A cache hit re-requested with persist=true gets written on the spot:
	// the 860 settle gate fires its first requests persist=false (frame unsettled) and replays them
	// persist=true once stable - without this, guide translations would never survive a restart.
	private final Set<String> persisted = ConcurrentHashMap.newKeySet();
	private final File dir = new File(RuneLite.RUNELITE_DIR, "osrscn");
	private String loadedModel; // model whose cache is currently in memory (per-model on disk)
	private long generation; // guarded by this; model round trips never reuse request ownership
	private File cacheFile;
	private volatile long lastDispatch;

	// Back off when the backend keeps failing (Ollama down, API unreachable) instead of
	// re-firing a request on every lookup miss.
	private static final int BACKOFF_AFTER_FAILURES = 3;
	private static final long BACKOFF_BASE_MS = 5_000;
	private static final long BACKOFF_MAX_MS = 300_000;
	private final java.util.concurrent.atomic.AtomicInteger failStreak = new java.util.concurrent.atomic.AtomicInteger();
	private volatile long backoffUntil;

	// monitor stats
	private final java.util.concurrent.atomic.AtomicInteger sessionCount = new java.util.concurrent.atomic.AtomicInteger();
	private final java.util.Deque<String> recent = new java.util.concurrent.ConcurrentLinkedDeque<>();

	/** Serializes player-mode revocation with admission of a fresh asynchronous request. */
	public static final class RequestPermit
	{
		private final java.util.function.BooleanSupplier allowed;
		private final RequestPermit owner;
		private boolean revoked;

		public RequestPermit(java.util.function.BooleanSupplier allowed)
		{
			this.allowed = allowed;
			owner = this;
		}

		/** Add a delivery's exact mode check while sharing its mode's cancellation boundary. */
		public RequestPermit(RequestPermit parent, java.util.function.BooleanSupplier allowed)
		{
			owner = parent.owner;
			this.allowed = () -> parent.allowed.getAsBoolean() && allowed.getAsBoolean();
		}

		public void revoke()
		{
			synchronized (owner) { owner.revoked = true; }
		}

		private void dispatch(Runnable action)
		{
			synchronized (owner)
			{
				if (!owner.revoked && allowed.getAsBoolean() && !owner.revoked) action.run();
			}
		}
	}

	/** @return cached translation, or null if disabled / still pending (request fired on miss). */
	public String translate(String english)
	{
		return translate(english, true);
	}

	/**
	 * Cache-only peek: no request is dispatched and nothing is written, so callers can skip expensive
	 * pre-processing when the answer is already known and re-ask through {@link #translate} for it.
	 *
	 * @return the cached translation, or null if this text has never been translated
	 */
	public synchronized String cached(String english)
	{
		if (english == null || english.isEmpty())
		{
			return null;
		}
		ensureLoaded();
		return cache.get(english);
	}

	/**
	 * @param persist whether a fresh translation is written to the on-disk cache. Player chat passes
	 *                {@code false}: player slang rarely recurs verbatim, so persisting it only bloats
	 *                the cache file and slows start-up loading. It is still cached in memory.
	 * @return cached translation (served even when AI is disabled), or null when not cached and AI is
	 *         disabled, or null while a fresh request is still pending (request fired on miss).
	 */
	public String translate(String english, boolean persist)
	{
		return translate(english, persist, null);
	}

	/** Player callers retain their mode's permit through preprocessing and every per-line request. */
	public String translate(String english, boolean persist, RequestPermit permit)
	{
		if (english == null || english.isEmpty())
		{
			return null;
		}
		final long requestedGeneration;
		synchronized (this)
		{
			ensureLoaded();
			String cached = cache.get(english);
			if (cached != null)
			{
				// AI off remains cache-only, including promotion of an existing memory-only entry.
				if (persist && isPersistable(english) && persisted.add(english))
				{
					persistToDisk(english, cached);
				}
				return cached;
			}
			if (!config.useLocalAi()) return null;
			requestedGeneration = generation;
		}
		// Never acquire a permit owner while holding this monitor. Admission order is owner -> this.
		if (permit == null) dispatch(english, persist, requestedGeneration);
		else permit.dispatch(() -> dispatch(english, persist, requestedGeneration));
		return null;
	}

	private synchronized void dispatch(String english, boolean persist, long requestedGeneration)
	{
		ensureLoaded();
		if (requestedGeneration != generation || !config.useLocalAi() || cache.containsKey(english))
		{
			return; // model/config changed or another callback filled this miss while acquiring admission
		}
		if (System.currentTimeMillis() < backoffUntil)
		{
			return; // backend keeps failing: wait out the backoff window
		}
		// rate limit so Ollama doesn't saturate the GPU and stall the game (both configurable)
		if (inFlight.size() >= Math.max(1, config.aiConcurrency())
				|| System.currentTimeMillis() - lastDispatch < config.aiPaceMs())
		{
			return;
		}
		if (!inFlight.add(english))
		{
			return; // already requested
		}
		lastDispatch = System.currentTimeMillis();
		RequestState state = new RequestState(generation, loadedModel);
		try
		{
			request(english, persist, state);
		}
		catch (RuntimeException e)
		{
			if (isCurrent(state))
			{
				recordFailure();
				finish(english, state);
			}
			if (persist) log.warn("OSRSCN AI dispatch failed", e);
			else log.warn("OSRSCN AI dispatch failed (non-persistent request): {}", e.getClass().getSimpleName());
		}
	}

	public int cacheSize()
	{
		return cache.size();
	}

	public int inFlightCount()
	{
		return inFlight.size();
	}

	public int sessionCount()
	{
		return sessionCount.get();
	}

	/** Most recent translations (newest first), for the monitor panel. */
	public java.util.List<String> recent()
	{
		return new java.util.ArrayList<>(recent);
	}

	/** Read the disk cache off the game thread so the first lookup miss doesn't stall the client. */
	public void preloadAsync()
	{
		executor.execute(this::ensureLoaded);
	}

	/** Each model keeps its own disk cache, so switching models doesn't return the old one's output. */
	private synchronized void ensureLoaded()
	{
		String model = activeModel();
		if (model.equals(loadedModel))
		{
			return;
		}
		configurationChanged();
		loadedModel = model;
		//noinspection ResultOfMethodCallIgnored
		dir.mkdirs();
		cacheFile = new File(dir, "ai_" + model.replaceAll("[^a-zA-Z0-9._-]", "_") + ".tsv");
		if (cacheFile.exists())
		{
			try (BufferedReader r = Files.newBufferedReader(cacheFile.toPath(), StandardCharsets.UTF_8))
			{
				String line;
				while ((line = r.readLine()) != null)
				{
					int t = line.indexOf('\t');
					if (t > 0 && t < line.length() - 1)
					{
						String k = line.substring(0, t);
						String v = line.substring(t + 1);
						cache.putIfAbsent(k, v);
						persisted.add(k);
						// Entries written before a normalize() change keep their old key; re-normalize on
						// load so the current query key still hits and the AI isn't re-run for them.
						String nk = TranslationStore.normalize(k);
						if (!nk.equals(k))
						{
							cache.putIfAbsent(nk, v);
							persisted.add(nk);
						}
					}
				}
				log.info("OSRSCN AI cache loaded: {} entries ({})", cache.size(), cacheFile.getName());
			}
			catch (Exception e)
			{
				log.warn("OSRSCN: failed to load AI cache", e);
			}
		}
	}

	/** Invalidate synchronously on model/connection events, even A -> B -> A without a lookup. */
	public synchronized void configurationChanged()
	{
		invalidateRequests();
		loadedModel = null;
		cacheFile = null;
		cache.clear();
		persisted.clear();
	}

	private void invalidateRequests()
	{
		generation++;
		inFlight.clear();
		failStreak.set(0);
		backoffUntil = 0;
		lastDispatch = 0;
	}

	private static final class RequestState
	{
		final long generation;
		final String model;
		boolean completed;

		RequestState(long generation, String model)
		{
			this.generation = generation;
			this.model = model;
		}
	}

	/** Called under this monitor, including a recheck after potentially reentrant config getters. */
	private boolean isCurrent(RequestState state)
	{
		return !state.completed && state.generation == generation && state.model.equals(loadedModel)
				&& state.model.equals(activeModel()) && state.generation == generation && !state.completed;
	}

	private void finish(String english, RequestState state)
	{
		if (isCurrent(state))
		{
			inFlight.remove(english);
			lastDispatch = System.currentTimeMillis();
		}
		state.completed = true;
	}

	/**
	 * Gate for the on-disk reflow cache only - never the in-memory {@code cache}, which always serves live
	 * on-screen text (cache.put is unconditional). Rejects the two categories that can never be a stable
	 * cross-session hit and only bloat the cache / pollute reflow submissions: player-authored CJK content
	 * (game English is never CJK), dynamic value labels, and number-templated messages that never recur.
	 * Deliberately does NOT apply MissingCollector's fragment / MAX_LEN / WORDY rules - those legitimately
	 * get translated live (e.g. wrapped info-box lines), and dropping them from disk would make AI-off
	 * users lose the translation next session.
	 */
	private static boolean isPersistable(String english)
	{
		if (english == null)
		{
			return false;
		}
		for (int i = 0; i < english.length(); i++)
		{
			if (english.charAt(i) >= 0x2E80)
			{
				return false; // CJK = player-created content (inventory-setup / bank-tab names)
			}
		}
		return !CACHE_DYNAMIC.matcher(english).find() && !CACHE_NUMTEMPLATE.matcher(english).find();
	}

	private synchronized void persistToDisk(String english, String zh)
	{
		if (cacheFile == null || english.indexOf('\t') >= 0 || english.indexOf('\n') >= 0
				|| zh.indexOf('\n') >= 0)
		{
			return; // skip entries that would corrupt the line-based file
		}
		try (FileWriter w = new FileWriter(cacheFile, StandardCharsets.UTF_8, true))
		{
			w.write(english + "\t" + zh + "\n");
		}
		catch (IOException e)
		{
			log.debug("OSRSCN: failed to append AI cache", e);
		}
	}

	public synchronized void clearCache()
	{
		ensureLoaded(); // configuration invalidation may have cleared the current file ownership
		invalidateRequests();
		cache.clear();
		persisted.clear();
		if (cacheFile != null)
		{
			//noinspection ResultOfMethodCallIgnored
			cacheFile.delete();
		}
	}

	/** Called under this monitor; only local inference gets the cold-load budget. */
	private OkHttpClient inferenceClient(boolean api)
	{
		if (api) return httpClient;
		if (ollamaHttpClient == null)
		{
			ollamaHttpClient = httpClient.newBuilder()
					.readTimeout(OLLAMA_REQUEST_TIMEOUT_MS, TimeUnit.MILLISECONDS)
					.callTimeout(OLLAMA_REQUEST_TIMEOUT_MS, TimeUnit.MILLISECONDS)
					.build();
		}
		return ollamaHttpClient;
	}

	private void request(String english, boolean persist, RequestState state)
	{
		JsonArray messages = new JsonArray();
		messages.add(message("system", SYSTEM_PROMPT));
		messages.add(message("user", english));

		boolean api = config.aiBackend() == AiBackend.OPENAI;
		final String url = api ? apiEndpoint() : ollamaEndpoint();
		Request req = api ? buildApiRequest(url, messages, state.model) : buildOllamaRequest(url, messages, state.model);
		if (req == null)
		{
			finish(english, state); // misconfigured: no request, and no failure/backoff increment
			return;
		}

		Call pending = inferenceClient(api).newCall(req);
		if (!isCurrent(state)) return;
		pending.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				synchronized (AiTranslator.this)
				{
					if (!isCurrent(state)) return;
					recordFailure();
					finish(english, state);
				}
				if (persist) log.warn("OSRSCN AI request failed ({}): {}", url, e.toString());
				else log.warn("OSRSCN AI request failed (non-persistent request): {}", e.getClass().getSimpleName());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						synchronized (AiTranslator.this)
						{
							if (!isCurrent(state)) return;
							recordFailure();
						}
						if (persist) log.warn("OSRSCN AI HTTP {} for model '{}'", r.code(), state.model);
						else log.warn("OSRSCN AI HTTP {} (non-persistent request)", r.code());
						return;
					}
					// Response IO/parse must not hold the model monitor: switching may happen mid-read.
					String content = r.body() == null ? null : parseContent(r.body().string());
					synchronized (AiTranslator.this)
					{
						if (!isCurrent(state)) return;
						recordSuccess();
						if (content != null && !content.isEmpty())
						{
							String zh = clean(content);
							cache.put(english, zh);
							if (persist && isPersistable(english) && persisted.add(english))
							{
								persistToDisk(english, zh);
							}
							sessionCount.incrementAndGet();
							recent.addFirst(english + "  →  " + zh);
							while (recent.size() > 40)
							{
								recent.pollLast();
							}
							if (persist) log.debug("OSRSCN AI: '{}' -> '{}'", english, zh);
							else log.debug("OSRSCN AI: non-persistent translation completed");
						}
					}
				}
				catch (Exception e)
				{
					// Parsing and close errors can contain response text, even for stale requests.
					if (persist) log.warn("OSRSCN AI parse failed", e);
					else log.warn("OSRSCN AI parse failed (non-persistent request): {}", e.getClass().getSimpleName());
				}
				finally
				{
					synchronized (AiTranslator.this) { finish(english, state); }
				}
			}
		});
	}

	private void recordFailure()
	{
		int n = failStreak.incrementAndGet();
		if (n >= BACKOFF_AFTER_FAILURES)
		{
			long delay = Math.min(BACKOFF_MAX_MS, BACKOFF_BASE_MS << Math.min(6, n - BACKOFF_AFTER_FAILURES));
			backoffUntil = System.currentTimeMillis() + delay;
			log.warn("OSRSCN AI: {} consecutive failures, backing off {}s", n, delay / 1000);
		}
	}

	private void recordSuccess()
	{
		failStreak.set(0);
		backoffUntil = 0;
	}

	/** The model name for the active backend; also names the per-model on-disk cache file. */
	private String activeModel()
	{
		return config.aiBackend() == AiBackend.OPENAI ? config.apiModel() : config.ollamaModel();
	}

	private String ollamaEndpoint()
	{
		return config.ollamaUrl().replaceAll("/+$", "") + "/api/chat";
	}

	private Request buildOllamaRequest(String url, JsonArray messages, String model)
	{
		JsonObject body = new JsonObject();
		body.addProperty("model", model);
		body.addProperty("stream", false);
		body.add("messages", messages);
		return new Request.Builder()
				.url(url)
				.post(RequestBody.create(JSON, gson.toJson(body)))
				.build();
	}

	/** Base API address (auto-filled from the provider preset) with {@code /chat/completions} appended. */
	private String apiEndpoint()
	{
		String base = config.apiUrl().trim().replaceAll("/+$", "");
		if (base.isEmpty())
		{
			return "";
		}
		return base.endsWith("/chat/completions") ? base : base + "/chat/completions";
	}

	private Request buildApiRequest(String url, JsonArray messages, String model)
	{
		String key = config.apiKey().trim();
		model = model.trim();
		if (url.isEmpty() || key.isEmpty() || model.isEmpty())
		{
			log.warn("OSRSCN AI: 在线 API 未配置完整（API 地址 / 密钥 / 模型）");
			return null;
		}
		JsonObject body = new JsonObject();
		body.addProperty("model", model);
		body.addProperty("stream", false);
		body.add("messages", messages);
		return new Request.Builder()
				.url(url)
				.addHeader("Authorization", "Bearer " + key)
				.post(RequestBody.create(JSON, gson.toJson(body)))
				.build();
	}

	/**
	 * Check connectivity to the active backend without spending any tokens: lists models
	 * (Ollama {@code /api/tags}, OpenAI {@code /models}) - no text is generated. The result lands on an
	 * OkHttp thread, so the Swing caller must marshal {@code onResult} back to the EDT.
	 *
	 * @param onResult (ok, message): ok=true on a 2xx reply, with a short human-readable message.
	 */
	public void testConnection(java.util.function.BiConsumer<Boolean, String> onResult)
	{
		boolean api = config.aiBackend() == AiBackend.OPENAI;
		Request req;
		if (api)
		{
			String base = config.apiUrl().trim().replaceAll("/+$", "");
			String key = config.apiKey().trim();
			if (base.isEmpty() || key.isEmpty())
			{
				onResult.accept(false, "请先填写 API 地址和密钥");
				return;
			}
			req = new Request.Builder().url(base + "/models").header("Authorization", "Bearer " + key).get().build();
		}
		else
		{
			String base = config.ollamaUrl().trim().replaceAll("/+$", "");
			if (base.isEmpty())
			{
				onResult.accept(false, "请先填写 Ollama 地址");
				return;
			}
			req = new Request.Builder().url(base + "/api/tags").get().build();
		}
		httpClient.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onResult.accept(false, "连接失败：" + e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful())
					{
						onResult.accept(true, api ? "连接成功，密钥有效" : "连接成功");
					}
					else if (r.code() == 401 || r.code() == 403)
					{
						onResult.accept(false, "密钥无效或无权限 (HTTP " + r.code() + ")");
					}
					else
					{
						onResult.accept(false, "连接失败 (HTTP " + r.code() + ")");
					}
				}
			}
		});
	}

	/** Parse the assistant reply from either Ollama ({@code /api/chat}) or OpenAI-style responses. */
	private String parseContent(String json)
	{
		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null)
		{
			return null;
		}
		// Ollama /api/chat: { "message": { "content": ... } }
		if (root.has("message") && root.get("message").isJsonObject())
		{
			JsonObject msg = root.getAsJsonObject("message");
			if (msg.has("content"))
			{
				return msg.get("content").getAsString();
			}
		}
		// OpenAI-compatible /chat/completions: { "choices": [ { "message": { "content": ... } } ] }
		if (root.has("choices"))
		{
			JsonArray choices = root.getAsJsonArray("choices");
			if (choices != null && choices.size() > 0 && choices.get(0).isJsonObject())
			{
				JsonObject first = choices.get(0).getAsJsonObject();
				if (first.has("message") && first.get("message").isJsonObject())
				{
					JsonObject msg = first.getAsJsonObject("message");
					if (msg.has("content"))
					{
						return msg.get("content").getAsString();
					}
				}
			}
		}
		return null;
	}

	private static String clean(String s)
	{
		return THINK.matcher(s).replaceAll("").trim();
	}

	private JsonObject message(String role, String content)
	{
		JsonObject m = new JsonObject();
		m.addProperty("role", role);
		m.addProperty("content", content);
		return m;
	}
}

package com.osrscn.translate;

import com.osrscn.OsrscnConfig;
import java.io.BufferedReader;
import java.io.File;
import java.io.FileWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Local-only collector for game text that the lookup table can't translate, so the maintainer can
 * batch-translate it later and feed it back into the tables. Writes one entry per unique line to
 * {@code ~/.runelite/osrscn/missing_<install id>.tsv}; the plugin never uploads it (the side panel
 * offers a manual clipboard-and-browser submission the user performs themselves).
 *
 * <p>The file carries a stable per-install id (see {@link #installId()}) so files from different
 * contributors never collide; a legacy {@code missing.tsv} is renamed on first access.
 *
 * <p>Off unless {@link OsrscnConfig#collectMissing()} is on. Only real prose ({@code WORDY}) is kept,
 * and callers must pass game content only (dialogue / interface / menu) - never player chat.
 */
@Slf4j
@Singleton
public class MissingCollector
{
	private static final Pattern WORDY = Pattern.compile("[A-Za-z]{3,}");
	// Reconstructed quest-journal / achievement-diary sentences can run long; 300 dropped some, so allow
	// more. Still bounded to keep pathological strings out of the collected file.
	private static final int MAX_LEN = 500;
	// A wrapped interface line (a quest-journal line when whole-task reflow is off, a long tip's middle
	// row, ...) is only ever half a sentence, and translating half-sentences yields broken data. Reject
	// the tell-tale mid-sentence chunks: a lowercase-leading continuation, or a run of words that ends on
	// a linking word with no terminal punctuation. Whole labels ("More info", "Over the Mountains") and
	// full sentences (which end in punctuation) pass; only genuine fragments are dropped.
	private static final Pattern FRAG_END = Pattern.compile("(?i)\\b(the|a|an|to|of|for|in|on|at|with|from|by"
			+ "|and|or|as|your|my|his|her|its|their|our|that|which|you|we|they|is|are|was|were|be|been)$");
	// Live/dynamic labels that recur with a changing value (bank tab totals "Tab 2 (96.9K)", amount
	// buttons "Deposit-15000"): not translatable content, and they spam the file as the value ticks.
	// "Showing items: <what the player typed>" is one row per search term, and the tail is the player's
	// own text, which must never reach the collected file at all.
	private static final Pattern DYNAMIC = Pattern.compile(
			"\\([\\d.,]+[KkMmBb]\\)|^(?:Deposit|Withdraw)-\\d+$|^Showing items: |^Tab \\d+$");
	// Non-content classes observed in collected files (2026-07-16 field audit): bare count labels
	// ("0 cannonballs") and widget-join artifacts that start with punctuation (real sentences never
	// do). News broadcasts (trailing "|p" link marker, "Click here...") stay collectable - maintainer
	// decision 2026-07-17: announcements are player-visible and worth translating.
	private static final Pattern NOISE = Pattern.compile("^\\d+\\s+\\S+$|^[.,;)\\]]");
	// Parameterized transaction messages: one instance per traded item would collect forever; the
	// synthetic GE lookup (Translator.syntheticLookup) composes them from the name table instead.
	// "Unable to find <name>" (player search) carries the searched player's name - never collectable.
	private static final Pattern TEMPLATE_MSG = Pattern.compile(
			"(?i)^Grand Exchange: (Finished )?(buying|selling) |^(Buy|Sell): \\d+ x |^(Bought|Sold): "
			+ "|^Unable to find ");
	private static final Pattern TAGS = Pattern.compile("<[^>]+>");
	private static final Pattern WS = Pattern.compile("\\s+");

	// --- word salad (mid-fill scramble) -------------------------------------------------------------
	// The new-style skill guide (group 860) fills a paragraph word by word across frames, so a snapshot
	// taken mid-fill reads like a sentence but is scrambled ("Range , such as the one in Lumbridge
	// Castle.", "...select an to Accurate"). Rows like that were translated and shipped, and the upstream
	// settle gate proved leaky, so the check sits here: record() is the one choke point every collection
	// path goes through. Only the cheap, high-confidence tells from tools/clean_inbox.py (stages 3-4) are
	// ported - containment, cross-row dedup and library comparison need the whole batch and stay in the
	// pipeline. Precision over recall: a false reject silently loses a real missing line, a false accept
	// is one junk row the pipeline still catches.

	// A space before a comma or full stop is a relayout join scar in reflowed prose. NOT a general rule:
	// 137 published rows match it, including ordinary dialogue ("Hey , what are you doing here?"), which
	// is why isSalad() only runs on the reflow surfaces. See REFLOW_SOURCE.
	private static final Pattern FLOAT_PUNCT = Pattern.compile("\\s[,.](?:\\s|$)");
	// Word pairs English never produces: doubled articles, doubled prepositions, or an article glued
	// straight onto a preposition ("select an to Accurate"). Case is load-bearing - the trailing word is
	// matched lower-case only so real text like "the On switch" survives, and the article+preposition
	// rule takes a lower-case article only so a capitalised letter label ("The A to Z") survives too.
	// The lookahead keeps hyphenated words ("the in-game clock") out.
	private static final Pattern SALAD_PAIR = Pattern.compile(
			"\\b(?:[Tt]he|[Aa]n?)\\s+(?:the|an?)\\b"
			+ "|\\b(?:the|an?)\\s+(?:to|of|in|on|for|with|and|or|at|by|from)(?=\\s|$)"
			+ "|\\b(to|of|in|on|for|with)\\s+\\1\\b");
	// Text that continues in lower case after a full stop is two pieces joined mid-fill ("...combat
	// skills. and"). Needs two letters before the stop, so "e.g." / "i.e." never match; the remaining
	// abbreviations are listed out. URLs and decimals are safe (no space after the stop / not letters).
	private static final Pattern MID_PERIOD = Pattern.compile("([A-Za-z]{2,})\\.\\s+[a-z]");
	private static final Set<String> ABBREV = new HashSet<>(Arrays.asList(
			"etc", "eg", "ie", "vs", "approx", "min", "max", "sec", "hr", "lvl", "mr", "mrs", "dr", "st", "no"));

	@Inject
	private OsrscnConfig config;
	@Inject
	private ScheduledExecutorService executor;

	private static final String ID_CHARS = "abcdefghijklmnopqrstuvwxyz0123456789";

	private final File dir = new File(RuneLite.RUNELITE_DIR, "osrscn");
	private volatile String installId;
	private volatile File file; // missing_<installId>.tsv, resolved (and legacy file migrated) lazily
	private final java.util.Set<String> seen = ConcurrentHashMap.newKeySet();
	private final ConcurrentLinkedQueue<String> pending = new ConcurrentLinkedQueue<>();
	private final AtomicBoolean loaded = new AtomicBoolean();
	private final AtomicBoolean flusherStarted = new AtomicBoolean();
	private final AtomicBoolean sessionMarked = new AtomicBoolean();
	private volatile ScheduledFuture<?> flusherFuture;

	/**
	 * Record a table miss as a row matching the transcript TSV columns
	 * ({@code english<TAB>translation(empty)<TAB>category<TAB>sub_category<TAB>source}), so the collected
	 * file lines up with the data tables for later translating and merging. No-op when disabled, not real
	 * prose, or already seen this session / in the file. Safe on the client thread (disk I/O is deferred).
	 *
	 * @param english     game English that failed lookup (player names already substituted to placeholders)
	 * @param category    target table hint: {@code "dialogue"}, {@code "interface"}, {@code "name"}, ...
	 * @param subCategory entity context, e.g. the NPC name for dialogue (may be empty)
	 * @param source      speaker / origin, e.g. the NPC name or {@code "Player"} (may be empty)
	 */
	public void record(String english, String category, String subCategory, String source)
	{
		if (english == null || !config.collectMissing())
		{
			return;
		}
		String t = english.trim();
		if (t.isEmpty() || t.length() > MAX_LEN || t.indexOf('\t') >= 0 || t.indexOf('\n') >= 0)
		{
			return;
		}
		// Test for prose on the tag-stripped text, never the raw string: our own output is a run of
		// <img=N> char-image tags, and "img" is three letters, so a fully translated widget passed the
		// prose test and our own translations were collected as missing words. The "[player name]" mask
		// is dropped too, so a widget that was only a name is rejected.
		String bare = TAGS.matcher(t).replaceAll("").trim();
		if (!WORDY.matcher(bare.replace("[player name]", "")).find())
		{
			return;
		}
		if (isFragment(bare) || DYNAMIC.matcher(t).find() || NOISE.matcher(t).find()
				|| TEMPLATE_MSG.matcher(t).find() || hasCjk(t)
				|| ((isReflowSource(source) || isReflowSource(subCategory)) && isSalad(bare)))
		{
			// fragment, live value label, join noise, per-item template instance, player CJK, mid-fill salad
			return;
		}
		ensureLoaded();
		if (seen.add(dedupKey(t)))
		{
			pending.add(t + "\t\t" + clean(category) + "\t" + clean(subCategory) + "\t" + clean(source));
			ensureFlusher();
		}
	}

	private static final Pattern DEDUP_NUM = Pattern.compile("\\d+(?:[.,]\\d+)*");
	private static final Pattern DEDUP_COL = Pattern.compile("(?i)<colnum\\d+>|</col>");

	/**
	 * Dedup key only: colour placeholders stripped and numbers templated, so the value/colour variants
	 * of one template don't each burn a row. The stored sample keeps its original text (translators
	 * need the real numbers as context, and names like "Rune 2h sword" must not lose their digits).
	 */
	private static String dedupKey(String t)
	{
		return TranslationStore.normalize(DEDUP_NUM.matcher(DEDUP_COL.matcher(t).replaceAll(" ")).replaceAll("#"));
	}

	/**
	 * A wrapped-line fragment (mid-sentence), which must not be collected as a translatable unit.
	 *
	 * @param bare the text with tags stripped
	 */
	private static boolean isFragment(String bare)
	{
		if (bare.isEmpty())
		{
			return false;
		}
		if (Character.isLowerCase(bare.charAt(0)))
		{
			return true; // starts mid-sentence
		}
		char last = bare.charAt(bare.length() - 1);
		boolean terminal = last == '.' || last == '!' || last == '?' || last == ':' || last == ')' || last == '"';
		return !terminal && WS.split(bare).length >= 4 && FRAG_END.matcher(bare).find();
	}

	/**
	 * Word salad only comes from the surfaces that reflow prose frame by frame (the new-style skill guide
	 * and the journal reconstruction), and their provenance tag is knowledge only the client has. Scoping
	 * the check to them keeps the shape rules away from ordinary dialogue and UI text, where they draw
	 * false positives. A client-side reject is invisible and can never be hot-fixed, so it stays narrow.
	 */
	private static boolean isReflowSource(String tag)
	{
		return tag != null && (tag.startsWith("skillguide") || tag.startsWith("journal"));
	}

	/**
	 * Word salad: a paragraph snapshot taken while the client was still filling it word by word. Only
	 * mechanical, high-confidence tells (see the pattern comments above); anything ambiguous is accepted
	 * and left to the offline cleaner.
	 *
	 * @param bare the text with tags stripped
	 */
	private static boolean isSalad(String bare)
	{
		if (bare.isEmpty())
		{
			return false;
		}
		if (FLOAT_PUNCT.matcher(bare).find() || SALAD_PAIR.matcher(bare).find())
		{
			return true;
		}
		Matcher m = MID_PERIOD.matcher(bare);
		while (m.find())
		{
			if (!ABBREV.contains(m.group(1).toLowerCase(java.util.Locale.ROOT)))
			{
				return true;
			}
		}
		return false;
	}

	/** Game English is never CJK, so any CJK codepoint means player-authored content (setup / tab names). */
	private static boolean hasCjk(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (s.charAt(i) >= 0x2E80)
			{
				return true;
			}
		}
		return false;
	}

	private static String clean(String s)
	{
		return s == null ? "" : s.replace('\t', ' ').replace('\n', ' ').replace('\r', ' ').trim();
	}

	/**
	 * Stable per-install 6-char id, created once and kept in {@code .reflow_id}. It names the missing
	 * file (and any submission), so files from different contributors never collide and repeat
	 * submissions from the same install are recognisable.
	 */
	public synchronized String installId()
	{
		if (installId != null)
		{
			return installId;
		}
		File idFile = new File(dir, ".reflow_id");
		try
		{
			if (idFile.exists())
			{
				String s = new String(Files.readAllBytes(idFile.toPath()), StandardCharsets.UTF_8).trim();
				if (s.matches("[a-z0-9]{4,16}"))
				{
					installId = s;
					return s;
				}
			}
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: failed to read .reflow_id", e);
		}
		StringBuilder sb = new StringBuilder(6);
		SecureRandom rnd = new SecureRandom();
		for (int i = 0; i < 6; i++)
		{
			sb.append(ID_CHARS.charAt(rnd.nextInt(ID_CHARS.length())));
		}
		installId = sb.toString();
		try
		{
			//noinspection ResultOfMethodCallIgnored
			dir.mkdirs();
			Files.write(idFile.toPath(), installId.getBytes(StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: failed to write .reflow_id", e); // id stays session-only, still usable
		}
		return installId;
	}

	/** The per-install missing file; a legacy {@code missing.tsv} is renamed to it on first access. */
	public synchronized File missingFile()
	{
		if (file != null)
		{
			return file;
		}
		File f = new File(dir, "missing_" + installId() + ".tsv");
		File legacy = new File(dir, "missing.tsv");
		if (legacy.exists() && !f.exists())
		{
			try
			{
				Files.move(legacy.toPath(), f.toPath());
			}
			catch (Exception e)
			{
				log.debug("OSRSCN: failed to migrate missing.tsv", e); // keep both; nothing is lost
			}
		}
		file = f;
		return f;
	}

	/** Flush queued rows to disk now, so a submission that reads the file right after sees everything. */
	public void flushPending()
	{
		flush();
	}

	private void ensureLoaded()
	{
		if (!loaded.compareAndSet(false, true))
		{
			return;
		}
		File f = missingFile();
		if (!f.exists())
		{
			return;
		}
		try (BufferedReader r = Files.newBufferedReader(f.toPath(), StandardCharsets.UTF_8))
		{
			String line;
			boolean first = true;
			while ((line = r.readLine()) != null)
			{
				if (line.startsWith("#"))
				{
					continue; // session markers
				}
				int tab = line.indexOf('\t');
				String en = tab == -1 ? line : line.substring(0, tab);
				if (first)
				{
					first = false;
					if (en.equalsIgnoreCase("english"))
					{
						continue; // skip header
					}
				}
				if (!en.isEmpty())
				{
					seen.add(dedupKey(en));
				}
			}
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: failed to read missing file", e);
		}
	}

	private void ensureFlusher()
	{
		if (flusherStarted.compareAndSet(false, true))
		{
			// RuneLite's shared executor; plugin-hub disallows plugin-created threads / sleep / interrupt.
			flusherFuture = executor.scheduleWithFixedDelay(this::flush, 5, 5, TimeUnit.SECONDS);
		}
	}

	/** Final flush and cancel the periodic flusher (plugin shutdown); a re-enable restarts it lazily. */
	public void stop()
	{
		ScheduledFuture<?> f = flusherFuture;
		if (f != null)
		{
			f.cancel(false);
			flusherFuture = null;
		}
		flush();
		flusherStarted.set(false);
	}

	private synchronized void flush()
	{
		if (pending.isEmpty())
		{
			return;
		}
		File f = missingFile();
		//noinspection ResultOfMethodCallIgnored
		f.getParentFile().mkdirs();
		boolean newFile = !f.exists();
		try (FileWriter w = new FileWriter(f, StandardCharsets.UTF_8, true))
		{
			if (newFile)
			{
				w.write("english\ttranslation\tcategory\tsub_category\tsource\n");
			}
			if (sessionMarked.compareAndSet(false, true))
			{
				// one marker per session, so it's obvious when each block of rows was collected;
				// every consumer (loader below / uploader / relay / clean_inbox) skips '#' lines
				w.write("# session " + new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm")
						.format(new java.util.Date()) + "\n");
			}
			String line;
			while ((line = pending.poll()) != null)
			{
				w.write(line + "\n");
			}
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: failed to append missing file", e);
		}
	}
}

package com.osrscn.translate;

import com.google.gson.Gson;
import com.osrscn.OsrscnConfig;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Voluntary uploader for the collected missing file. Off unless BOTH
 * {@link OsrscnConfig#collectMissing()} and {@link OsrscnConfig#uploadMissing()} are on (the latter
 * pops an explicit consent dialog when enabled). Periodically POSTs only the rows added since the
 * last successful upload - game English plus the anonymous install id, never chat or account data -
 * to the maintainer's relay, which files them into the private data repo's inbox.
 *
 * <p>A watermark file ({@code .upload_state}: {@code <missing file name>\t<lines sent>}) makes
 * uploads incremental and idempotent; on any failure it simply retries next period.
 */
@Slf4j
@Singleton
public class MissingUploader
{
	// Cloudflare Worker endpoint (see tools/reflow_worker/DEPLOY.md). Empty = feature dormant:
	// nothing is scheduled and the config toggle has no effect.
	static final String UPLOAD_URL = "https://osrscn-reflow.0shrug.workers.dev";

	private static final MediaType JSON = MediaType.parse("application/json");
	private static final int MAX_ROWS_PER_POST = 400;
	private static final long INITIAL_DELAY_S = 60;
	private static final long PERIOD_S = 30 * 60;

	@Inject
	private OsrscnConfig config;
	@Inject
	private MissingCollector collector;
	@Inject
	private ScheduledExecutorService executor;
	@Inject
	private OkHttpClient httpClient;
	@Inject
	private Gson gson;

	private volatile ScheduledFuture<?> future;
	private final AtomicBoolean inFlight = new AtomicBoolean();

	/** Schedule the periodic check (plugin startUp). No-op while no endpoint is configured. */
	public void start()
	{
		if (UPLOAD_URL.isEmpty() || future != null)
		{
			return;
		}
		future = executor.scheduleWithFixedDelay(this::tick, INITIAL_DELAY_S, PERIOD_S, TimeUnit.SECONDS);
	}

	// Told how many rows just went out, so the plugin can say so in chat. Data leaving the machine
	// should be visible to the person it belongs to, and a silent button looks broken besides.
	private volatile java.util.function.IntConsumer uploadListener;

	public void setUploadListener(java.util.function.IntConsumer listener)
	{
		uploadListener = listener;
	}

	/** Rows past the upload watermark (display only - the batch builder re-reads on upload). */
	public int pendingRows()
	{
		try
		{
			File f = collector.missingFile();
			if (!f.exists())
			{
				return 0;
			}
			int lines = Files.readAllLines(f.toPath(), StandardCharsets.UTF_8).size();
			int sent = readWatermark(f.getName());
			// No watermark yet: the first tick starts it at the current size (the backlog is never
			// sent), so nothing is actually pending.
			return sent == 0 ? 0 : Math.max(0, lines - sent);
		}
		catch (Exception e)
		{
			return 0;
		}
	}

	/** Manual trigger from the side panel (quick test / impatient contributors). */
	public void uploadNow()
	{
		if (!UPLOAD_URL.isEmpty())
		{
			executor.execute(this::tick);
		}
	}

	/** Cancel the periodic check (plugin shutDown). */
	public void stop()
	{
		ScheduledFuture<?> f = future;
		if (f != null)
		{
			f.cancel(false);
			future = null;
		}
	}

	private void tick()
	{
		if (!config.collectMissing() || !config.uploadMissing() || !inFlight.compareAndSet(false, true))
		{
			return;
		}
		boolean handedOff = false;
		try
		{
			handedOff = uploadNextBatch();
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: missing upload failed", e);
		}
		finally
		{
			if (!handedOff)
			{
				inFlight.set(false); // async callback owns the flag once the call is enqueued
			}
		}
	}

	/** @return true if an async call was enqueued (the callback releases {@link #inFlight}) */
	private boolean uploadNextBatch() throws IOException
	{
		collector.flushPending();
		File f = collector.missingFile();
		if (!f.exists())
		{
			return false;
		}
		List<String> lines = Files.readAllLines(f.toPath(), StandardCharsets.UTF_8);
		int sent = readWatermark(f.getName()); // line 0 is the header, never sent
		if (sent == 0)
		{
			// First upload for this file: start the watermark at the current size. The backlog was
			// collected before the client-side quality gates existed and must never be replayed.
			writeWatermark(f.getName(), Math.max(1, lines.size()));
			return false;
		}
		if (lines.size() <= sent)
		{
			return false;
		}
		int end = Math.min(lines.size(), sent + MAX_ROWS_PER_POST);
		List<String> batch = new ArrayList<>();
		for (int i = sent; i < end; i++)
		{
			String l = lines.get(i);
			if (!l.trim().isEmpty() && !l.startsWith("#"))
			{
				batch.add(l); // '#' session markers stay local
			}
		}
		if (batch.isEmpty())
		{
			writeWatermark(f.getName(), end);
			return false;
		}
		Map<String, Object> body = new HashMap<>();
		body.put("v", 1);
		body.put("id", collector.installId());
		body.put("rows", batch);
		Request req = new Request.Builder()
				.url(UPLOAD_URL)
				.post(RequestBody.create(JSON, gson.toJson(body)))
				.build();
		final int newWatermark = end;
		final int rowsSent = batch.size(); // '#' markers advance the watermark but are never sent
		final String fileName = f.getName();
		httpClient.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("OSRSCN: missing upload failed", e);
				inFlight.set(false);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful())
					{
						writeWatermark(fileName, newWatermark);
						log.debug("OSRSCN: uploaded missing rows up to line {}", newWatermark);
						java.util.function.IntConsumer l = uploadListener;
						if (l != null)
						{
							l.accept(rowsSent);
						}
					}
				}
				finally
				{
					inFlight.set(false);
				}
			}
		});
		return true;
	}

	private File stateFile()
	{
		return new File(collector.missingFile().getParentFile(), ".upload_state");
	}

	/** Lines already sent for this missing file; 0 when none / the file name changed (new id). */
	private int readWatermark(String fileName)
	{
		try
		{
			File s = stateFile();
			if (!s.exists())
			{
				return 0;
			}
			String[] c = new String(Files.readAllBytes(s.toPath()), StandardCharsets.UTF_8).trim().split("\t");
			if (c.length == 2 && c[0].equals(fileName))
			{
				return Integer.parseInt(c[1]);
			}
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: failed to read .upload_state", e);
		}
		return 0;
	}

	private synchronized void writeWatermark(String fileName, int lines)
	{
		try
		{
			Files.write(stateFile().toPath(), (fileName + "\t" + lines).getBytes(StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: failed to write .upload_state", e);
		}
	}
}

package com.osrscn.translate;

import java.io.BufferedReader;
import java.io.File;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.regex.Pattern;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * In-memory English -> Simplified Chinese lookup, loaded from the community OSRS transcript TSVs.
 *
 * <p>Each TSV is a translation domain (dialogue, names, menu actions, interface text, examine,
 * etc.) and is kept in its own map so callers can look up in the right context. Files are read
 * from the local cache ({@code ~/.runelite/osrscn/zh/}); a missing file is downloaded once from
 * the configured base URL and cached.
 */
@Slf4j
@Singleton
public class TranslationStore
{
	/** Translation domains, each backed by one TSV file. */
	public enum Category
	{
		DIALOGUE("transcript_zh_dialogue.tsv"),
		DIALOGUE_EXPERIMENTAL("transcript_zh_dialogue_experimental.tsv"),
		NAME("transcript_zh_name.tsv"),
		ACTIONS("transcript_zh_actions.tsv"),
		INVENTORY_ACTIONS("transcript_zh_inventoryActions.tsv"),
		INTERFACE("transcript_zh_interface.tsv"),
		EXAMINE("transcript_zh_examine.tsv"),
		GAME_TEXT("transcript_zh_gameText.tsv"),
		LVL_UP("transcript_zh_lvl_up_msg.tsv"),
		// skill-guide prose/titles (group 860), regenerated wholesale from the cache-dump pipeline
		SKILL_GUIDE("transcript_zh_skillguide.tsv"),
		SUPPLEMENT("transcript_zh_supplement.tsv");

		final String file;

		Category(String file)
		{
			this.file = file;
		}
	}

	// Order tried by lookupAny() when the caller has no specific context. Every category is listed so a
	// translation never gets lost just because it was filed under one this path didn't try; the dialogue
	// tables stay last (experimental dead last) so curated tables win.
	private static final Category[] ANY_ORDER = {
			Category.DIALOGUE, Category.GAME_TEXT, Category.LVL_UP, Category.INTERFACE, Category.NAME,
			Category.EXAMINE, Category.SKILL_GUIDE, Category.SUPPLEMENT, Category.ACTIONS,
			Category.INVENTORY_ACTIONS, Category.DIALOGUE_EXPERIMENTAL,
	};

	// Categories that also get a case-insensitive index. The huge dialogue tables are
	// excluded to save memory - dialogue is matched verbatim.
	private static final java.util.EnumSet<Category> LOOSE = java.util.EnumSet.of(
			Category.NAME, Category.INTERFACE, Category.GAME_TEXT, Category.EXAMINE,
			Category.SKILL_GUIDE, Category.SUPPLEMENT, Category.LVL_UP, Category.ACTIONS,
			Category.INVENTORY_ACTIONS);

	private final File cacheDir = new File(RuneLite.RUNELITE_DIR, "osrscn/zh");
	private final Map<Category, Map<String, String>> maps = new EnumMap<>(Category.class);
	private final Map<Category, Map<String, String>> lowerMaps = new EnumMap<>(Category.class); // case-insensitive index
	private volatile boolean loaded;
	private volatile String baseUrl; // e.g. https://raw.githubusercontent.com/<user>/<repo>/<branch>/public/zh/

	@Inject
	private OkHttpClient httpClient;
	@Inject
	private java.util.concurrent.ScheduledExecutorService executor;

	public TranslationStore()
	{
		for (Category c : Category.values())
		{
			maps.put(c, new ConcurrentHashMap<>());
		}
		for (Category c : LOOSE)
		{
			lowerMaps.put(c, new ConcurrentHashMap<>());
		}
	}

	public void setBaseUrl(String url)
	{
		this.baseUrl = (url == null || url.trim().isEmpty()) ? null : url.trim();
	}

	public boolean isLoaded()
	{
		return loaded;
	}

	public int size()
	{
		int n = 0;
		for (Map<String, String> m : maps.values())
		{
			n += m.size();
		}
		return n;
	}

	/**
	 * Distinct CJK codepoints across every loaded Chinese value, for glyph pre-warm (so a character's
	 * first appearance does not flash English while its sprite uploads). Call once {@link #isLoaded()};
	 * returns an empty set if nothing is loaded yet. Uses the same 0x2E80 threshold as the glyph renderer.
	 */
	public java.util.Set<Integer> chineseCodepoints()
	{
		java.util.Set<Integer> out = new java.util.HashSet<>(8192);
		for (Map<String, String> m : maps.values())
		{
			for (String v : m.values())
			{
				if (v == null)
				{
					continue;
				}
				int i = 0;
				int len = v.length();
				while (i < len)
				{
					int cp = v.codePointAt(i);
					if (cp >= 0x2E80)
					{
						out.add(cp);
					}
					i += Character.charCount(cp);
				}
			}
		}
		return out;
	}

	/** Loads the store on the client's background executor. Safe to call once at start-up. */
	public void loadAsync()
	{
		executor.execute(this::load);
	}

	private void load()
	{
		try
		{
			//noinspection ResultOfMethodCallIgnored
			cacheDir.mkdirs();
			// Refresh stale tables against the published hash list; without this, existing
			// installs would keep their first-download copies forever. Any failure keeps the
			// cached copy - the check must never block startup.
			Map<String, String> remote = fetchRemoteHashes();
			for (Category c : Category.values())
			{
				File f = new File(cacheDir, c.file);
				if (f.exists() && remote != null)
				{
					String want = remote.get(c.file);
					if (want != null && !want.equalsIgnoreCase(sha256(f)))
					{
						try
						{
							download(baseUrl + c.file, f);
						}
						catch (Exception e)
						{
							log.debug("OSRSCN: refresh failed for {}, keeping cached copy: {}", c.file, e.getMessage());
						}
					}
				}
				if (!f.exists() && baseUrl != null)
				{
					try
					{
						download(baseUrl + c.file, f);
					}
					catch (Exception e)
					{
						log.debug("OSRSCN: optional file not downloaded {}: {}", c.file, e.getMessage());
					}
				}
				if (f.exists())
				{
					parse(f, c);
				}
			}
			buildPlaceholderIndex();
			loaded = true;
			log.info("OSRSCN translations loaded: {} entries", size());
		}
		catch (Exception e)
		{
			log.error("OSRSCN: failed to load translations", e);
		}
	}

	private void parse(File f, Category c) throws Exception
	{
		Map<String, String> into = maps.get(c);
		Map<String, String> lower = lowerMaps.get(c); // null for non-loose categories
		try (BufferedReader r = Files.newBufferedReader(f.toPath(), StandardCharsets.UTF_8))
		{
			String line = r.readLine(); // header
			while ((line = r.readLine()) != null)
			{
				int t1 = line.indexOf('\t');
				if (t1 <= 0)
				{
					continue;
				}
				int t2 = line.indexOf('\t', t1 + 1);
				String en = line.substring(0, t1);
				String zh = (t2 == -1) ? line.substring(t1 + 1) : line.substring(t1 + 1, t2);
				if (zh.isEmpty())
				{
					continue;
				}
				String key = normalize(en);
				into.putIfAbsent(key, zh);
				if (lower != null)
				{
					lower.putIfAbsent(key.toLowerCase(), zh);
				}
			}
		}
	}

	/** Published table hashes ({@code name|sha256} per line), or null when unavailable/offline. */
	private Map<String, String> fetchRemoteHashes()
	{
		if (baseUrl == null)
		{
			return null;
		}
		try
		{
			Request request = new Request.Builder().url(baseUrl + "hashList_zh.txt").build();
			try (Response response = http(5).newCall(request).execute())
			{
				if (!response.isSuccessful() || response.body() == null)
				{
					return null;
				}
				Map<String, String> out = new java.util.HashMap<>();
				for (String line : response.body().string().split("\n"))
				{
					int p = line.indexOf('|');
					if (p > 0)
					{
						out.put(line.substring(0, p).trim(), line.substring(p + 1).trim());
					}
				}
				return out;
			}
		}
		catch (Exception e)
		{
			log.debug("OSRSCN: hash list not available: {}", e.getMessage());
			return null;
		}
	}

	private static String sha256(File f)
	{
		try (InputStream in = Files.newInputStream(f.toPath()))
		{
			java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
			byte[] buf = new byte[8192];
			int n;
			while ((n = in.read(buf)) > 0)
			{
				md.update(buf, 0, n);
			}
			StringBuilder sb = new StringBuilder();
			for (byte b : md.digest())
			{
				sb.append(Character.forDigit((b >> 4) & 0xF, 16)).append(Character.forDigit(b & 0xF, 16));
			}
			return sb.toString();
		}
		catch (Exception e)
		{
			return "";
		}
	}

	/**
	 * The injected client has no call timeout, and these blocking calls run on the client's shared
	 * scheduled executor - a hung connection would stall every plugin's periodic tasks with it.
	 * The hash list is a tiny probe (5s); table downloads reach ~18 MB and need slow-network
	 * headroom (60s still bounds a hang, but covers ~2.5 Mbps links).
	 */
	private OkHttpClient http(int callTimeoutSeconds)
	{
		return httpClient.newBuilder().callTimeout(callTimeoutSeconds, java.util.concurrent.TimeUnit.SECONDS).build();
	}

	private void download(String url, File dest) throws Exception
	{
		log.info("OSRSCN: downloading {}", url);
		Request request = new Request.Builder().url(url).build();
		try (Response response = http(60).newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				throw new java.io.IOException("HTTP " + response.code());
			}
			// Download to a temp file and swap it in atomically, so an interrupted download can
			// never leave a truncated table that the exists() check would treat as complete.
			Path tmp = dest.toPath().resolveSibling(dest.getName() + ".tmp");
			try
			{
				try (InputStream in = response.body().byteStream())
				{
					Files.copy(in, tmp, StandardCopyOption.REPLACE_EXISTING);
				}
				try
				{
					Files.move(tmp, dest.toPath(), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
				}
				catch (java.nio.file.AtomicMoveNotSupportedException e)
				{
					Files.move(tmp, dest.toPath(), StandardCopyOption.REPLACE_EXISTING);
				}
			}
			finally
			{
				Files.deleteIfExists(tmp);
			}
		}
	}

	/** @return the translation for {@code english} in {@code category}, or {@code null}. */
	public String lookup(Category category, String english)
	{
		if (english == null || english.isEmpty())
		{
			return null;
		}
		return maps.get(category).get(normalize(english));
	}

	/** Lookup with an already-normalized key (avoids re-normalizing across many categories). */
	public String lookupNormalized(Category category, String normalizedKey)
	{
		return maps.get(category).get(normalizedKey);
	}

	// Tables that carry long reconstructed prose, where drift healing is safe and useful.
	private static final Category[] DRIFT_CATEGORIES = {
			Category.SUPPLEMENT, Category.SKILL_GUIDE, Category.INTERFACE,
	};

	/**
	 * Drift heal for reconstructed prose: after a scroll/tab re-layout the word-run assembly can lose
	 * its first word(s) ("Your Strength level..." -> "Strength level..."), so an exact key that hit on
	 * the first visit misses forever after. Serve any known key that ends with the query and only has
	 * a few extra leading characters. Long queries only - short labels must stay exact-match. The
	 * linear scan is fine: this runs only on whole-run misses, which are rare and cooldown-paced.
	 */
	public String lookupProseDrift(String english)
	{
		if (english == null || english.length() < 40)
		{
			return null;
		}
		String q = normalize(english);
		for (Category c : DRIFT_CATEGORIES)
		{
			for (Map.Entry<String, String> e : maps.get(c).entrySet())
			{
				String k = e.getKey();
				int extra = k.length() - q.length();
				if (extra > 0 && extra <= 16 && k.endsWith(q))
				{
					return e.getValue();
				}
			}
		}
		return null;
	}

	// Rows keyed on a name placeholder ("Greetings, Thane [Fremennik name].") can never match live
	// text exactly: the client only knows the account name, not the second name the game hands the
	// player (Fremennik Trials). Each such key is split on its placeholder once at load, so a miss
	// can match around the on-screen name and backfill it. Single-occurrence keys with at least
	// 8 chars of fixed context only, so a near-bare-name row can never swallow an ordinary short line.
	private static final String[] NAME_PLACEHOLDERS = {"[Fremennik name]", "[player name]"};
	// OSRS display names: up to 12 chars of letters/digits/space/_/-, at least one letter.
	private static final Pattern PLACEHOLDER_NAME = Pattern.compile("(?=[0-9 _-]*[A-Za-z])[A-Za-z0-9 _-]{1,12}");

	private static final class PlaceholderRow
	{
		final String prefix;
		final String suffix;
		final String placeholder;
		final String zh;

		PlaceholderRow(String prefix, String suffix, String placeholder, String zh)
		{
			this.prefix = prefix;
			this.suffix = suffix;
			this.placeholder = placeholder;
			this.zh = zh;
		}
	}

	private volatile List<PlaceholderRow> placeholderRows = java.util.Collections.emptyList();

	// Rebuilt whenever the tables are (re)parsed - never per query, so there is no negative cache to
	// go stale (the render()-null-is-ambiguous trap does not apply here).
	private void buildPlaceholderIndex()
	{
		List<PlaceholderRow> rows = new ArrayList<>();
		for (Category c : ANY_ORDER) // priority order, so a curated-table row wins the scan
		{
			for (Map.Entry<String, String> e : maps.get(c).entrySet())
			{
				String k = e.getKey();
				for (String p : NAME_PLACEHOLDERS)
				{
					int i = k.indexOf(p);
					if (i >= 0 && k.indexOf(p, i + 1) < 0 && k.length() - p.length() >= 8)
					{
						rows.add(new PlaceholderRow(k.substring(0, i), k.substring(i + p.length()), p, e.getValue()));
					}
				}
			}
		}
		placeholderRows = rows;
	}

	/**
	 * Match {@code english} against the placeholder-keyed rows, backfilling the on-screen name into
	 * the translation (values keep their placeholder verbatim, so a plain replace restores the name).
	 * Returns null when no row fits. A hit here is a real table hit: the caller must treat it as
	 * final - recording it or sending it to the AI would leak the name it carries off the machine.
	 * The linear scan (~4k rows) only runs after every exact lookup missed, with a cheap length
	 * pre-filter, so it stays off the per-frame hot path.
	 */
	public String lookupPlaceholderTolerant(String english)
	{
		List<PlaceholderRow> rows = placeholderRows;
		if (english == null || english.isEmpty() || rows.isEmpty())
		{
			return null;
		}
		String q = normalize(english);
		for (PlaceholderRow r : rows)
		{
			int nameLen = q.length() - r.prefix.length() - r.suffix.length();
			if (nameLen < 1 || nameLen > 12 || !q.startsWith(r.prefix) || !q.endsWith(r.suffix))
			{
				continue;
			}
			String name = q.substring(r.prefix.length(), r.prefix.length() + nameLen);
			if (PLACEHOLDER_NAME.matcher(name).matches())
			{
				return r.zh.replace(r.placeholder, name);
			}
		}
		return null;
	}

	/** Case-insensitive lookup; {@code lowerKey} must be an already-normalized, lower-cased key.
	 *  Only the {@link #LOOSE} categories have a lower-cased index (others return null). */
	public String lookupLower(Category category, String lowerKey)
	{
		Map<String, String> m = lowerMaps.get(category);
		return m == null ? null : m.get(lowerKey);
	}

	/** @return the translation from any domain (priority order), or {@code null}. */
	public String lookupAny(String english)
	{
		if (english == null || english.isEmpty())
		{
			return null;
		}
		String key = normalize(english);
		for (Category c : ANY_ORDER)
		{
			String zh = maps.get(c).get(key);
			if (zh != null)
			{
				return zh;
			}
		}
		String lower = key.toLowerCase();
		for (Category c : ANY_ORDER)
		{
			String zh = lookupLower(c, lower);
			if (zh != null)
			{
				return zh;
			}
		}
		return null;
	}

	// Precompiled: normalize() sits on the per-frame widget scan path, so its regexes must not be
	// recompiled on every call.
	private static final Pattern BR_TAG = Pattern.compile("(?i)<br\\s*/?>");
	private static final Pattern STR_TAG = Pattern.compile("(?i)</?str>");
	private static final Pattern ODD_SPACES = Pattern.compile("[\\u00A0\\u2000-\\u200B\\u202F\\u205F\\u3000\\uFEFF]");
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	/** Canonicalize so game text and TSV keys compare equal. {@code <br>} becomes a space; {@code <str>}
	 *  is dropped so struck-through diary/quest lines match the plain key. Typographic variants are folded
	 *  to their ASCII form (curly quotes -&gt; straight, en/em dashes -&gt; '-', ellipsis -&gt; '...').
	 *  The apostrophe is kept as a real character (so "you've" never collapses onto "youve"). Unusual
	 *  Unicode spaces (NBSP, full-width, thin, zero-width) that Java's {@code \s} does NOT match are
	 *  turned into a normal space before whitespace is collapsed. */
	public static String normalize(String s)
	{
		s = BR_TAG.matcher(s).replaceAll(" ");
		s = STR_TAG.matcher(s).replaceAll("");
		s = s.replace((char) 0x2018, '\'').replace((char) 0x2019, '\'').replace((char) 0x201B, '\'')
				.replace((char) 0x00B4, '\'').replace('`', '\'')
				.replace((char) 0x201C, '"').replace((char) 0x201D, '"').replace((char) 0x201E, '"')
				.replace((char) 0x2013, '-').replace((char) 0x2014, '-').replace((char) 0x2012, '-').replace((char) 0x2015, '-')
				.replace(String.valueOf((char) 0x2026), "...");
		s = ODD_SPACES.matcher(s).replaceAll(" ");
		return WHITESPACE.matcher(s).replaceAll(" ").trim();
	}

	/** One English/Chinese name pair, for the panel's search results. */
	public static final class Match
	{
		public final String en;
		public final String zh;

		Match(String en, String zh)
		{
			this.en = en;
			this.zh = zh;
		}
	}

	/**
	 * Substring search over entity names (items / NPCs / objects), matching either the English or the
	 * Chinese side, for the side panel's lookup tool. Case-insensitive on the English side.
	 */
	public List<Match> searchNames(String query, int limit)
	{
		List<Match> out = new ArrayList<>();
		if (query == null)
		{
			return out;
		}
		String raw = query.trim();
		if (raw.isEmpty())
		{
			return out;
		}
		String lower = raw.toLowerCase();
		for (Map.Entry<String, String> e : maps.get(Category.NAME).entrySet())
		{
			String en = e.getKey();
			String zh = e.getValue();
			if (en.toLowerCase().contains(lower) || zh.contains(raw))
			{
				out.add(new Match(en, zh));
				if (out.size() >= limit)
				{
					break;
				}
			}
		}
		return out;
	}
}

package com.osrscn.translate;

import com.osrscn.glyph.GlyphService;
import com.osrscn.text.Tags;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;

/**
 * Translation facade: lookup table first, AI fallback second, then render to char-image tags.
 * Returns {@code null} when no translation is available yet, and also when the table says this text
 * stays English (see {@link #keepEnglish}); either way the caller keeps the original text untouched.
 *
 * <p>Call on the client thread (reads the local player name).
 */
@Singleton
public class Translator
{
	private static final String PLAYER_NAME = "[player name]";
	private static final int CJK_MIN = 0x2E80; // same cut-off the glyph renderer uses for "needs a char-image"
	private static final Pattern NUMBER = Pattern.compile("\\d+(?:[.,]\\d+)*");
	private static final Pattern WORDY = Pattern.compile("[A-Za-z]{3,}"); // has a real word worth AI-translating
	private static final Pattern HAS_LETTER = Pattern.compile("[A-Za-z]");
	private static final Pattern TOP_THREE_WERE = Pattern.compile("(?i)(top three .+? were )(.+?)([.!?])");
	private static final Pattern TOP_CRAB_WAS = Pattern.compile("(?i)the top crab crusher was (.+?)([.!?])");
	private static final Pattern MEMBERS_LINE = Pattern.compile("(?i)^Members:\\s*(.+)$");
	// GE transaction lines are parameterized by item: one hard row per item would never end, so the
	// frame is composed here and the item goes through the name table (17k entries) instead.
	private static final Pattern GE_TRADE_LINE = Pattern.compile(
			"(?i)^Grand Exchange: Finished (buying|selling) (<Num\\d+>) x (.+?)\\.?$");
	private static final Pattern GE_OFFER_LINE = Pattern.compile(
			"(?i)^(Buy|Sell): (<Num\\d+>) x (.+)$");
	// Offer labels in the exchange window: same deal, the item is the only variable part.
	private static final Pattern GE_DONE_LINE = Pattern.compile("(?i)^(Bought|Sold|Buying|Selling):\\s*(.+?)\\.?$");
	// Quest list entry. Both halves are already in the tables (every quest name, and the three states),
	// so composing it covers all ~200 quests instead of one collected row per quest per state.
	private static final Pattern QUEST_STATE_LINE = Pattern.compile(
			"^Quest: (.+?) \\((Not Started|In Progress|Completed)\\)$");
	// Quest-complete scroll / chat congratulation: the quest name is the only variable and every
	// quest name is already in the tables, so compose these instead of one row per quest.
	private static final Pattern QUEST_DONE_LINE = Pattern.compile("^You have completed (.+?)!$");
	private static final Pattern QUEST_DONE_CHAT = Pattern.compile("(?i)^Congratulations, you've completed a quest:\\s*(.+)$");
	// Reward-scroll XP line ("3,875 Crafting XP"): the skill is the only variable part.
	private static final Pattern SKILL_XP_LINE = Pattern.compile("^(<Num\\d+>) ([A-Za-z]+) XP$");
	// Level-up chat lines arrive as "<skillId>|Check the skill guide ...": the engine reads the
	// prefix to make "skill guide" clickable, so it must survive translation untouched.
	private static final Pattern CHAT_LINK_PREFIX = Pattern.compile("^(\\d{1,3}\\|)(.+)$", Pattern.DOTALL);
	// Combat-achievement "Monster: <name>" line: the prefix is fixed and the name lives in the name
	// table (incl. bosses), so compose "怪物：" + looked-up name instead of needing a whole-line entry.
	private static final Pattern MONSTER_LINE = Pattern.compile("(?i)^Monster:\\s*(.+)$");
	private static final Pattern REQUIRES_LINE = Pattern.compile("(?i)^Requires:\\s*(.+)$");
	// Examine "Price of <item>: GE average <Num0> HA value <Num1>" - the item lives in the name table, so
	// compose a consistent line from the looked-up name instead of needing a whole-line entry per item.
	private static final Pattern PRICE_LINE = Pattern.compile("(?i)^Price of (.+?):\\s*(.+)$");
	private static final Pattern PRICE_QTY = Pattern.compile("(?i)^(<Num\\d+>)\\s*x\\s*(.+)$");
	private static final Pattern GE_AVERAGE = Pattern.compile("(?i)GE average\\s*(<Num\\d+>)");
	private static final Pattern HA_VALUE = Pattern.compile("(?i)HA value\\s*(<Num\\d+>)");
	private static final Pattern PRICE_EACH = Pattern.compile("(?i)\\((<Num\\d+>)\\s*ea\\)");
	private static final Pattern LEVEL_REQUIREMENT = Pattern.compile(
			"(?i)^(<colNum\\d+>)?\\s*Level\\s+((?:<Num\\d+>)|\\d+(?:[.,]\\d+)*)\\s+(.+?)(</col>)?$");
	private static final Pattern PLAYER_NAME_CHARS = Pattern.compile("[A-Za-z0-9 _-]+");

	@Inject
	private Client client;
	@Inject
	private TranslationStore store;
	@Inject
	private AiTranslator ai;
	@Inject
	private GlyphService glyph;
	@Inject
	private MissingCollector missing;

	// Nearby-player names, compiled into one alternation and rebuilt at most once per game tick. Built
	// and read on the client thread only; published as an immutable snapshot so a stray read from
	// anywhere else still sees a matching tick/pattern pair.
	private volatile NearbyNames nearby = NearbyNames.EMPTY;

	/**
	 * @param english  plain English source text (tags already stripped by the caller)
	 * @param colorRgb colour to render the Chinese glyphs in
	 * @return rendered Chinese (char-image tags), or null if not translated yet
	 */
	public String translate(String english, int colorRgb, int maxChars)
	{
		String zh = plain(english);
		if (zh == null)
		{
			return null;
		}
		return render(zh, colorRgb, maxChars, glyph.uiSize());
	}

	/**
	 * True when a lookup result carries no CJK, i.e. the data deliberately keeps this text in English:
	 * fairy-ring dial letters ("A" -&gt; "A"), "PvP", ":-(", orc speech ("Kl-Kra!"), untranslated proper
	 * nouns. Such a row is a real table hit, never a miss - it must not reach the AI or the missing
	 * collector - but there is nothing for us to draw, so the surface is told "nothing to do" and leaves
	 * the text (and the native bitmap font that draws it best) alone.
	 *
	 * <p>Tested on the value rather than {@code zh.equals(en)} because the harm comes from taking a widget
	 * over, not from the two columns matching: near-identity rows ("Bosses" -&gt; "Boss") and accented-Latin
	 * flavour lines have nothing to render either. Anything with real Chinese in it fails this test and
	 * takes the normal path.
	 */
	private static boolean keepEnglish(String zh)
	{
		int i = 0;
		int len = zh.length();
		while (i < len)
		{
			int cp = zh.codePointAt(i);
			if (cp >= CJK_MIN)
			{
				return false;
			}
			i += Character.charCount(cp);
		}
		return true;
	}

	/** Render to char-image tags, or null when there is nothing to render (see {@link #keepEnglish}). */
	private String render(String zh, int colorRgb, int maxChars, int size)
	{
		return keepEnglish(zh) ? null : glyph.toImgTags(zh, colorRgb, maxChars, size);
	}

	/**
	 * Plain-text translation (lookup table then AI), without rendering to char-images. For Swing UI
	 * (the side panel) which draws with a real CJK font. Returns null if not translated yet.
	 */
	public String plain(String english)
	{
		return plainCore(english, null, null, null, false);
	}

	/**
	 * Like {@link #plain} but, on a table miss, records the line to {@link MissingCollector} tagged with
	 * the given transcript columns (category / NPC / speaker) so the collected file lines up with the data
	 * tables. Used by the dialogue handler, which knows the NPC and speaker.
	 */
	public String plainCollect(String english, String category, String subCategory, String source)
	{
		return plainCore(english, category, subCategory, source, true);
	}

	private String plainCore(String english, String category, String subCategory, String source, boolean collect)
	{
		if (english == null || english.trim().isEmpty())
		{
			return null;
		}
		String zh = tableHit(english);
		if (zh != null)
		{
			return keepEnglish(zh) ? null : zh;
		}
		// Rows keyed on a name placeholder ("[Fremennik name]") can never match exactly: the client only
		// knows the account name, not the second name the game hands the player. A tolerant hit backfills
		// the on-screen name and is final - recording or AI-translating it would leak that name off the
		// machine (missing.tsv / the AI disk cache).
		zh = store.lookupPlaceholderTolerant(english);
		if (zh != null)
		{
			return keepEnglish(zh) ? null : zh;
		}
		if (collect)
		{
			String name = playerName();
			missing.record(name != null ? english.replace(name, PLAYER_NAME) : english, category, subCategory, source);
		}
		return aiTranslate(english, true);
	}

	/**
	 * Name-masked table hit for {@code english}, or null on a genuine miss. A hit is final either way:
	 * an English-only value means "checked, keep English", so it must not fall through to the collector
	 * or the AI (which would mistranslate it). The value is returned raw - the caller applies
	 * {@link #keepEnglish} itself, so it can tell "hit but nothing to draw" from a miss.
	 */
	private String tableHit(String english)
	{
		String name = playerName();
		if (name != null)
		{
			String zh = store.lookupAny(english.replace(name, PLAYER_NAME));
			if (zh != null)
			{
				return keepEnglish(zh) ? zh : zh.replace(PLAYER_NAME, name);
			}
		}
		return store.lookupAny(english);
	}

	/**
	 * Colour-aware dialogue translation. A line with an inline {@code <col=..>} segment (e.g. the red
	 * "Hardcore Group Ironmen" in a tutor line) keeps its colours by translating the {@code <colNumN>}
	 * templated form: coloured transcript entries are stored that way, and the AI is told to preserve
	 * tags, so the placeholders survive and {@link Tags#restoreColors} paints each segment. Safety: an
	 * uncoloured line takes the exact plain path unchanged; if the model drops or reorders the
	 * placeholders (count mismatch) we strip them and render single-colour, so a coloured line never
	 * comes out worse than today. Returns {@code null} while the AI is still in flight (caller retries).
	 */
	public String plainColored(String text, String category, String subCategory, String source)
	{
		if (text == null || text.trim().isEmpty())
		{
			return null;
		}
		List<String> colors = Tags.colorTags(text);
		if (colors.isEmpty())
		{
			return plainCollect(Tags.stripTags(text), category, subCategory, source);
		}
		// The tables often hold only the plain form of a coloured line, so a <colNumN> miss retries with
		// colours stripped before anything is recorded or sent to the AI; the placeholder-count check
		// below then renders such a hit single-colour, which still beats leaving the line English.
		String templated = Tags.placeholdColors(text);
		String zh = tableHit(templated);
		if (zh == null)
		{
			zh = tableHit(Tags.stripTags(text));
		}
		if (zh != null)
		{
			if (keepEnglish(zh))
			{
				return null;
			}
		}
		else
		{
			zh = plainCore(templated, category, subCategory, source, true);
			if (zh == null)
			{
				return null;
			}
		}
		return Tags.placeholderCount(zh) == colors.size()
				? Tags.restoreColors(zh, colors)
				: Tags.stripColorPlaceholders(zh);
	}

	/**
	 * Plain-text translation with no client access (no player-name substitution), safe to call from
	 * the Swing thread - used by the side panel's manual translate box. English-only rows are returned
	 * verbatim rather than suppressed: the panel draws with a real font, so showing what the table holds
	 * is the useful answer there.
	 */
	public String plainNoPlayer(String english)
	{
		if (english == null || english.trim().isEmpty())
		{
			return null;
		}
		return lookupOrAi(english, false);
	}

	/** Lookup table then AI fallback for an already player-name-substituted query. */
	private String lookupOrAi(String query, boolean protectPlayerNames)
	{
		String zh = store.lookupAny(query);
		if (zh == null)
		{
			zh = aiTranslate(query, protectPlayerNames);
		}
		return zh;
	}

	/**
	 * Lookup-only translation for menus/interface: no AI fallback (must be instant, no flicker).
	 * Tries {@code category} then falls back to NAME for entity-style text.
	 *
	 * @param maxChars wrap with {@code <br>} after this many visual chars (0 = no wrap)
	 * @param size     glyph point size ({@link GlyphService#uiSize()} / {@link GlyphService#smallSize()})
	 * @return rendered Chinese (char-image tags), or null if not in the table / not ready yet
	 */
	public String lookupRender(TranslationStore.Category category, String english, int colorRgb, int maxChars, int size)
	{
		if (english == null || english.trim().isEmpty())
		{
			return null;
		}
		String zh = store.lookup(category, english);
		if (zh == null && category != TranslationStore.Category.NAME)
		{
			zh = store.lookup(TranslationStore.Category.NAME, english);
		}
		if (zh == null)
		{
			return null;
		}
		return render(zh, colorRgb, maxChars, size);
	}

	// Menu options: action verbs first, then item actions and interface / name labels.
	private static final TranslationStore.Category[] MENU_ORDER = {
			TranslationStore.Category.ACTIONS, TranslationStore.Category.INVENTORY_ACTIONS,
			TranslationStore.Category.INTERFACE, TranslationStore.Category.NAME,
	};

	/**
	 * Render a whole menu option that embeds a coloured entity, e.g. {@code "Open <col=ff9040>Ardougne
	 * Journal</col>"} whose transcript key stores the colour as {@code <colNum0>}. Colours are templated to
	 * {@code <colNumN>}, looked up, then restored, so the rendered Chinese keeps the entity's colour. This is
	 * what {@code lookupRender}'s plain (colour-stripped) lookup misses. Lookup only, no AI.
	 *
	 * @return rendered char-image tags, or null if not in the tables.
	 */
	public String lookupRenderMenuOption(String option, int colorRgb, int size)
	{
		if (option == null || option.trim().isEmpty())
		{
			return null;
		}
		List<String> colors = Tags.colorTags(option);
		String zh = templateLookup(Tags.placeholdColors(option), MENU_ORDER);
		if (zh == null)
		{
			missing.record(collectKey(option), "interface", "", "");
			return null;
		}
		// render() may still return null (English-only row): that is a hit, so nothing is collected here.
		return render(Tags.restoreColors(zh, colors), colorRgb, 0, size);
	}

	// Tables tried, in order, for generic interface text (LVL_UP covers level-up chat messages).
	private static final TranslationStore.Category[] UI_ORDER = {
			TranslationStore.Category.INTERFACE, TranslationStore.Category.SKILL_GUIDE,
			TranslationStore.Category.GAME_TEXT, TranslationStore.Category.LVL_UP,
			TranslationStore.Category.NAME, TranslationStore.Category.EXAMINE,
			TranslationStore.Category.SUPPLEMENT,
	};

	// Chat/game messages often come from dialogue captures even when shown in the chatbox.
	private static final TranslationStore.Category[] CHAT_ORDER = {
			TranslationStore.Category.DIALOGUE, TranslationStore.Category.GAME_TEXT,
			TranslationStore.Category.LVL_UP, TranslationStore.Category.INTERFACE,
			TranslationStore.Category.NAME, TranslationStore.Category.EXAMINE,
			TranslationStore.Category.SUPPLEMENT, TranslationStore.Category.DIALOGUE_EXPERIMENTAL,
	};

	/**
	 * Lookup-only render for interface widgets, trying several tables (interface labels, game text,
	 * names, examine, manual) so pages with mixed content (quests, spell info, ...) get covered.
	 * Numbers are templated to {@code <Num0>}, ... so a
	 * single table entry (e.g. {@code "Level <Num0><br>Sharp Eye<br>Increases ... <Num1>%."}) matches
	 * any concrete instance; the real numbers are substituted back into the translation. Colour tags
	 * are dropped first so their hex digits are not mistaken for numbers.
	 *
	 * @param aiFallback for descriptive boxes (spell/prayer/...), translate table-missing lines with
	 *                   the AI backend (async, cached). Off for general UI to avoid translating junk.
	 */
	public String lookupRenderUi(String text, int colorRgb, int maxChars, int size, boolean aiFallback)
	{
		Rendered r = renderUi(text, colorRgb, maxChars, size, aiFallback);
		return r == null ? null : r.text;
	}

	/** Result of {@link #renderUi}: the rendered text plus whether every translatable line is done. */
	public static final class Rendered
	{
		public final String text;
		public final boolean complete; // false if a real (wordy) line is still untranslated (AI pending)

		Rendered(String text, boolean complete)
		{
			this.text = text;
			this.complete = complete;
		}
	}

	/**
	 * Like {@link #lookupRenderUi} but also reports completeness. A multi-line info box whose AI lines
	 * are still pending renders partially and returns {@code complete == false}; the caller should keep
	 * re-translating it until complete, otherwise the box stays half-English forever (the partial would
	 * be cached and never upgraded once the AI results land).
	 */
	public Rendered renderUi(String text, int colorRgb, int maxChars, int size, boolean aiFallback)
	{
		return renderUi(text, colorRgb, maxChars, size, aiFallback, true);
	}

	/**
	 * @param persist whether AI translations of table-missing lines are written to the on-disk cache.
	 *                Player chat passes {@code false} (slang rarely recurs; keep it memory-only).
	 */
	public Rendered renderUi(String text, int colorRgb, int maxChars, int size, boolean aiFallback, boolean persist)
	{
		return renderWithOrder(text, colorRgb, maxChars, size, aiFallback, persist, UI_ORDER, "interface");
	}

	public Rendered renderChat(String text, int colorRgb, int maxChars, int size, boolean aiFallback, boolean persist)
	{
		return renderChat(text, colorRgb, maxChars, size, aiFallback, persist, true, null);
	}

	/** Repaint chat from tables and AI cache without requests, persistence or missing collection. */
	public Rendered renderChatCached(String text, int colorRgb, int maxChars, int size)
	{
		return renderChat(text, colorRgb, maxChars, size, true, false, false, null);
	}

	/** Player-mode permit reaches each AI admission; table and cached rendering stay unchanged. */
	public Rendered renderChat(String text, int colorRgb, int maxChars, int size, boolean aiFallback,
			boolean persist, AiTranslator.RequestPermit permit)
	{
		return renderChat(text, colorRgb, maxChars, size, aiFallback, persist, true, permit);
	}

	private Rendered renderChat(String text, int colorRgb, int maxChars, int size, boolean aiFallback,
			boolean persist, boolean allowRequests, AiTranslator.RequestPermit permit)
	{
		// Game messages pass persist=true and are safe to collect; player chat passes persist=false
		// and must never be written to missing.tsv.
		Matcher link = text == null ? null : CHAT_LINK_PREFIX.matcher(text);
		if (link != null && link.matches())
		{
			Rendered r = renderWithOrder(link.group(2), colorRgb, maxChars, size, aiFallback, persist,
					CHAT_ORDER, persist ? "gameText" : null, allowRequests, permit);
			return r == null ? null : new Rendered(link.group(1) + r.text, r.complete);
		}
		return renderWithOrder(text, colorRgb, maxChars, size, aiFallback, persist, CHAT_ORDER, persist ? "gameText" : null, allowRequests, permit);
	}

	/**
	 * Like {@link #renderUi} but never writes missing rows and keeps AI results memory-only - for
	 * surfaces whose text is player-controlled (boat names, hiscores) or mid-reflow (reconstruct
	 * groups while the reflow toggle is off).
	 */
	public Rendered renderUiNoCollect(String text, int colorRgb, int maxChars, int size, boolean aiFallback)
	{
		return renderWithOrder(text, colorRgb, maxChars, size, aiFallback, false, UI_ORDER, null);
	}

	private Rendered renderWithOrder(String text, int colorRgb, int maxChars, int size, boolean aiFallback, boolean persist,
			TranslationStore.Category[] order, String collectSource)
	{
		return renderWithOrder(text, colorRgb, maxChars, size, aiFallback, persist, order, collectSource, true, null);
	}

	private Rendered renderWithOrder(String text, int colorRgb, int maxChars, int size, boolean aiFallback, boolean persist,
			TranslationStore.Category[] order, String collectSource, boolean allowRequests, AiTranslator.RequestPermit permit)
	{
		if (text == null || text.trim().isEmpty())
		{
			return null;
		}
		// Colours are looked up as <colNumN> placeholders (the data stores them that way) and restored to
		// real <col=..> tags afterwards, so the colour-aware glyph renderer can colour each segment.
		// First try the whole widget as one entry (multi-line info boxes like prayer/spell are combined).
		List<String> wholeColors = Tags.colorTags(text);
		String whole = lookupPeriodTolerant(Tags.placeholdColors(text), order);
		if (whole != null)
		{
			// A hit ends the walk even when render() declines it (English-only row): no per-line retry, no
			// collected row, no AI - the caller just keeps the text the client already drew.
			String img = render(Tags.restoreColors(whole, wholeColors), colorRgb, maxChars, size);
			return img == null ? null : new Rendered(img, true);
		}
		if (text.contains("<br>") || text.contains("<u") || text.contains("<str") || aiFallback)
		{
			// per-line: some widgets pack independent labels (e.g. chat tab "Game<br>On"); also lets the
			// AI fill individual lines a combined entry doesn't cover. Each line is placeheld/restored on
			// its own so colour indices match the data (which stores each entry from <colNum0>).
			String[] lines = text.split("<br>", -1);
			StringBuilder sb = new StringBuilder();
			boolean any = false;
			boolean all = true;
			for (int i = 0; i < lines.length; i++)
			{
				if (i > 0)
				{
					sb.append("<br>");
				}
				String line = lines[i];
				List<String> lineColors = Tags.colorTags(line);
				String lzh = lookupPeriodTolerant(Tags.placeholdColors(line), order);
				if (lzh == null)
				{
					// Styled link/quest lines (<u=..>Quest</u>) and struck items are stored plain in the
					// tables; strip styling, match the plain key, and recolour with the line's own colour.
					String plain = Tags.stripStyle(line);
					if (!plain.equals(line) && !plain.trim().isEmpty())
					{
						String pz = lookupPeriodTolerant(plain, order);
						if (pz != null)
						{
							// A single colour tag colours the whole line (quest links etc.); several tags
							// mean highlighted words in base-coloured text - painting everything with the
							// first highlight looks wrong, keep the base colour instead.
							int wrap = lineColors.size() > 1 ? colorRgb : Tags.firstColor(line, colorRgb);
							lzh = "<col=" + Tags.hex(wrap) + ">" + pz + "</col>";
						}
					}
				}
				if (lzh == null && aiFallback)
				{
					lzh = aiLine(Tags.stripCol(line), persist, allowRequests, permit);
				}
				if (lzh != null)
				{
					sb.append(Tags.restoreColors(lzh, lineColors));
					any = true;
				}
				else
				{
					sb.append(line); // leave the original (with real colours) so English stays coloured
					if (WORDY.matcher(Tags.stripCol(line)).find())
					{
						all = false; // a real line is still untranslated (table miss + AI not ready)
						if (collectSource != null)
						{
							missing.record(collectKey(line), collectSource, "", "");
						}
					}
				}
			}
			if (!any)
			{
				return null;
			}
			// Every line that hit was English-only: nothing to draw, leave the widget as the client drew it.
			String img = render(sb.toString(), colorRgb, maxChars, size);
			return img == null ? null : new Rendered(img, all);
		}
		if (collectSource != null && !text.contains("<br>"))
		{
			missing.record(collectKey(text), collectSource, "", "");
		}
		return null;
	}

	/**
	 * Collection form of a UI line: the exact key the lookups use (colours placeholded, styling
	 * stripped) with the local player's name masked, so collected rows are directly usable table keys.
	 * Nearby players' names are masked too (trade / friends-style panels show them in static labels,
	 * and a name list can't know names it has never seen); a nearby name that collides with an
	 * ordinary word over-masks that word - precision over recall, the pipeline can't un-leak a name.
	 */
	private String collectKey(String s)
	{
		String k = Tags.placeholdColors(Tags.stripStyle(s)).trim();
		String name = playerName();
		if (name != null && !name.isEmpty())
		{
			k = k.replace(name, PLAYER_NAME);
		}
		Pattern any = nearbyNamePattern();
		if (any != null)
		{
			k = any.matcher(k).replaceAll(Matcher.quoteReplacement(PLAYER_NAME));
		}
		return k;
	}

	// Tables and live messages disagree on trailing punctuation ("You catch some raw shrimps" in the
	// table vs "...shrimps." in game; label "Sailing:" vs table "Sailing"), so on a miss retry once
	// with it stripped, or with '.' added.
	private String lookupPeriodTolerant(String key, TranslationStore.Category[] order)
	{
		String zh = templateLookup(key, order);
		if (zh != null)
		{
			return zh;
		}
		String t = key.trim();
		if (t.isEmpty())
		{
			return null;
		}
		char last = t.charAt(t.length() - 1);
		if ((last == '.' || last == '!' || last == '?' || last == ':') && !t.endsWith(".."))
		{
			return templateLookup(t.substring(0, t.length() - 1), order);
		}
		if (Character.isLetterOrDigit(last))
		{
			return templateLookup(t + ".", order);
		}
		return null;
	}

	/** AI-translate one line, but only if it is real prose (skip numbers/symbols like "0/1"). */
	private String aiLine(String line, boolean persist)
	{
		return aiLine(line, persist, true, null);
	}

	private String aiLine(String line, boolean persist, boolean allowRequests, AiTranslator.RequestPermit permit)
	{
		String t = line.trim();
		if (!WORDY.matcher(t).find())
		{
			return null;
		}
		return aiTranslate(t, true, persist, allowRequests, permit);
	}

	private String aiTranslate(String query, boolean protectPlayerNames)
	{
		return aiTranslate(query, protectPlayerNames, true);
	}

	private String aiTranslate(String query, boolean protectPlayerNames, boolean persist)
	{
		return aiTranslate(query, protectPlayerNames, persist, true, null);
	}

	private String aiTranslate(String query, boolean protectPlayerNames, boolean persist, boolean allowRequests, AiTranslator.RequestPermit permit)
	{
		String key = TranslationStore.normalize(query);
		if (!protectPlayerNames)
		{
			return allowRequests ? requestAi(key, persist, permit) : ai.cached(key);
		}
		// Cache first: an entry stored under the raw key was translated with nothing to protect, so on a
		// hit for name-free text this is the very entry the protected path would find - reached without
		// paying for name protection at all. Text that does carry a name is keyed on its placeholder form
		// and deliberately falls through to the full path below, so cache keys are unchanged.
		if (ai.cached(key) != null && !hasProtectableName(query))
		{
			return allowRequests ? requestAi(key, persist, permit) : ai.cached(key);
		}
		ProtectedText p = protectDynamicPlayerNames(query);
		String protectedKey = TranslationStore.normalize(p.text);
		String zh = allowRequests ? requestAi(protectedKey, persist, permit) : ai.cached(protectedKey);
		return zh == null ? null : p.restore(zh);
	}

	private String requestAi(String key, boolean persist, AiTranslator.RequestPermit permit)
	{
		return permit == null ? ai.translate(key, persist) : ai.translate(key, persist, permit);
	}

	/** Cheap "does protection change anything?" test, on the client thread. */
	private boolean hasProtectableName(String text)
	{
		Pattern any = nearbyNamePattern();
		return (any != null && any.matcher(text).find())
				|| TOP_THREE_WERE.matcher(text).find()
				|| TOP_CRAB_WAS.matcher(text).find();
	}

	private ProtectedText protectDynamicPlayerNames(String text)
	{
		ProtectedText p = new ProtectedText(text);
		Pattern any = nearbyNamePattern();
		if (any != null)
		{
			// One pass yields the (usually zero) nearby names actually present, instead of matching the
			// whole nearby-player list against the text name by name.
			Matcher m = any.matcher(text);
			while (m.find())
			{
				p.protectName(m.group());
			}
		}
		for (String name : topThreeNames(text))
		{
			p.protectName(name);
		}
		for (String name : topCrabName(text))
		{
			p.protectName(name);
		}
		return p;
	}

	/** Immutable snapshot of the nearby-name alternation and the tick it was built on. */
	private static final class NearbyNames
	{
		static final NearbyNames EMPTY = new NearbyNames(Integer.MIN_VALUE, null);

		final int tick;
		final Pattern any; // alternation over every nearby name, longest first; null when there are none

		NearbyNames(int tick, Pattern any)
		{
			this.tick = tick;
			this.any = any;
		}
	}

	/**
	 * One pattern matching any nearby player's name, rebuilt at most once per game tick. Rebuilding the
	 * list and compiling one Pattern per name on every call was the crowded-place lag: at a busy Grand
	 * Exchange that was ~150 Pattern.compile per untranslated line per frame. Up to a tick of staleness is
	 * harmless - AI translation is asynchronous and lands seconds later anyway.
	 *
	 * <p>Client thread only (reads the player list).
	 */
	private Pattern nearbyNamePattern()
	{
		int tick = client.getTickCount();
		NearbyNames cached = nearby;
		if (cached.tick == tick)
		{
			return cached.any;
		}
		Pattern any = compileNames(currentPlayerNames());
		nearby = new NearbyNames(tick, any);
		return any;
	}

	/** Names are joined longest-first so a name that is a prefix of a longer one can't win over it. */
	private static Pattern compileNames(List<String> names)
	{
		if (names.isEmpty())
		{
			return null;
		}
		StringBuilder sb = new StringBuilder("(?<![A-Za-z0-9_])(?:");
		for (int i = 0; i < names.size(); i++)
		{
			if (i > 0)
			{
				sb.append('|');
			}
			sb.append(Pattern.quote(names.get(i)));
		}
		return Pattern.compile(sb.append(")(?![A-Za-z0-9_])").toString());
	}

	private List<String> currentPlayerNames()
	{
		List<String> names = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		if (client.getLocalPlayer() != null)
		{
			addName(names, seen, client.getLocalPlayer().getName());
		}
		List<Player> players = client.getPlayers();
		if (players == null)
		{
			return names;
		}
		for (Player p : players)
		{
			if (p != null)
			{
				addName(names, seen, p.getName());
			}
		}
		names.sort(Comparator.comparingInt(String::length).reversed());
		return names;
	}

	private static void addName(List<String> names, Set<String> seen, String name)
	{
		if (name == null)
		{
			return;
		}
		String n = name.trim();
		if (!n.isEmpty() && seen.add(n))
		{
			names.add(n);
		}
	}

	private static void addName(List<String> names, String name)
	{
		if (name == null)
		{
			return;
		}
		String n = name.trim();
		if (!n.isEmpty() && !names.contains(n))
		{
			names.add(n);
		}
	}

	private static List<String> topThreeNames(String text)
	{
		List<String> out = new ArrayList<>();
		Matcher m = TOP_THREE_WERE.matcher(text);
		if (!m.find())
		{
			return out;
		}
		for (String part : m.group(2).split("\\s*(?:,|&|\\band\\b)\\s*"))
		{
			String name = part.trim();
			if (looksLikePlayerName(name))
			{
				addName(out, name);
			}
		}
		return out;
	}

	private static List<String> topCrabName(String text)
	{
		List<String> out = new ArrayList<>(1);
		Matcher m = TOP_CRAB_WAS.matcher(text);
		if (m.find())
		{
			String name = m.group(1).trim();
			if (looksLikePlayerName(name))
			{
				out.add(name);
			}
		}
		return out;
	}

	private static boolean looksLikePlayerName(String name)
	{
		int len = name.length();
		return len >= 1 && len <= 12
				&& PLAYER_NAME_CHARS.matcher(name).matches()
				&& HAS_LETTER.matcher(name).find();
	}

	private static final class ProtectedText
	{
		private final Map<String, String> replacements = new LinkedHashMap<>();
		private String text;

		private ProtectedText(String text)
		{
			this.text = text;
		}

		private void protectName(String name)
		{
			if (name == null || name.isEmpty())
			{
				return;
			}
			String placeholder = placeholderFor(name);
			Pattern p = Pattern.compile("(?<![A-Za-z0-9_])" + Pattern.quote(name) + "(?![A-Za-z0-9_])");
			Matcher m = p.matcher(text);
			StringBuffer sb = new StringBuffer();
			boolean found = false;
			while (m.find())
			{
				found = true;
				m.appendReplacement(sb, Matcher.quoteReplacement(placeholder));
			}
			if (found)
			{
				m.appendTail(sb);
				text = sb.toString();
				replacements.putIfAbsent(placeholder, name);
			}
		}

		private String placeholderFor(String name)
		{
			for (Map.Entry<String, String> e : replacements.entrySet())
			{
				if (e.getValue().equals(name))
				{
					return e.getKey();
				}
			}
			return "<osrscn-name-" + replacements.size() + ">";
		}

		private String restore(String zh)
		{
			String out = zh;
			for (Map.Entry<String, String> e : replacements.entrySet())
			{
				out = out.replace(e.getKey(), e.getValue());
			}
			return out;
		}
	}

	/**
	 * Number-templated table lookup; returns the raw Chinese (numbers substituted back) or null. The
	 * input may carry {@code <colNumN>} colour placeholders; numbers inside any {@code <...>} tag are
	 * left alone so those placeholders survive.
	 */
	private String templateLookup(String text, TranslationStore.Category[] order)
	{
		if (text.trim().isEmpty())
		{
			return null;
		}
		// Letter-free text (bare numbers, "31/31", "200!") needs no translation - and looking it up is
		// actively dangerous: the period-tolerant retry once matched a dialogue row "31." -> "31岁。",
		// painting every widget that showed 31. Dialogue lookups use lookupAny, not this path.
		if (!HAS_LETTER.matcher(Tags.stripColorPlaceholders(text)).find())
		{
			return null;
		}
		String playerList = playerListTemplateLookup(text);
		if (playerList != null)
		{
			return playerList;
		}
		List<String> nums = new ArrayList<>();
		String tpl = templatizeNumbers(text, nums);
		// Price lines render from the name table first, so every item is consistent (and beats the older
		// per-item cache entries with mixed wording).
		String zh = priceLineLookup(tpl, order);
		if (zh == null)
		{
			zh = lookupAnyOf(tpl, order);
		}
		if (zh == null)
		{
			zh = syntheticLookup(tpl, order);
		}
		if (zh == null && !nums.isEmpty())
		{
			zh = lookupAnyOf(text, order); // some entries are stored without number placeholders
			if (zh == null)
			{
				zh = syntheticLookup(text, order);
			}
		}
		if (zh == null)
		{
			return null;
		}
		for (int k = 0; k < nums.size(); k++)
		{
			zh = zh.replace("<Num" + k + ">", nums.get(k));
		}
		return zh;
	}

	/**
	 * Render an examine "Price of <item>: GE average <Num0> HA value <Num1>" line from the name table:
	 * the item name is looked up (incl. a leading "<Num> x " quantity), GE/HA wording is fixed, and the
	 * number placeholders are kept for the caller to substitute back. Returns null for non-price lines or
	 * when the item is not in the tables (so the caller falls back to a cached entry or the AI). Ground-item
	 * overhead prices are drawn by another plugin's overlay and are out of scope here.
	 */
	private String priceLineLookup(String text, TranslationStore.Category[] order)
	{
		String plain = Tags.stripColorPlaceholders(text);
		Matcher m = PRICE_LINE.matcher(plain);
		if (!m.matches())
		{
			return null;
		}
		String item = m.group(1).trim();
		String details = m.group(2).trim();
		String qty = null;
		Matcher q = PRICE_QTY.matcher(item);
		if (q.matches())
		{
			qty = q.group(1);
			item = q.group(2).trim();
		}
		String nameZh = lookupAnyOf(item, order);
		if (nameZh == null)
		{
			return null;
		}
		StringBuilder sb = new StringBuilder();
		if (qty != null)
		{
			sb.append(qty).append(" × ");
		}
		sb.append(nameZh).append("价格：");
		boolean any = false;
		Matcher ge = GE_AVERAGE.matcher(details);
		if (ge.find())
		{
			sb.append("GE 均价 ").append(ge.group(1));
			any = true;
		}
		Matcher ha = HA_VALUE.matcher(details);
		if (ha.find())
		{
			if (any)
			{
				sb.append('，');
			}
			sb.append("HA 估值 ").append(ha.group(1));
			any = true;
		}
		Matcher ea = PRICE_EACH.matcher(details);
		if (ea.find())
		{
			sb.append("（每个 ").append(ea.group(1)).append('）');
		}
		return any ? sb.toString() : null;
	}

	private String syntheticLookup(String text, TranslationStore.Category[] order)
	{
		Matcher ge = GE_TRADE_LINE.matcher(text);
		if (ge.matches())
		{
			String zhName = lookupAnyOf(Tags.stripColorPlaceholders(ge.group(3)).trim(), order);
			return zhName == null ? null
					: "大交易所：已完成" + ("buying".equalsIgnoreCase(ge.group(1)) ? "购买" : "出售")
					+ " " + ge.group(2) + " × " + zhName + "。";
		}
		Matcher offer = GE_OFFER_LINE.matcher(text);
		if (offer.matches())
		{
			String zhName = lookupAnyOf(Tags.stripColorPlaceholders(offer.group(3)).trim(), order);
			return zhName == null ? null
					: ("Buy".equalsIgnoreCase(offer.group(1)) ? "购买" : "出售")
					+ "：" + offer.group(2) + " × " + zhName;
		}

		Matcher done = GE_DONE_LINE.matcher(text);
		if (done.matches())
		{
			String zhName = lookupAnyOf(Tags.stripColorPlaceholders(done.group(2)).trim(), order);
			if (zhName == null)
			{
				return null;
			}
			String verb = done.group(1).toLowerCase(java.util.Locale.ROOT);
			String zhVerb = "bought".equals(verb) ? "已购买"
					: "sold".equals(verb) ? "已售出"
					: "buying".equals(verb) ? "购买中" : "出售中";
			return zhVerb + "：" + zhName;
		}

		Matcher quest = QUEST_STATE_LINE.matcher(text);
		if (quest.matches())
		{
			String zhName = lookupAnyOf(quest.group(1).trim(), order);
			String zhState = lookupAnyOf(quest.group(2), order);
			return zhName == null || zhState == null ? null : "任务：" + zhName + "（" + zhState + "）";
		}

		Matcher done2 = QUEST_DONE_LINE.matcher(Tags.stripColorPlaceholders(text).trim());
		if (done2.matches())
		{
			String zhName = lookupAnyOf(done2.group(1).trim(), order);
			return zhName == null ? null : "你已完成任务：" + zhName + "！";
		}

		Matcher congrats = QUEST_DONE_CHAT.matcher(Tags.stripColorPlaceholders(text).trim());
		if (congrats.matches())
		{
			String zhName = lookupAnyOf(congrats.group(1).trim(), order);
			return zhName == null ? null : "恭喜，你完成了一个任务：" + zhName;
		}

		Matcher xp = SKILL_XP_LINE.matcher(Tags.stripColorPlaceholders(text).trim());
		if (xp.matches())
		{
			String zhSkill = lookupAnyOf(xp.group(2), order);
			return zhSkill == null ? null : xp.group(1) + "点" + zhSkill + "经验值";
		}

		Matcher members = MEMBERS_LINE.matcher(text);
		if (members.matches())
		{
			String name = Tags.stripColorPlaceholders(members.group(1)).trim();
			String zhName = lookupAnyOf(name, order);
			return zhName == null ? null : "会员：" + zhName;
		}

		Matcher monster = MONSTER_LINE.matcher(text);
		if (monster.matches())
		{
			String name = Tags.stripColorPlaceholders(monster.group(1)).trim();
			String zhName = lookupAnyOf(name, order);
			return zhName == null ? null : "怪物：" + zhName;
		}

		Matcher requires = REQUIRES_LINE.matcher(text);
		if (!requires.matches())
		{
			return null;
		}
		String[] parts = requires.group(1).split("\\s*,\\s*");
		StringBuilder sb = new StringBuilder("需要：");
		boolean translatedAny = false;
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				sb.append('，');
			}
			String part = parts[i].trim();
			String translated = translateRequirementPart(part, order);
			if (translated != null)
			{
				sb.append(translated);
				translatedAny = true;
			}
			else
			{
				sb.append(part);
			}
		}
		return translatedAny ? sb.toString() : null;
	}

	private String translateRequirementPart(String part, TranslationStore.Category[] order)
	{
		Matcher level = LEVEL_REQUIREMENT.matcher(part);
		if (level.matches())
		{
			String skill = Tags.stripColorPlaceholders(level.group(3)).trim();
			String zhSkill = lookupAnyOf(skill, order);
			if (zhSkill == null)
			{
				return null;
			}
			String open = level.group(1) == null ? "" : level.group(1);
			String close = level.group(4) == null ? "" : level.group(4);
			return open + level.group(2) + "级" + zhSkill + close;
		}

		String clean = Tags.stripColorPlaceholders(part).trim();
		String zh = lookupAnyOf(clean, order);
		return zh == null ? null : zh;
	}

	// "<level> <skill>" inside a diary requirement, e.g. "65 Slayer" -> "65级杀戮者".
	private static final Pattern REQ_SEG_LEVEL = Pattern.compile("^(\\d+)\\s+(.+)$");

	/**
	 * Translate a whole reconstructed journal task (prose, usually not in any table) to plain Chinese:
	 * the translation table first (so a hand-fixed entry wins), then the AI backend when {@code aiFallback}
	 * is on. Returns {@code null} when not translatable right now (table miss + AI off, or AI pending), so
	 * the caller leaves the task in English. Used by the experimental achievement/quest journal rebuild,
	 * which renders the colour-carrying requirement separately (see {@link #translateReqSegment}).
	 */
	public String translateJournalSentence(String plain, boolean aiFallback)
	{
		return translateJournalSentence(plain, aiFallback, "", true);
	}

	/**
	 * @param subCategory provenance tag for collected rows ({@code "skillguide860"} for the group-860
	 *                    reflow), so the reflow pipeline can route by source
	 * @param collect     false while the source frame is still settling: no missing row is written and
	 *                    the AI result stays memory-only, so mid-relayout scrambles never persist
	 */
	public String translateJournalSentence(String plain, boolean aiFallback, String subCategory, boolean collect)
	{
		if (plain == null || plain.trim().isEmpty())
		{
			return "";
		}
		String zh = lookupPeriodTolerant(plain, UI_ORDER);
		if (zh != null)
		{
			return zh;
		}
		// A re-layout can drop the run's leading word(s), so the composed key misses a table entry that
		// hit on the first visit; heal from the known key instead of collecting the drifted variant.
		zh = store.lookupProseDrift(plain);
		if (zh != null)
		{
			return zh;
		}
		// Capture the verbatim reconstructed journal sentence (quest journal / achievement diary) so it
		// can be batch-translated and baked into the tables later. This is the only drift-free source for
		// journal recaps: they are server-sent, absent from both the cache dump and (accurately) the wiki.
		if (collect)
		{
			missing.record(collectKey(plain), "journal", subCategory, "");
		}
		return aiFallback ? aiLine(plain, collect) : null;
	}

	// Sentinel: this requirement segment carries a real name that the AI is still translating, so the
	// whole task should be retried next tick rather than rendered half-translated.
	public static final String REQ_PENDING = "\000PENDING\000";

	/**
	 * Translate one diary requirement segment ("65 Slayer", "Started Desert Treasure I", "Eagles' Peak")
	 * to Chinese, preserving any leading/trailing spaces. Skills become "&lt;level&gt;级&lt;skill&gt;".
	 * Names come from the tables first; missing names fall back to the AI backend when {@code aiFallback}
	 * is on. Returns the segment unchanged when it is punctuation, or a name that can't be translated
	 * (AI off / not in tables); returns {@link #REQ_PENDING} when a name's AI translation is still in
	 * flight, so the caller can retry instead of showing English.
	 */
	public String translateReqSegment(String seg, boolean aiFallback)
	{
		if (seg == null || seg.isEmpty())
		{
			return seg;
		}
		int a = 0;
		int b = seg.length();
		while (a < b && seg.charAt(a) == ' ')
		{
			a++;
		}
		while (b > a && seg.charAt(b - 1) == ' ')
		{
			b--;
		}
		String core = seg.substring(a, b);
		if (core.isEmpty())
		{
			return seg;
		}
		String zh = translateReqCore(core, aiFallback);
		//noinspection StringEquality
		if (zh == REQ_PENDING)
		{
			return REQ_PENDING;
		}
		return zh == null ? seg : seg.substring(0, a) + zh + seg.substring(b);
	}

	/** @return Chinese, {@code null} to leave {@code core} as-is, or {@link #REQ_PENDING} if AI in flight. */
	private String translateReqCore(String core, boolean aiFallback)
	{
		Matcher level = REQ_SEG_LEVEL.matcher(core);
		if (level.matches())
		{
			String skill = level.group(2).trim();
			String zhSkill = reqName(skill, aiFallback);
			//noinspection StringEquality
			if (zhSkill == REQ_PENDING)
			{
				return REQ_PENDING;
			}
			return zhSkill == null ? null : level.group(1) + "级" + zhSkill;
		}
		if (core.startsWith("Started "))
		{
			String quest = core.substring("Started ".length()).trim();
			String zhQuest = reqName(quest, aiFallback);
			//noinspection StringEquality
			if (zhQuest == REQ_PENDING)
			{
				return REQ_PENDING;
			}
			return zhQuest == null ? null : "开始" + zhQuest;
		}
		return reqName(core, aiFallback);
	}

	/** Look a requirement name up in the tables, then AI; {@link #REQ_PENDING} while AI is in flight. */
	private String reqName(String name, boolean aiFallback)
	{
		String zh = lookupAnyOf(name, UI_ORDER);
		if (zh != null)
		{
			return zh;
		}
		if (aiFallback && WORDY.matcher(name).find())
		{
			String ai = aiLine(name, true);
			return ai != null ? ai : REQ_PENDING;
		}
		return null; // punctuation, or no AI: leave as-is
	}

	/**
	 * Replace numbers with {@code <Num0>}, {@code <Num1>}, ... but skip over {@code <...>} tags, so colour
	 * placeholders ({@code <colNum0>}) and {@code <br>} keep their digits.
	 */
	private static String templatizeNumbers(String s, List<String> numsOut)
	{
		StringBuilder out = new StringBuilder(s.length() + 8);
		int i = 0;
		int n = s.length();
		while (i < n)
		{
			char c = s.charAt(i);
			if (c == '<')
			{
				int end = s.indexOf('>', i);
				if (end != -1)
				{
					out.append(s, i, end + 1);
					i = end + 1;
					continue;
				}
			}
			if (Character.isDigit(c))
			{
				Matcher m = NUMBER.matcher(s);
				if (m.find(i) && m.start() == i)
				{
					out.append("<Num").append(numsOut.size()).append('>');
					numsOut.add(m.group());
					i = m.end();
					continue;
				}
			}
			out.append(c);
			i++;
		}
		return out.toString();
	}

	private String playerListTemplateLookup(String text)
	{
		Matcher m = TOP_THREE_WERE.matcher(text);
		if (m.find())
		{
			List<String> names = topThreeNames(text);
			if (names.size() == 3)
			{
				String query = m.replaceFirst(Matcher.quoteReplacement(
						m.group(1) + "[player 1], [player 2], & [player 3]" + m.group(3)));
				String zh = store.lookupAny(query);
				if (zh != null)
				{
					for (int i = 0; i < names.size(); i++)
					{
						String name = names.get(i);
						int n = i + 1;
						zh = zh.replace("[player " + n + "]", name).replace("[player" + n + "]", name);
					}
					return zh;
				}
			}
		}
		m = TOP_CRAB_WAS.matcher(text);
		if (!m.find())
		{
			return null;
		}
		String name = m.group(1).trim();
		if (!looksLikePlayerName(name))
		{
			return null;
		}
		String zh = store.lookupAny("The top crab crusher was [player]" + m.group(2));
		return zh == null ? null : zh.replace("[player]", name);
	}

	// Lowest-priority sweep when the scene's own order misses every table, so a translation filed under a
	// category that order doesn't list still resolves instead of being lost forever. Dialogue tables stay
	// last (experimental dead last) so any curated table the scene already tried keeps priority.
	private static final TranslationStore.Category[] FALLBACK_ALL = {
			TranslationStore.Category.NAME, TranslationStore.Category.INTERFACE,
			TranslationStore.Category.GAME_TEXT, TranslationStore.Category.EXAMINE,
			TranslationStore.Category.SUPPLEMENT, TranslationStore.Category.LVL_UP,
			TranslationStore.Category.ACTIONS, TranslationStore.Category.INVENTORY_ACTIONS,
			TranslationStore.Category.DIALOGUE, TranslationStore.Category.DIALOGUE_EXPERIMENTAL,
	};

	private static boolean inOrder(TranslationStore.Category[] order, TranslationStore.Category c)
	{
		for (TranslationStore.Category o : order)
		{
			if (o == c)
			{
				return true;
			}
		}
		return false;
	}

	private String lookupAnyOf(String key, TranslationStore.Category[] order)
	{
		String k = TranslationStore.normalize(key); // normalize once, not per category
		for (TranslationStore.Category c : order)
		{
			String zh = store.lookupNormalized(c, k);
			if (zh != null)
			{
				return zh;
			}
		}
		// P4: case-insensitive fallback (game text capitalises names the table stores lower-cased)
		String lower = k.toLowerCase();
		for (TranslationStore.Category c : order)
		{
			String zh = store.lookupLower(c, lower);
			if (zh != null)
			{
				return zh;
			}
		}
		// Universal last resort: try every category the scene's order skipped (lowest priority).
		for (TranslationStore.Category c : FALLBACK_ALL)
		{
			if (inOrder(order, c))
			{
				continue;
			}
			String zh = store.lookupNormalized(c, k);
			if (zh == null)
			{
				zh = store.lookupLower(c, lower);
			}
			if (zh != null)
			{
				return zh;
			}
		}
		return null;
	}

	public void clearAiCache()
	{
		ai.clearCache();
	}

	private String playerName()
	{
		if (client.getLocalPlayer() != null)
		{
			return client.getLocalPlayer().getName();
		}
		return null;
	}
}

package com.osrscn.ui;

import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Singleton;

/**
 * Rolling log of recent dialogue lines (NPC and player), shown in the side panel so the player can
 * scroll back and re-read story they clicked past - the core "watch the story" use case.
 */
@Singleton
public class DialogueHistory
{
	private static final int MAX = 300;

	public static final class Entry
	{
		public final String speakerZh; // speaker name in Chinese (or English if untranslated); may be empty
		public final String speakerEn; // speaker name in English; may be empty
		public final String zh;        // translated line, or null if not translated
		public final String en;        // original English line

		Entry(String speakerZh, String speakerEn, String zh, String en)
		{
			this.speakerZh = speakerZh;
			this.speakerEn = speakerEn;
			this.zh = zh;
			this.en = en;
		}
	}

	private final Deque<Entry> entries = new ConcurrentLinkedDeque<>();
	private final AtomicInteger version = new AtomicInteger();

	public void add(String speakerZh, String speakerEn, String zh, String en)
	{
		if (en == null || en.isEmpty())
		{
			return;
		}
		String spZh = speakerZh == null ? "" : speakerZh;
		String spEn = speakerEn == null ? "" : speakerEn;
		Entry last = entries.peekLast();
		if (last != null && en.equals(last.en) && spEn.equals(last.speakerEn))
		{
			return; // same line captured again (dialogue widget re-set): skip the duplicate
		}
		entries.addLast(new Entry(spZh, spEn, zh, en));
		while (entries.size() > MAX)
		{
			entries.pollFirst();
		}
		version.incrementAndGet();
	}

	/** Oldest-first snapshot, for rendering newest at the bottom. */
	public List<Entry> snapshot()
	{
		return new ArrayList<>(entries);
	}

	/** Bumped on every change, so the panel only rebuilds when there is something new. */
	public int version()
	{
		return version.get();
	}

	public void clear()
	{
		entries.clear();
		version.incrementAndGet();
	}
}

package com.osrscn.ui;

import com.osrscn.OsrscnConfig;
import com.osrscn.ToggleService;
import com.osrscn.glyph.GlyphService;
import com.osrscn.hooks.MenuTranslator;
import com.osrscn.translate.TranslationStore;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Objects;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.VarClientInt;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws a translated tooltip near the cursor for the default (left-click) menu entry, so the
 * top-left hover action text is shown in Chinese without rewriting the native UI text.
 */
public class HoverTooltipOverlay extends Overlay
{
	// A part that fell back to English may just be waiting on a glyph sprite upload (one client cycle),
	// so an incomplete result is retried for this many cycles before it is latched.
	private static final int RETRY_CYCLES = 10;

	private final Client client;
	private final TooltipManager tooltipManager;
	private final ToggleService toggle;
	private final OsrscnConfig config;
	private final MenuTranslator menuTranslator;
	private final GlyphService glyph;
	private final TranslationStore store;

	// One-entry memo (only one entry is hovered at a time). Translating costs a full table-lookup
	// pipeline plus a miss-collector write, and render() runs on every drawn frame while the hovered
	// entry almost never changes; misses are memoised too, since the miss path is the expensive one.
	// Client thread only (Overlay#render), so no synchronisation.
	private String memoOption;
	private String memoTarget;
	private MenuAction memoType;
	private int memoSize;
	private String memoFontPath;
	private int memoFontSize;
	private int memoStoreSize;
	private String memoText;      // tooltip to draw, or null for "nothing translated"
	private boolean memoComplete; // false while some part is still English
	private int memoCycle;        // game cycle the memo inputs were first seen at

	@Inject
	HoverTooltipOverlay(Client client, TooltipManager tooltipManager, ToggleService toggle,
			OsrscnConfig config, MenuTranslator menuTranslator, GlyphService glyph, TranslationStore store)
	{
		this.client = client;
		this.tooltipManager = tooltipManager;
		this.toggle = toggle;
		this.config = config;
		this.menuTranslator = menuTranslator;
		this.glyph = glyph;
		this.store = store;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!toggle.isChineseEnabled() || !config.translateMenus() || client.isMenuOpen())
		{
			return null;
		}

		MenuEntry[] entries = client.getMenuEntries();
		if (entries.length == 0)
		{
			return null;
		}
		MenuEntry entry = entries[entries.length - 1];
		String option = entry.getOption();
		String target = entry.getTarget();
		if (option == null || option.isEmpty() || isTrivial(option))
		{
			return null;
		}

		// don't fight the client's own tooltip handling
		int cycle = client.getGameCycle();
		if (client.getVarcIntValue(VarClientInt.TOOLTIP_TIMEOUT) > cycle
				|| client.getVarcIntValue(VarClientInt.TOOLTIP_VISIBLE) == 1)
		{
			return null;
		}

		MenuAction type = entry.getType();
		int size = glyph.smallSize();
		// fontPath/mainFontSize are the settings that trigger GlyphService#reloadFont, which invalidates
		// every cached <img=N>; the table size changes when the store finishes (or grows) its load.
		String fontPath = config.fontPath();
		int fontSize = config.mainFontSize();
		int storeSize = store.size();
		boolean fresh = Objects.equals(option, memoOption)
				&& Objects.equals(target, memoTarget)
				&& type == memoType
				&& size == memoSize
				&& fontSize == memoFontSize
				&& storeSize == memoStoreSize
				&& Objects.equals(fontPath, memoFontPath);
		if (!fresh || (!memoComplete && cycle - memoCycle < RETRY_CYCLES))
		{
			String optZh = menuTranslator.translateOption(option, type, size);
			String tgtZh = (target == null || target.isEmpty()) ? null
					: menuTranslator.translateTarget(target, size);
			String optPart = (optZh != null) ? optZh : option;
			String tgtPart = (tgtZh != null) ? tgtZh : (target == null ? "" : target);
			memoText = (optZh == null && tgtZh == null) ? null
					: (tgtPart.isEmpty() ? optPart : optPart + " " + tgtPart);
			memoComplete = optZh != null && (tgtZh != null || tgtPart.isEmpty());
			if (!fresh)
			{
				memoCycle = cycle;
				memoOption = option;
				memoTarget = target;
				memoType = type;
				memoSize = size;
				memoFontPath = fontPath;
				memoFontSize = fontSize;
				memoStoreSize = storeSize;
			}
		}
		if (memoText == null)
		{
			return null; // nothing translated yet - let the native text stand
		}

		tooltipManager.addFront(new Tooltip(memoText));
		return null;
	}

	private static boolean isTrivial(String option)
	{
		return option.equals("Walk here") || option.equals("Cancel") || option.equals("Continue");
	}
}

package com.osrscn.ui;

import com.osrscn.OsrscnPlugin;
import com.osrscn.glyph.GlyphService;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.ImageUtil;

/**
 * Replaces the login screen banner art with a localised Chinese version, by overriding the sprite
 * the welcome-screen banner widget draws. The image is bundled (credit: RuneLingual); the version /
 * origin line is drawn on in code so the bundled PNG never has to be re-exported.
 */
@Slf4j
@Singleton
public class LoginBanner
{
	private static final String RESOURCE = "/com/osrscn/login_banner_zh.png";

	// Origin line, placed in the empty dark strip below the artwork, which ends about three quarters of
	// the way down and leaves the bottom band clear across the full width.
	//
	// Every measurement is a fraction of the image, never a pixel count: the dev banner is 1952x544 and
	// the released one is 480x134 (shrunk to satisfy the Plugin Hub image check), so hard-coded
	// coordinates draw off-canvas for real users while looking right in a source build - and the drift
	// check whitelists this file, so nothing would have caught it.
	private static final double NOTICE_X_FRAC = 0.025;
	private static final double NOTICE_BASELINE_FRAC = 0.92;
	private static final double NOTICE_SIZE_FRAC = 0.088;
	private static final double NOTICE_MAX_WIDTH_FRAC = 0.62; // shrink rather than run into the art
	private static final Color NOTICE_COLOR = new Color(0xff, 0x98, 0x1f);
	private static final Color NOTICE_SHADOW = new Color(0, 0, 0, 190);
	private static final String NOTICE_TAIL = " 只在 RuneLite 插件库发布，永久免费";

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private GlyphService glyph;

	private SpritePixels sprite;

	public void apply()
	{
		clientThread.invoke(() ->
		{
			SpritePixels s = banner();
			if (s != null)
			{
				client.getWidgetSpriteOverrides().put(InterfaceID.WelcomeScreen.BANNER_ARTCANVAS, s);
			}
		});
	}

	public void remove()
	{
		clientThread.invoke(() ->
				client.getWidgetSpriteOverrides().remove(InterfaceID.WelcomeScreen.BANNER_ARTCANVAS));
	}

	private SpritePixels banner()
	{
		if (sprite != null)
		{
			return sprite;
		}
		try
		{
			BufferedImage img = ImageUtil.loadImageResource(LoginBanner.class, RESOURCE);
			drawNotice(img);
			sprite = ImageUtil.getImageSpritePixels(img, client);
		}
		catch (Exception e)
		{
			log.warn("OSRSCN: failed to load login banner", e);
		}
		return sprite;
	}

	/**
	 * Draw the version / origin line onto the banner, using the plugin's own glyph font so every
	 * character is one the bundled subset covers.
	 */
	private void drawNotice(BufferedImage img)
	{
		int size = Math.max(8, (int) Math.round(img.getHeight() * NOTICE_SIZE_FRAC));
		Font font = glyph.font(size);
		if (font == null)
		{
			return;
		}
		int x = (int) Math.round(img.getWidth() * NOTICE_X_FRAC);
		int baseline = (int) Math.round(img.getHeight() * NOTICE_BASELINE_FRAC);
		int maxWidth = (int) Math.round(img.getWidth() * NOTICE_MAX_WIDTH_FRAC);
		int shadow = Math.max(1, size / 24);
		String text = "OSRSCN " + OsrscnPlugin.versionLabel() + NOTICE_TAIL;
		Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setFont(font);
			int width = g.getFontMetrics().stringWidth(text);
			if (width > maxWidth)
			{
				g.setFont(font.deriveFont(font.getSize2D() * maxWidth / width));
			}
			g.setColor(NOTICE_SHADOW);
			g.drawString(text, x + shadow, baseline + shadow);
			g.setColor(NOTICE_COLOR);
			g.drawString(text, x, baseline);
		}
		finally
		{
			g.dispose();
		}
	}
}

