		add(display, BorderLayout.CENTER);

		searchDebounce = new Timer(180, e -> runSearch());
		searchDebounce.setRepeats(false);
		translatePoll = new Timer(300, e -> pollTranslate());
		refreshTimer = new Timer(1000, e -> refresh());
	}

